    // ─────────────── ۱: جنایت و مکافات ───────────────
    private fun story1() = StoryContent(
        storyId = "adv_crime_punishment",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Student in Petersburg", titlePersian = "دانشجوی پترزبورگ",
                paragraphs = listOf(
                    StoryParagraph("At the beginning of July, in an exceptionally hot summer, a young man named Rodion Romanovich Raskolnikov emerged from his tiny garret in a dilapidated tenement house in the vicinity of Sennaya Square and walked slowly, as though uncertain of his purpose, toward the bridge over the canal.", "در آغاز ماه ژوئیه، در تابستانی به‌طرز استثنایی گرم، جوانی به نام رودیون رومانوویچ راسکولنیکوف از اتاق زیرشیروانی محقر خود در ساختمانی فرسوده در حوالی میدان سنایا بیرون آمد و به‌آرامی، گویی از هدفش مطمئن نبود، به سمت پل روی کانال راه افتاد."),
                    StoryParagraph("He had been avoiding his landlady for weeks, not because she had been unkind to him, but because he could no longer endure the sound of her voice asking for the rent he did not have.", "هفته‌ها بود که از صاحب‌خانه‌اش پرهیز می‌کرد، نه به این دلیل که او با او بدرفتاری کرده بود، بلکه چون دیگر نمی‌توانست صدای او را که اجاره‌ای را که نداشت طلب می‌کرد تحمل کند."),
                    StoryParagraph("His garret was so low that a man of average height could not stand upright in it, and so narrow that it seemed more like a cupboard than a human dwelling.", "اتاق زیرشیروانی‌اش آنقدر کوتاه بود که مردی با قد متوسط نمی‌توانست در آن راست بایستد و آنقدر باریک بود که بیشتر شبیه گنجه‌ای به نظر می‌رسید تا محل سکونت یک انسان."),
                    StoryParagraph("The yellow wallpaper was peeling off the walls in long, ragged strips, and the smell of dust and mildew hung in the air like a permanent accusation.", "کاغذ دیواری زرد به‌شکل نوارهای بلند و ژنده از دیوارها کنده می‌شد و بوی گرد و کپک مثل اتهامی دائمی در هوا معلق بود."),
                    StoryParagraph("He had once been a brilliant law student at the university, admired by his professors for his sharp analytical mind and by his classmates for his proud, uncompromising spirit.", "او زمانی دانشجوی درخشان حقوق در دانشگاه بود که استادانش به خاطر ذهن تحلیلی تیزش و هم‌کلاسی‌هایش به خاطر روح مغرور و سازش‌ناپذیرش تحسینش می‌کردند."),
                    StoryParagraph("But poverty — that slow, grinding poverty that wears away a man's dignity as water wears away stone — had forced him to abandon his studies more than a year ago.", "اما فقر — همان فقر آهسته و فرساینده‌ای که کرامت انسان را می‌ساید همان‌طور که آب سنگ را می‌ساید — او را بیش از یک سال پیش مجبور به رها کردن تحصیلش کرده بود."),
                    StoryParagraph("His clothes had become so worn and threadbare that he was ashamed to appear on the street in daylight; his boots had holes through which his bare feet showed.", "لباس‌هایش آنقدر فرسوده و ژنده شده بودند که در روشنایی روز از ظاهر شدن در خیابان خجالت می‌کشید؛ چکمه‌هایش سوراخ‌هایی داشتند که پاهای برهنه‌اش از آن‌ها بیرون می‌زد."),
                    StoryParagraph("He had eaten almost nothing for two full days, and the hunger had transformed into a strange, feverish clarity of mind that both terrified and exhilarated him.", "تقریباً دو روز کامل هیچ نخورده بود و گرسنگی به وضوح ذهنی عجیب و تب‌آلودی تبدیل شده بود که هم وحشتزده‌اش می‌کرد و هم سرخوشش می‌ساخت."),
                    StoryParagraph("His mother, Pulcheria Alexandrovna, sent him what little money she could scrape together from her meager pension, and his sister Dunya had taken a position as a governess to contribute to his support.", "مادرش، پولخریا الکساندرونا، هر پول اندکی که می‌توانست از حقوق ناچیز بازنشستگی‌اش جمع کند برایش می‌فرستاد و خواهرش دونیا برای کمک به حمایت از او شغل معلمی سرخانه را پذیرفته بود."),
                    StoryParagraph("The thought of their sacrifice was an unbearable weight upon his conscience, a weight that pressed down upon him constantly and made every breath feel like a reproach.", "فکر فداکاری آن‌ها وزنی تحمل‌ناپذیر بر وجدانش بود، وزنی که مدام بر او فشار می‌آورد و هر نفسی را مثل سرزنشی حس می‌کرد."),
                    StoryParagraph("It was during this period of suffering that Raskolnikov had begun to formulate a theory, a theory that had taken root in his mind like a poisonous weed and had slowly strangled every other thought.", "در همین دوره رنج بود که راسکولنیکوف شروع به شکل دادن نظریه‌ای کرده بود، نظریه‌ای که مثل علف هرز سمی در ذهنش ریشه دوانده و آهسته هر فکر دیگری را خفه کرده بود."),
                    StoryParagraph("According to this theory, all men were divided into two categories: the ordinary and the extraordinary, the common and the exceptional.", "طبق این نظریه، همه مردان به دو دسته تقسیم می‌شدند: معمولی و استثنایی، عادی و برجسته."),
                    StoryParagraph("Ordinary men, the vast majority of humanity, were obliged to live in submission, to obey the laws and customs of society, to accept their mediocrity without complaint.", "مردان معمولی، اکثریت قاطع بشریت، موظف بودند در تسلیم زندگی کنند، از قوانین و آداب جامعه اطاعت کنند، متوسط بودن خود را بدون شکایت بپذیرند."),
                    StoryParagraph("But extraordinary men — men like Napoleon, like Lycurgus, like Solon — were different; they had the right, even the duty, to transgress the moral and legal boundaries that confined ordinary men.", "اما مردان استثنایی — مردانی مثل ناپلئون، مثل لیکورگوس، مثل سولون — متفاوت بودند؛ آن‌ها حق، حتی وظیفه داشتند از مرزهای اخلاقی و قانونی‌ای که مردان معمولی را محدود می‌کرد عبور کنند."),
                    StoryParagraph("Such men, Raskolnikov argued in the article he had published years earlier, could commit any crime — even murder — if it served a higher purpose, if it brought new truths to humanity.", "راسکولنیکوف در مقاله‌ای که سال‌ها پیش منتشر کرده بود استدلال می‌کرد که چنین مردانی می‌توانند هر جنایتی — حتی قتل — مرتکب شوند اگر به هدفی برتر خدمت کند، اگر حقایق جدیدی برای بشریت بیاورد."),
                    StoryParagraph("The crime itself, he reasoned, was not really a crime; it was merely the removal of an obstacle that stood in the way of greatness.", "او استدلال می‌کرد که جنایت به خودی خود واقعاً جنایت نیست؛ فقط حذف مانعی است که سر راه عظمت ایستاده."),
                    StoryParagraph("And if such a man felt no remorse afterward, if he simply stepped over the body and continued on his way, then he proved himself to be one of the extraordinary ones.", "و اگر چنین مردی بعد از آن احساس پشیمانی نمی‌کرد، اگر به سادگی از روی جسد عبور می‌کرد و به راهش ادامه می‌داد، آنگاه ثابت می‌کرد که یکی از استثنایی‌هاست."),
                    StoryParagraph("For months, this theory had consumed Raskolnikov's mind, and for months, he had been tormented by a single, terrible question: Was he an extraordinary man?", "ماه‌ها این نظریه ذهن راسکولنیکوف را بلعیده بود و ماه‌ها بود که توسط یک پرسش واحد و هولناک شکنجه می‌شد: آیا او مردی استثنایی بود؟"),
                    StoryParagraph("Did he have the right — the terrible, self-granted right — to step over the moral law, or was he merely a common creature, a trembling slave, a louse?", "آیا او حق داشت — همان حق هولناک و خودداده — که از قانون اخلاقی عبور کند، یا فقط موجودی معمولی بود، برده‌ای لرزان، شپشی؟"),
                    StoryParagraph("To answer this question, he had decided, he would have to test himself, and the test he had chosen was a dreadful one.", "تصمیم گرفته بود که برای پاسخ دادن به این پرسش باید خودش را بیازماید و آزمونی که انتخاب کرده بود، آزمونی هولناک بود."),
                    StoryParagraph("He would kill an old pawnbroker named Alyona Ivanovna, a woman whom he had visited several times to pawn his few remaining possessions.", "او پیرزنی رباخوار به نام آلیونا ایوانوونا را می‌کشت، زنی که چندین بار برای گرو گذاشتن آخرین دارایی‌هایش به دیدنش رفته بود."),
                    StoryParagraph("Alyona was small, dry, and mean-spirited, with sharp, malicious eyes and a neck like a chicken's leg wrapped in flannel.", "آلیونا کوچک، خشک و بدخواه بود، با چشمانی تیز و شیطانی و گردنی مثل پای مرغی پیچیده در فلانل."),
                    StoryParagraph("She was sixty years old, cruel, greedy, and utterly without compassion; she lent money to desperate people at interest rates that were little better than robbery.", "او شصت ساله بود، بی‌رحم، حریص و کاملاً بی‌ترحم؛ به افراد درمانده با نرخ بهره‌ای پول قرض می‌داد که کمی بهتر از دزدی بود."),
                    StoryParagraph("Her sister Lizaveta, a gentle, simple-minded woman of thirty-five, lived with her as a virtual slave, doing all the housework and enduring all the abuse.", "خواهرش لیزاویتا، زنی ملایم و ساده‌دل سی و پنج ساله، به‌عنوان برده‌ای مجازی با او زندگی می‌کرد، تمام کارهای خانه را انجام می‌داد و تمام آزارها را تحمل می‌کرد."),
                    StoryParagraph("Alyona's death, Raskolnikov told himself, would be a blessing to countless people who suffered under her cruelty.", "راسکولنیکوف به خودش می‌گفت که مرگ آلیونا برای بی‌شمار افرادی که زیر ظلمش رنج می‌بردند برکت خواهد بود."),
                    StoryParagraph("Her money, which she hoarded in her filthy apartment and never used for any good purpose, could be used to help the poor, to fund education, to bring about a new era of justice.", "پولش، که در آپارتمان کثیفش انبار کرده بود و هرگز برای هدف خوبی استفاده نمی‌کرد، می‌توانست برای کمک به فقرا، تأمین هزینه آموزش و آوردن عصری جدید از عدالت استفاده شود."),
                    StoryParagraph("The arithmetic, he assured himself, was simple: one worthless, cruel life exchanged for hundreds of lives saved, for countless futures improved.", "او به خودش اطمینان می‌داد که حساب ساده است: یک زندگی بی‌ارزش و بی‌رحم در ازای صدها زندگی نجات‌یافته، در ازای آینده‌های بی‌شمار بهبودیافته."),
                    StoryParagraph("But every time he tried to convince himself with these arguments, a small, honest voice deep inside him whispered that he was lying, that all this reasoning was merely a way to justify what he wanted to do.", "اما هر بار که تلاش می‌کرد خودش را با این استدلال‌ها قانع کند، صدایی کوچک و صادق در عمق درونش زمزمه می‌کرد که دروغ می‌گوید، که تمام این استدلال‌ها فقط راهی برای توجیه کاری بود که می‌خواست بکند."),
                    StoryParagraph("For six weeks, he had been planning the murder with a meticulousness that bordered on obsession.", "شش هفته بود که با دقتی که به وسواس مرزی می‌زد قتل را نقشه می‌کشید."),
                    StoryParagraph("He had memorized the layout of Alyona's apartment, had noted where she kept her keys, where she stored her money and her jewels, how many steps led from her door to the street.", "او نقشه آپارتمان آلیونا را حفظ کرده بود، توجه کرده بود کلیدهایش را کجا نگه می‌دارد، پول و جواهراتش را کجا ذخیره می‌کند، چند قدم از درش به خیابان است."),
                    StoryParagraph("He had even prepared a loop of fabric to carry the axe under his coat, so that its handle would not be visible when he walked.", "او حتی حلقه‌ای از پارچه آماده کرده بود تا تبر را زیر کتش حمل کند، تا دسته‌اش وقتی راه می‌رود دیده نشود."),
                    StoryParagraph("One afternoon, while wandering through the Hay Market, he overheard a conversation that changed everything.", "یک بعدازظهر، در حال پرسه زدن در بازار علف، گفت‌وگویی شنید که همه چیز را عوض کرد."),
                    StoryParagraph("Two young students were sitting in a tavern, and one of them was saying, quite casually, that killing Alyona Ivanovna would be a perfectly justifiable act.", "دو دانشجوی جوان در میخانه‌ای نشسته بودند و یکی از آن‌ها کاملاً اتفاقی می‌گفت کشتن آلیونا ایوانوونا عملی کاملاً قابل توجیه خواهد بود."),
                    StoryParagraph("The student argued, with a logic almost identical to Raskolnikov's own, that Alyona was a useless, wicked woman whose death would harm no one and benefit many.", "دانشجو با منطقی تقریباً یکسان با منطق خود راسکولنیکوف استدلال می‌کرد که آلیونا زنی بی‌فایده و پلید است که مرگش به کسی آسیب نمی‌رساند و به بسیاری سود می‌بخشد."),
                    StoryParagraph("Raskolnikov stood frozen, listening, and it felt to him as if fate itself had spoken through the mouths of these two strangers, confirming the terrible plan that had been forming in his mind.", "راسکولنیکوف یخ‌زده ایستاد و گوش داد و به نظرش رسید که خود تقدیر از دهان این دو غریبه سخن گفته و نقشه هولناکی که در ذهنش شکل گرفته بود را تأیید کرده است."),
                    StoryParagraph("He walked home in a daze, and when he reached his garret, he threw himself onto his broken sofa and lay there for hours, staring at the ceiling, while his mind raced with ideas that both terrified and fascinated him.", "گیج به خانه رفت و وقتی به زیرشیروانی‌اش رسید، خود را روی مبل شکسته‌اش انداخت و ساعت‌ها آنجا دراز کشید و به سقف خیره شد، در حالی که ذهنش با ایده‌هایی می‌دوید که هم وحشتزده‌اش می‌کرد و هم مجذوبش."),
                    StoryParagraph("That evening, as the shadows of the city lengthened and the gas lamps were lit one by one, Raskolnikov made his decision.", "آن عصر، همان‌طور که سایه‌های شهر بلند می‌شد و چراغ‌های گازی یکی‌یکی روشن می‌شدند، راسکولنیکوف تصمیمش را گرفت."),
                    StoryParagraph("He would kill Alyona Ivanovna tomorrow evening, and he would prove to himself, once and for all, that he was one of the extraordinary ones, that he had the right.", "او فردا عصر آلیونا ایوانوونا را می‌کشت و یک بار برای همیشه به خودش ثابت می‌کرد که یکی از استثنایی‌هاست، که حق دارد."),
                    StoryParagraph("He did not sleep that night; he lay awake, listening to the sounds of the city, and he watched the dawn creep slowly across the sky, and he felt strangely calm, as if he had already crossed a line from which there was no return.", "آن شب نخوابید؛ بیدار دراز کشید، به صداهای شهر گوش داد و تماشا کرد که سحر آهسته در آسمان می‌خزد و به‌طرز عجیبی آرام حس کرد، گویی از قبل از خطی عبور کرده که بازگشتی از آن نیست."),
                    StoryParagraph("The next day passed in a blur of feverish preparations and unbearable waiting.", "روز بعد در تاری از آماده‌سازی‌های تب‌آلود و انتظار تحمل‌ناپذیر گذشت."),
                    StoryParagraph("He rehearsed every step of the plan in his mind until it felt inevitable, until it felt almost familiar, until it felt as though he had done it a thousand times before.", "او هر قدم نقشه را در ذهنش مرور کرد تا وقتی اجتناب‌ناپذیر به نظر رسید، تا وقتی تقریباً آشنا به نظر رسید، تا وقتی حس شد که هزار بار پیش انجامش داده است."),
                    StoryParagraph("And then, at exactly six o'clock in the evening, he put the axe in his coat, slipped out of his building, and walked quickly toward the house of Alyona Ivanovna.", "و بعد، درست ساعت شش عصر، تبر را در کتش گذاشت، از ساختمانش بیرون خزید و سریع به سمت خانه آلیونا ایوانوونا راه افتاد."),
                    StoryParagraph("As he climbed the dark, narrow staircase to her apartment, he could hear his own heart beating so loudly that he was certain everyone in the building must hear it too.", "در حالی که از پله‌های تاریک و باریک به آپارتمانش بالا می‌رفت، می‌توانست صدای قلب خودش را چنان بلند بشنود که مطمئن بود همه اهل ساختمان هم می‌شنوند."),
                    StoryParagraph("His hands were cold and clammy, and his legs felt weak beneath him, as if his body already knew, on some deep and primitive level, what his mind was still refusing to accept.", "دست‌هایش سرد و عرق‌آلود بود و پاهایش زیرش سست می‌شد، گویی بدنش در سطحی عمیق و بدوی از قبل می‌دانست آنچه ذهنش هنوز از پذیرشش سر باز می‌زد."),
                    StoryParagraph("He paused on the landing to catch his breath, and for a brief, agonizing moment, he considered turning around and going home.", "روی پاگرد توقف کرد تا نفس بگیرد و برای لحظه‌ای کوتاه و عذاب‌آور، به بازگشت و رفتن به خانه فکر کرد."),
                    StoryParagraph("But the thought of retreating, of returning to his miserable garret, of spending the rest of his life wondering whether he had been a coward or a hero — this thought was more unbearable than any crime.", "اما فکر عقب‌نشینی، فکر بازگشت به زیرشیروانی رقت‌انگیزش، فکر گذراندن بقیه عمرش در حیرت از اینکه ترسو بوده یا قهرمان — این فکر از هر جنایتی تحمل‌ناپذیرتر بود."),
                    StoryParagraph("And so he continued up the stairs, toward the door of Alyona Ivanovna, toward the moment that would define the rest of his life.", "و بنابراین به بالا رفتن از پله‌ها ادامه داد، به سمت در آلیونا ایوانوونا، به سمت لحظه‌ای که بقیه زندگی‌اش را تعریف می‌کرد.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Murder", titlePersian = "قتل",
                paragraphs = listOf(
                    StoryParagraph("Alyona Ivanovna opened the door and peered out at him with her usual suspicious, mistrustful expression, her small, wicked eyes gleaming in the dim light of the corridor.", "آلیونا ایوانوونا در را باز کرد و مثل همیشه با حالت مشکوک و بی‌اعتمادش به بیرون نگاه کرد، چشمان کوچک و شیطانی‌اش در نور کم راهرو می‌درخشیدند."),
                    StoryParagraph("The apartment was cramped and cluttered, filled with old furniture and strange objects, and it smelled of dust and incense and something else — something unclean, something rotten, something that seemed to cling to the very air.", "آپارتمان تنگ و درهم بود، پر از مبلمان قدیمی و اشیای عجیب، و بوی گرد و بخور می‌داد و چیز دیگری — چیزی ناپاک، چیزی پوسیده، چیزی که به نظر می‌رسید به خود هوا می‌چسبد."),
                    StoryParagraph("A single candle burned on the table, casting long, dancing shadows on the peeling walls, and the whole room felt as though it belonged to another era, another century, another world entirely.", "یک شمع روی میز می‌سوخت و سایه‌های بلند و رقصنده روی دیوارهای کنده‌شده می‌انداخت و تمام اتاق حس می‌شد که به عصری دیگر، قرنی دیگر، دنیایی کاملاً دیگر تعلق دارد."),
                    StoryParagraph("Raskolnikov forced his voice to remain steady as he told her that he had brought another item to pawn.", "راسکولنیکوف صدایش را به‌زور ثابت نگه داشت همان‌طور که به او گفت چیز دیگری برای گرو گذاشتن آورده است."),
                    StoryParagraph("He pulled a small silver cigarette case from his pocket — a memento from his student days — and held it out to her.", "او جعبه سیگار نقره‌ای کوچکی از جیبش بیرون کشید — یادگاری از روزهای دانشجویی‌اش — و به سمتش گرفت."),
                    StoryParagraph("The old woman took it greedily, as she always did, and turned it over in her hands, examining it carefully with her sharp, calculating eyes.", "پیرزن مثل همیشه حریصانه آن را گرفت و در دستانش چرخاند و با چشمان تیز و حسابگرش با دقت بررسی‌اش کرد."),
                    StoryParagraph("She weighed it in her palm, calculating its value with the precision of a woman who had spent her entire life measuring the worth of other people's possessions.", "او در کف دستش وزنش کرد و ارزشش را با دقتی محاسبه کرد که زنی صرف کرده بود که تمام عمرش را صرف سنجش ارزش دارایی‌های دیگران کرده بود."),
                    StoryParagraph("'It is not worth much,' she muttered, 'but I will give you what I can.'", "زیر لب گفت: «ارزش زیادی ندارد، اما هر چه بتوانم می‌دهم.»"),
                    StoryParagraph("And then, as she turned toward the window to examine the case more closely, she made the fatal mistake of turning her back to him.", "و بعد، همان‌طور که به سمت پنجره می‌چرخید تا جعبه را دقیق‌تر بررسی کند، اشتباه مرگبارش را کرد و پشتش را به او کرد."),
                    StoryParagraph("For one long, terrible moment, Raskolnikov stood frozen, staring at the back of her head, at the greasy grey hair twisted into a tight knot, at the thin, wrinkled neck that seemed so fragile, so vulnerable, so human.", "برای یک لحظه طولانی و هولناک، راسکولنیکوف یخ‌زده ایستاد و به پشت سرش خیره شد، به موهای خاکستری چرب که به گره‌ای محکم پیچیده شده بودند، به گردن نازک و چین‌دار که اینقدر شکننده، اینقدر آسیب‌پذیر، اینقدر انسانی به نظر می‌رسید."),
                    StoryParagraph("He remembered, in that moment, a strange detail from his childhood: a dream he had once had about a horse being beaten to death by a crowd of drunken peasants.", "در آن لحظه جزئیات عجیبی از کودکی‌اش را به یاد آورد: خوابی که یک بار دیده بود درباره اسبی که توسط جمعی از دهقانان مست تا مرگ کتک می‌خورد."),
                    StoryParagraph("He had woken from that dream in tears, and his mother had tried to comfort him, but even then, even as a small boy, he had understood something terrible about the world.", "او از آن خواب گریان بیدار شده بود و مادرش تلاش کرده بود دلداری‌اش دهد، اما حتی آنوقت، حتی به عنوان پسربچه‌ای کوچک، چیز هولناکی درباره دنیا فهمیده بود."),
                    StoryParagraph("And now, standing in this cramped, suffocating room, with an axe hidden under his coat and an old woman's back turned toward him, he understood that understanding was not enough.", "و حالا، در این اتاق تنگ و خفه‌کننده ایستاده، با تبری زیر کتش پنهان و پشت پیرزنی به سمتش برگشته، فهمید که فهمیدن کافی نیست."),
                    StoryParagraph("He pulled the axe from his coat with hands that trembled so violently he thought he might drop it.", "او با دستانی که آنقدر شدید می‌لرزیدند که فکر کرد ممکن است بیفتد، تبر را از کتش بیرون کشید."),
                    StoryParagraph("And then, before he could think, before he could hesitate, before he could change his mind, he brought the axe down upon the old woman's head with all the strength he possessed.", "و بعد، پیش از آنکه بتواند فکر کند، پیش از آنکه بتواند تردید کند، پیش از آنکه بتواند نظرش را عوض کند، تبر را با تمام قدرتی که داشت بر سر پیرزن فرود آورد."),
                    StoryParagraph("Alyona Ivanovna collapsed to the floor without a sound, without a cry, without even a sigh — as if the blow had simply erased her, as if she had never been more than a shadow.", "آلیونا ایوانوونا بی‌صدا روی زمین فرو افتاد، بدون فریاد، بدون حتی آه — گویی ضربه به سادگی پاکش کرده بود، گویی هرگز چیزی بیش از سایه‌ای نبوده است."),
                    StoryParagraph("Raskolnikov stood over her for a moment, breathing hard, staring at the blood that had begun to spread slowly across the floorboards beneath her head.", "راسکولنیکوف لحظه‌ای بالای سرش ایستاد، به‌سختی نفس می‌کشید و به خونی خیره شد که آهسته زیر سرش روی تخته‌های کف شروع به پخش شدن کرده بود."),
                    StoryParagraph("He felt nothing at that moment, no guilt, no horror, no remorse — only a strange, cold emptiness, as if the part of him that could feel such things had been switched off entirely.", "در آن لحظه هیچ حس نکرد، نه گناه، نه وحشت، نه پشیمانی — فقط خالی‌بودنی عجیب و سرد، گویی بخشی از او که می‌توانست چنین چیزهایی را حس کند کاملاً خاموش شده بود."),
                    StoryParagraph("He then rushed to the bedroom to look for her keys, moving quickly and silently, his hands searching the room with a desperate, mechanical precision.", "سپس به اتاق خواب هجوم برد تا کلیدهایش را پیدا کند، سریع و بی‌صدا حرکت می‌کرد و دست‌هایش با دقتی ناامیدانه و ماشینی اتاق را می‌گشتند."),
                    StoryParagraph("He found a small purse full of banknotes under her pillow, and he stuffed it into his pocket without counting, and he was just about to leave when he heard a soft sound behind him.", "کیف کوچکی پر از اسکناس زیر بالشش پیدا کرد و بدون شمردن آن را در جیبش فرو کرد و درست داشت می‌رفت که صدای ملایمی پشت سرش شنید."),
                    StoryParagraph("He turned around slowly, and there, in the doorway, stood Lizaveta, Alyona's gentle, innocent sister, holding a bundle of clothes in her arms, staring at the dead body of her sister with wide, horrified eyes.", "آهسته برگشت و آنجا، در چارچوب در، لیزاویتا ایستاده بود، خواهر ملایم و بی‌گناه آلیونا، بقچه‌ای لباس در آغوش داشت و با چشمانی گشاد و وحشت‌زده به جسد خواهرش خیره شده بود."),
                    StoryParagraph("For one long, agonizing moment, neither of them moved.", "برای یک لحظه طولانی و عذاب‌آور، هیچ‌کدام تکان نخوردند."),
                    StoryParagraph("Lizaveta was too terrified to scream, and Raskolnikov was frozen, unable to decide what to do, unable even to think clearly.", "لیزاویتا آنقدر وحشت‌زده بود که نمی‌توانست فریاد بزند و راسکولنیکوف یخ‌زده بود و نمی‌توانست تصمیم بگیرد چه کند، حتی نمی‌توانست واضح فکر کند."),
                    StoryParagraph("Then, in a sudden movement that he himself did not fully understand, he raised the axe again and brought it down upon Lizaveta's head, killing her as well.", "سپس، در حرکتی ناگهانی که خودش هم کاملاً نمی‌فهمید، تبر را دوباره بالا برد و بر سر لیزاویتا فرود آورد و او را نیز کشت."),
                    StoryParagraph("The moment it was done, he felt a wave of horror sweep through him — not for the old woman, whom he had convinced himself deserved to die, but for the young, innocent sister whose only crime had been to enter the room at the wrong moment.", "همان لحظه که انجام شد، موجی از وحشت او را فرا گرفت — نه برای پیرزن، که خودش را قانع کرده بود سزاوار مرگ است، بلکه برای خواهر جوان و بی‌گناهی که تنها گناهش این بود که در لحظه اشتباه وارد اتاق شده بود."),
                    StoryParagraph("He stood there, shaking, staring at the two bodies on the floor, and he realized with a terrible clarity that nothing would ever be the same again, that he had crossed a line from which there was no return.", "آنجا ایستاد، می‌لرزید و به دو جسد روی زمین خیره شد و با وضوحی هولناک دریافت که دیگر هیچ چیز مثل قبل نخواهد بود، که از خطی عبور کرده که بازگشتی از آن نیست."),
                    StoryParagraph("He forced himself to move, and he quickly searched the apartment for anything valuable, taking money, jewelry, and a few small items, though his hands were trembling so badly that he dropped more than he collected.", "خودش را مجبور به حرکت کرد و سریع آپارتمان را برای هر چیز باارزشی گشت، پول، جواهرات و چند چیز کوچک برداشت، هرچند دست‌هایش آنقدر بد می‌لرزیدند که بیشتر از آنکه جمع کند، می‌انداخت."),
                    StoryParagraph("He then went to the kitchen to wash the blood from his hands and the axe, but the water was cold and rusty, and the blood clung to his skin like a stain that would never come off.", "سپس به آشپزخانه رفت تا خون را از دست‌ها و تبرش بشوید، اما آب سرد و زنگ‌زده بود و خون مثل لکه‌ای که هرگز پاک نمی‌شد به پوستش چسبیده بود."),
                    StoryParagraph("Just as he was finishing, he heard footsteps on the stairs outside, and his blood ran cold, because he knew that if someone found him here, everything would be over.", "درست وقتی داشت تمام می‌کرد، صدای قدم‌هایی از پله‌های بیرون شنید و خونش یخ کرد، چون می‌دانست اگر کسی او را اینجا پیدا کند، همه چیز تمام است."),
                    StoryParagraph("He slipped out of the apartment and hid in an empty room on the same floor, pressing himself against the wall and holding his breath while two men entered Alyona's flat and began to cry out in horror at what they found.", "از آپارتمان بیرون خزید و در اتاقی خالی در همان طبقه پنهان شد، خودش را به دیوار فشار داد و نفسش را نگه داشت، در حالی که دو مرد وارد آپارتمان آلیونا شدند و با وحشت از آنچه یافتند فریاد کشیدند."),
                    StoryParagraph("For what felt like an eternity, he crouched in the darkness, listening to the men's panicked voices, hearing them run down the stairs to fetch help, knowing that he had only a few seconds to escape.", "برای مدتی که به نظر ابدیت می‌رسید، در تاریکی خمیده ماند و به صداهای هراس‌زده آن مردان گوش داد، شنید که برای آوردن کمک از پله‌ها پایین دویدند و می‌دانست که فقط چند ثانیه برای فرار دارد."),
                    StoryParagraph("When the coast was clear, he ran down the stairs and out into the street, and he walked quickly through the dark alleys of the city, keeping his head down, trying to look like an ordinary man on an ordinary errand.", "وقتی راه خالی شد، از پله‌ها پایین دوید و به خیابان زد و سریع از میان کوچه‌های تاریک شهر گذشت، سرش را پایین گرفته بود و تلاش می‌کرد مثل مردی معمولی در کاری معمولی به نظر برسد."),
                    StoryParagraph("But his legs were shaking, his heart was pounding, and every shadow seemed to him to be a policeman, every voice a witness, every step behind him the sound of the law closing in.", "اما پاهایش می‌لرزید، قلبش می‌کوبید و هر سایه برایش پلیسی به نظر می‌رسید، هر صدایی شاهدی، هر قدمی پشت سرش صدای قانونی که نزدیک می‌شد."),
                    StoryParagraph("When he finally reached his own building, he climbed the stairs as quietly as he could, entered his room, and locked the door behind him with trembling hands.", "وقتی بالاخره به ساختمان خودش رسید، تا حد امکان بی‌صدا از پله‌ها بالا رفت، وارد اتاقش شد و با دستانی لرزان در را پشت سرش قفل کرد."),
                    StoryParagraph("He then threw himself onto his sofa and lay there, fully clothed, shaking, unable to think, unable to move, unable even to close his eyes, because every time he did, he saw the two bodies on the floor.", "سپس خود را روی مبلش انداخت و همان‌جا با لباس دراز کشید، می‌لرزید، نمی‌توانست فکر کند، نمی‌توانست حرکت کند، حتی نمی‌توانست چشمانش را ببندد، چون هر بار که می‌بست، دو جسد روی زمین را می‌دید."),
                    StoryParagraph("He had hidden the stolen items under a loose stone in an inner courtyard on the way home, and now he realized, with a strange and bitter clarity, that he had not even looked at them, so great had been his horror.", "اشیا دزدیده‌شده را در راه بازگشت زیر سنگی لق در حیاطی داخلی پنهان کرده بود و حالا با وضوحی عجیب و تلخ دریافت که حتی به آن‌ها نگاه هم نکرده بود، چنان وحشتش زیاد بود."),
                    StoryParagraph("He tried to wash his hands again, but the blood was gone by now — or at least it seemed gone — and yet he could still smell it, still feel it on his skin, still taste it in his mouth.", "دوباره تلاش کرد دست‌هایش را بشوید، اما خون تا حالا رفته بود — یا حداقل به نظر می‌رسید رفته باشد — و با این حال هنوز بویش را حس می‌کرد، هنوز روی پوستش حسش می‌کرد، هنوز در دهانش می‌چشیدش."),
                    StoryParagraph("He checked his clothes for stains, and finding only a small spot on his trousers, he cut the fringed edge off with a knife and burned the piece in the candle flame, watching the fabric curl and blacken.", "لباس‌هایش را برای لکه بررسی کرد و فقط لکه کوچکی روی شلوارش یافت، پس لبه ریش‌ریش آن را با چاقو برید و تکه را در شعله شمع سوزاند و تماشا کرد که پارچه جمع شد و سیاه شد."),
                    StoryParagraph("He then sat on the edge of his sofa for a long time, staring at the wall, listening to the sounds of the city outside, waiting for the knock on the door that he was certain would come at any moment.", "سپس مدت طولانی روی لبه مبلش نشست و به دیوار خیره شد و به صداهای شهر بیرون گوش داد و منتظر ضربه‌ای به در ماند که مطمئن بود هر لحظه می‌آید."),
                    StoryParagraph("But the knock did not come, and slowly — terribly slowly — the night passed, and the first grey light of dawn began to creep through the window, and Raskolnikov was still awake, still shaking, still waiting.", "اما ضربه نیامد و آهسته — به‌طرز هولناکی آهسته — شب گذشت و اولین نور خاکستری سحر شروع کرد از پنجره داخل شدن و راسکولنیکوف هنوز بیدار بود، هنوز می‌لرزید، هنوز منتظر بود."),
                    StoryParagraph("He knew, somewhere deep in the exhausted corners of his mind, that he had won nothing, that he had killed two women for nothing, that the money he had taken would never give him what he truly wanted.", "در گوشه‌های خسته ذهنش، جایی عمیق، می‌دانست که هیچ چیزی نبرده بود، که دو زن را برای هیچ کشته بود، که پولی که گرفته بود هرگز آنچه واقعاً می‌خواست را به او نمی‌داد."),
                    StoryParagraph("And he knew, with a certainty that chilled him to the bone, that the punishment for what he had done would not come from the police, or from a court, or from any prison, but from something far worse inside himself.", "و با اطمینانی که تا مغز استخوانش را سرد کرد می‌دانست که مجازات کاری که کرده بود نه از پلیس می‌آمد، نه از دادگاه، نه از هیچ زندانی، بلکه از چیزی بسیار بدتر در درون خودش."),
                    StoryParagraph("He had imagined, before the murder, that he would feel like a Napoleon after it was done, that he would feel powerful, free, above the ordinary rules of ordinary men, but instead, he felt smaller and weaker than he had ever felt before.", "پیش از قتل تصور کرده بود که پس از انجامش مثل ناپلئون احساس می‌کند، احساس قدرت، آزادی، برتری از قوانین معمولی مردان معمولی، اما در عوض، کوچک‌تر و ضعیف‌تر از هر زمان دیگری در عمرش احساس می‌کرد."),
                    StoryParagraph("He tried to laugh at himself, at his own foolishness, at the proud theories that had led him here, but the laughter stuck in his throat and turned into something closer to a sob.", "تلاش کرد به خودش بخندد، به حماقت خودش، به نظریه‌های مغرورانه‌ای که او را به اینجا کشانده بود، اما خنده در گلویش گیر کرد و به چیزی شبیه به هق‌هق تبدیل شد."),
                    StoryParagraph("And then, at last, as the sun rose over the rooftops of Petersburg, he fell into a deep, feverish sleep, and he dreamed of horses being beaten to death, and he dreamed of old women laughing at him from the darkness, and he dreamed of a life he would never have.", "و بعد، در نهایت، همان‌طور که خورشید بر بام‌های پترزبورگ طلوع می‌کرد، در خوابی عمیق و تب‌آلود فرو رفت و خواب اسب‌هایی را دید که تا مرگ کتک می‌خورند و خواب پیرزنان را دید که از تاریکی به او می‌خندند و خواب زندگی‌ای را دید که هرگز نخواهد داشت.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Torment of Guilt", titlePersian = "عذاب گناه",
                paragraphs = listOf(
                    StoryParagraph("When Raskolnikov finally woke, many hours later, the sun was already high in the sky, and the room was filled with a strange, hostile brightness that seemed to mock his misery.", "وقتی راسکولنیکوف بالاخره بیدار شد، ساعت‌ها بعد، خورشید از قبل در آسمان بلند بود و اتاق پر از روشنایی عجیب و خصمانه‌ای بود که به نظر می‌رسید بدبختی‌اش را مسخره می‌کرد."),
                    StoryParagraph("For a long, confused moment, he did not remember what had happened the night before, and then the memory crashed over him like a wave of ice-cold water, and he began to shake uncontrollably.", "برای لحظه‌ای طولانی و گیج، به یاد نیاورد شب قبل چه اتفاقی افتاده بود و بعد خاطره مثل موجی از آب یخ‌سرد رویش فروریخت و شروع کرد به لرزیدن بی‌کنترل."),
                    StoryParagraph("He had become, in a single, irreversible moment, a murderer — not in theory, not in some abstract philosophical sense, but in reality, in blood, in flesh, in the irreversible fact of two human lives ended by his own hands.", "او در یک لحظه واحد و بازگشت‌ناپذیر به قاتل تبدیل شده بود — نه در تئوری، نه به معنایی فلسفی انتزاعی، بلکه در واقعیت، در خون، در گوشت، در واقعیت بازگشت‌ناپذیر دو زندگی انسانی که توسط دستان خودش پایان یافته بودند."),
                    StoryParagraph("He examined his clothes obsessively, searching for any trace of blood, any evidence of his crime.", "او وسواس‌گونه لباس‌هایش را بررسی کرد و دنبال هر اثری از خون گشت، هر مدرکی از جنایتش."),
                    StoryParagraph("He checked his hands, his cuffs, his collar, his pockets — but there was nothing, nothing, nothing.", "دستانش را بررسی کرد، مچ‌هایش، یقه‌اش، جیب‌هایش — اما چیزی نبود، هیچ چیز، هیچ چیز."),
                    StoryParagraph("The absence of evidence did not comfort him; it only made him more anxious, as if the crime itself had been so insignificant that it had left no trace, as if he were not important enough even to have committed a murder.", "نبود مدرک آرامشش نداد؛ فقط مضطرب‌ترش کرد، گویی خود جنایت آنقدر بی‌اهمیت بود که هیچ اثری نگذاشته، گویی حتی به‌قدری که مرتکب قتلی شود هم مهم نبود."),
                    StoryParagraph("He hid the money and jewels under a loose brick behind the peeling wallpaper, and he sat on his sofa, staring at the wall, waiting.", "پول و جواهرات را زیر آجری لق پشت کاغذ دیواری کنده‌شده پنهان کرد و روی مبلش نشست و به دیوار خیره شد و منتظر ماند."),
                    StoryParagraph("He did not know what he was waiting for; perhaps he was waiting for the knock on the door, or for the sound of the police on the stairs, or for the world itself to acknowledge what he had done.", "نمی‌دانست منتظر چه بود؛ شاید منتظر ضربه‌ای به در بود، یا صدای پلیس روی پله‌ها، یا اینکه خود دنیا به آنچه کرده بود اعتراف کند."),
                    StoryParagraph("But the world did not care; the world continued on its way, indifferent to the small horror that had taken place in a cramped apartment on a side street.", "اما دنیا اهمیت نمی‌داد؛ دنیا به راهش ادامه می‌داد، بی‌تفاوت به وحشت کوچکی که در آپارتمانی تنگ در خیابان کناری اتفاق افتاده بود."),
                    StoryParagraph("That afternoon, there was a loud knock at his door, and his heart stopped, and he was certain, absolutely certain, that his moment had come.", "آن بعدازظهر، ضربه بلندی به درش خورد و قلبش ایستاد و مطمئن بود، کاملاً مطمئن، که لحظه‌اش رسیده است."),
                    StoryParagraph("But it was not the police; it was his landlady's servant, bringing him a summons to the police station.", "اما پلیس نبود؛ خدمتکار صاحب‌خانه بود که احضاریه‌ای به کلانتری برایش می‌آورد."),
                    StoryParagraph("The summons concerned a debt he owed to his landlady — nothing more, nothing less — but for Raskolnikov, in his feverish state of mind, it felt like the end of the world.", "احضاریه مربوط به بدهی‌ای بود که به صاحب‌خانه‌اش داشت — نه بیشتر، نه کمتر — اما برای راسکولنیکوف، در وضعیت ذهنی تب‌آلودش، مثل پایان دنیا حس می‌شد."),
                    StoryParagraph("He dressed with trembling hands, gathered his scattered thoughts as best he could, and walked to the station, rehearsing excuses in his head, planning his defense, preparing for the worst.", "با دستانی لرزان لباس پوشید، تا آنجا که می‌توانست افکار پراکنده‌اش را جمع کرد و به سمت کلانتری راه افتاد، در ذهنش عذر و بهانه تمرین می‌کرد، دفاعش را برنامه‌ریزی می‌کرد، خود را برای بدترین حالت آماده می‌کرد."),
                    StoryParagraph("But when he arrived, the clerk looked at him with mild annoyance and told him, in a bored voice, that the matter concerned an unpaid debt to his landlady, nothing more.", "اما وقتی رسید، کارمند با نارضایتی ملایمی به او نگاه کرد و با صدایی خسته گفت که موضوع درباره بدهی پرداخت‌نشده به صاحب‌خانه‌اش است، چیز دیگری نیست."),
                    StoryParagraph("The relief that washed over Raskolnikov was so intense that he nearly laughed out loud, and the policemen, seeing his strange reaction, looked at him with suspicion and asked him if he was feeling unwell.", "آسودگی‌ای که راسکولنیکوف را فرا گرفت چنان شدید بود که تقریباً بلند خندید و پلیس‌ها که واکنش عجیبش را دیدند، با شک به او نگاه کردند و پرسیدند حالش خوب است یا نه."),
                    StoryParagraph("He left the station in a daze, and as he walked home through the crowded streets, he felt suddenly dizzy, and he collapsed on a bench in a small square, unable to continue.", "گیج از کلانتری بیرون رفت و در حالی که از میان خیابان‌های شلوغ به خانه می‌رفت، ناگهان احساس سرگیجه کرد و روی نیمکتی در میدان کوچکی افتاد و نتوانست ادامه دهد."),
                    StoryParagraph("A kind stranger helped him up and even gave him some money for a cab, but Raskolnikov, suspicious of everyone, threw the money into the river as soon as the stranger had gone away.", "غریبه‌ای مهربان کمکش کرد بلند شود و حتی پولی برای کالسکه به او داد، اما راسکولنیکوف که به همه مشکوک بود، به‌محض رفتن آن غریبه پول را در رودخانه انداخت."),
                    StoryParagraph("When he finally reached his room, he threw himself on his sofa and fell into a deep, feverish sleep, and as he slept, a terrible dream came to him, a dream far worse than anything he had yet endured.", "وقتی بالاخره به اتاقش رسید، خود را روی مبلش انداخت و در خوابی عمیق و تب‌آلود فرو رفت و در خواب، رؤیای هولناکی به سراغش آمد، رؤیایی بسیار بدتر از هر چیزی که تا حالا تحمل کرده بود."),
                    StoryParagraph("In the dream, he was back in Alyona's apartment, striking her again and again with the axe, but no matter how many times he hit her, she would not die.", "در خواب، دوباره در آپارتمان آلیونا بود، بارها و بارها با تبر به او می‌کوبید، اما هر چقدر ضربه می‌زد، نمی‌مرد."),
                    StoryParagraph("She sat there on the floor, silent and still, watching him with her cold, mocking eyes, and then, slowly, she began to laugh — a terrible, soundless laugh that seemed to come from somewhere far away.", "او همان‌جا روی زمین نشسته بود، ساکت و بی‌حرکت، با چشمانی سرد و طعنه‌آمیز نگاهش می‌کرد و سپس، آهسته، شروع کرد به خندیدن — خنده‌ای هولناک و بی‌صدا که به نظر از جایی دور می‌آمد."),
                    StoryParagraph("Raskolnikov tried to run, but his legs would not move, and the old woman grew larger and larger, filling the whole room, until he woke up screaming, drenched in sweat, his heart pounding in his chest.", "راسکولنیکوف تلاش کرد فرار کند، اما پاهایش حرکت نمی‌کردند و پیرزن بزرگ‌تر و بزرگ‌تر شد و تمام اتاق را پر کرد، تا وقتی فریادزنان بیدار شد، غرق در عرق و قلبش در سینه‌اش می‌کوبید."),
                    StoryParagraph("Just at that moment, there was a loud knock at his door, and Raskolnikov froze, convinced that the police had come for him at last, that his brief, terrible freedom was finally over.", "همان لحظه، ضربه بلندی به درش خورد و راسکولنیکوف یخ زد، مطمئن شد بالاخره پلیس برایش آمده و آزادی کوتاه و هولناکش بالاخره تمام شده است."),
                    StoryParagraph("But the man who entered was not a policeman; it was Razumikhin, a former classmate and a kind, loyal, and talkative friend whom Raskolnikov had once been close to.", "اما مردی که وارد شد پلیس نبود؛ رازومیخین بود، هم‌کلاسی سابق و دوستی مهربان، وفادار و پرحرف که راسکولنیکوف زمانی با او نزدیک بود."),
                    StoryParagraph("Razumikhin had been looking for him for days, worried about his health, and he was genuinely shocked by his friend's pale, gaunt appearance and wild, feverish eyes.", "رازومیخین روزها بود دنبالش می‌گشت و نگران سلامتی‌اش بود و از ظاهر رنگ‌پریده و لاغر و چشمان وحشی و تب‌آلود دوستش واقعاً شوکه شد."),
                    StoryParagraph("He had brought Raskolnikov clean clothes, some money, and news from his mother and sister, who were on their way to Petersburg to see him.", "او برای راسکولنیکوف لباس تمیز، کمی پول و خبری از مادر و خواهرش آورده بود که در راه پترزبورگ برای دیدنش بودند."),
                    StoryParagraph("Raskolnikov, however, could not accept any of this kindness; suspicion had become his second nature, and he pushed Razumikhin away with cold, bitter words that wounded the loyal friend deeply.", "اما راسکولنیکوف نمی‌توانست هیچ‌کدام از این مهربانی‌ها را بپذیرد؛ بدگمانی طبیعت دومش شده بود و رازومیخین را با کلمات سرد و تلخ از خود راند، کلماتی که دوست وفادارش را عمیقاً زخمی کرد."),
                    StoryParagraph("But Razumikhin, being the man he was, did not give up; he promised to return the next day and the day after that, and he told Raskolnikov, quite firmly, that he would not be abandoned no matter how hard he pushed people away.", "اما رازومیخین، چون مردی که بود، رها نکرد؛ قول داد روز بعد و روز بعد از آن برگردد و به راسکولنیکوف با اطمینان گفت که هر چقدر هم مردم را از خود براند، رها نخواهد شد."),
                    StoryParagraph("When Razumikhin had gone, Raskolnikov lay on his sofa for a long time, thinking about what he had done, and about what he would do next, and about the terrible, unending weight that now pressed upon his soul.", "وقتی رازومیخین رفت، راسکولنیکوف مدت طولانی روی مبلش دراز کشید و به آنچه کرده بود فکر کرد و به آنچه بعداً می‌کرد و به وزن هولناک و بی‌پایانی که حالا بر روحش فشار می‌آورد."),
                    StoryParagraph("He had believed that the murder would make him free, but instead, it had bound him tighter than any chain, and it had cut him off from every human being who might have loved him.", "باور داشت قتل آزادش می‌کند، اما در عوض، او را محکم‌تر از هر زنجیری بسته بود و او را از هر انسانی که ممکن بود دوستش داشته باشد جدا کرده بود."),
                    StoryParagraph("The investigation into the murders had begun, and a clever, patient investigator named Porfiry Petrovich had been assigned to the case — a man who had studied Raskolnikov's mind from the very beginning.", "تحقیق درباره قتل‌ها آغاز شده بود و بازپرسی زیرک و صبور به نام پورفیری پتروویچ به پرونده گمارده شده بود — مردی که از همان ابتدا ذهن راسکولنیکوف را مطالعه کرده بود."),
                    StoryParagraph("Porfiry had read an article that Raskolnikov had written months earlier, in which the young student argued that extraordinary men had the right to step over moral laws for the sake of a greater purpose.", "پورفیری مقاله‌ای خوانده بود که راسکولنیکوف ماه‌ها پیش نوشته بود، در آن دانشجوی جوان استدلال می‌کرد که مردان استثنایی حق دارند برای هدفی برتر از قوانین اخلاقی عبور کنند."),
                    StoryParagraph("This article, more than any other clue, made Porfiry suspect that Raskolnikov might be the murderer, and from that moment on, he began to weave a careful, patient trap.", "این مقاله، بیش از هر سرنخ دیگری، پورفیری را مشکوک کرد که راسکولنیکوف ممکن است قاتل باشد و از آن لحظه به بعد، شروع کرد به تنیدن تله‌ای دقیق و صبورانه."),
                    StoryParagraph("When Raskolnikov came to the police station to register some pawned items, he and Porfiry met for the first time, and the meeting was strange and unsettling for both of them.", "وقتی راسکولنیکوف برای ثبت اشیای گروگذاشته‌شده به کلانتری رفت، او و پورفیری برای اولین بار همدیگر را دیدند و این ملاقات برای هر دو عجیب و نگران‌کننده بود."),
                    StoryParagraph("Porfiry smiled constantly, speaking in a soft, gentle voice, but his questions were sharp as knives, and he watched Raskolnikov's face for every flicker of emotion, every tiny, unconscious reaction.", "پورفیری مدام لبخند می‌زد و با صدایی نرم و ملایم صحبت می‌کرد، اما سوالاتش مثل چاقو تیز بود و برای هر تکان احساس، هر واکنش کوچک و ناخودآگاه، چهره راسکولنیکوف را می‌پایید."),
                    StoryParagraph("He asked Raskolnikov about his article, about his theory of extraordinary men, and about whether he himself believed he was one of those men, and Raskolnikov, trying to remain calm, felt cold sweat forming on his forehead.", "او از راسکولنیکوف درباره مقاله‌اش پرسید، درباره نظریه‌اش درباره مردان استثنایی و اینکه آیا خودش باور دارد یکی از آن مردان است و راسکولنیکوف که تلاش می‌کرد آرام بماند، عرق سردی روی پیشانی‌اش حس کرد."),
                    StoryParagraph("When Raskolnikov finally left the office, he felt both relieved and more terrified than before, because he sensed, somehow, that Porfiry had not been fooled for a single moment.", "وقتی راسکولنیکوف بالاخره از دفتر بیرون رفت، هم آسوده شد و هم بیشتر از قبل ترسید، چون حس کرد، به نحوی، که پورفیری حتی برای یک لحظه فریب نخورده است."),
                    StoryParagraph("A few days later, Porfiry appeared unexpectedly at Raskolnikov's own room, and their second meeting was even more disturbing than the first, because this time, there were no formalities to hide behind.", "چند روز بعد، پورفیری به‌طور غیرمنتظره در اتاق خود راسکولنیکوف ظاهر شد و ملاقات دومشان حتی نگران‌کننده‌تر از اولی بود، چون این بار تشریفاتی نبود که پشتش پنهان شوند."),
                    StoryParagraph("The investigator mentioned the murders, described them in careful detail, and then, quite casually, asked Raskolnikov what he thought of the whole affair.", "بازپرس به قتل‌ها اشاره کرد، با جزئیات دقیق توصیفشان کرد و سپس، کاملاً اتفاقی، از راسکولنیکوف پرسید که درباره کل ماجرا چه فکر می‌کند."),
                    StoryParagraph("Raskolnikov tried to answer calmly, but his hands were shaking, and his voice cracked more than once, and he knew that Porfiry saw everything, that Porfiry was only waiting for him to break down.", "راسکولنیکوف تلاش کرد آرام پاسخ دهد، اما دست‌هایش می‌لرزیدند و صدایش بیش از یک بار شکست و می‌دانست که پورفیری همه چیز را می‌بیند، که پورفیری فقط منتظر است او فرو بریزد."),
                    StoryParagraph("At the very moment of greatest tension, a strange man burst into the room and confessed to the murders, claiming that he, and not Raskolnikov, had killed Alyona and Lizaveta.", "در همان لحظه بیشترین تنش، مردی عجیب به اتاق هجوم برد و به قتل‌ها اعتراف کرد و ادعا کرد که او، نه راسکولنیکوف، آلیونا و لیزاویتا را کشته است."),
                    StoryParagraph("Raskolnikov left the room in a daze, hardly able to believe his luck, but Porfiry was not fooled; he knew that the confession was false, and he continued to wait, patient as always.", "راسکولنیکوف گیج از اتاق بیرون رفت و به‌سختی می‌توانست باورش کند، اما پورفیری فریب نخورد؛ می‌دانست که آن اعتراف دروغین است و مثل همیشه صبورانه ادامه داد به انتظار."),
                    StoryParagraph("The game between the two men had only just begun, and both of them knew that it could only end in one way: with Raskolnikov either confessing on his own or being broken by the weight of his own conscience.", "بازی میان آن دو مرد تازه شروع شده بود و هر دو می‌دانستند که فقط به یک شکل می‌تواند پایان یابد: یا راسکولنیکوف خودش اعتراف می‌کند، یا زیر وزن وجدان خودش خرد می‌شود."),
                    StoryParagraph("Raskolnikov began to wander the streets of Petersburg like a ghost, unable to eat, unable to sleep, unable to find peace in any corner of the city, pursued by a guilt that would not let him rest.", "راسکولنیکوف شروع کرد مثل شبحی در خیابان‌های پترزبورگ پرسه زدن، نه می‌توانست بخورد، نه بخوابد، نه در هیچ گوشه‌ای از شهر آرامش بیابد، تعقیب‌شده توسط گناهی که رهایش نمی‌کرد."),
                    StoryParagraph("He visited the scenes of his old life, the university, the streets where he had once walked as a free man, and everywhere he went, he felt like a stranger, like someone who no longer belonged to the human race.", "او به صحنه‌های زندگی گذشته‌اش سر زد، دانشگاه، خیابان‌هایی که زمانی به‌عنوان مردی آزاد در آن‌ها قدم زده بود و هر جا می‌رفت، مثل غریبه‌ای احساس می‌کرد، مثل کسی که دیگر به نسل بشر تعلق ندارد."),
                    StoryParagraph("His mother and sister arrived in the city, and when he saw them, he was overcome with shame, because he knew that they had sacrificed everything for him and that he had betrayed them in the worst way possible.", "مادر و خواهرش به شهر رسیدند و وقتی آن‌ها را دید، شرم او را فرا گرفت، چون می‌دانست که آن‌ها همه چیز را برایش فدا کرده بودند و او به بدترین شکل ممکن به آن‌ها خیانت کرده بود."),
                    StoryParagraph("His sister Dunya had accepted a proposal of marriage from a wealthy but cruel man named Luzhin, partly to help her brother, partly to save her family from ruin, and Raskolnikov, when he learned of it, felt a fresh wave of self-loathing.", "خواهرش دونیا پیشنهاد ازدواج مردی ثروتمند اما بی‌رحم به نام لوژین را پذیرفته بود، نیمه برای کمک به برادرش، نیمه برای نجات خانواده‌اش از تباهی و راسکولنیکوف وقتی از آن باخبر شد، موج تازه‌ای از نفرت از خودش حس کرد."),
                    StoryParagraph("He forbade the marriage, he argued with his mother, he drove his sister to tears, and then, when they had gone, he sat alone in his room and wept like a child, because he knew that everything he touched turned to ruin.", "او ازدواج را ممنوع کرد، با مادرش بحث کرد، خواهرش را به گریه انداخت و سپس، وقتی رفتند، تنها در اتاقش نشست و مثل بچه‌ای گریه کرد، چون می‌دانست هر چیزی که لمس می‌کند به تباهی تبدیل می‌شود."),
                    StoryParagraph("In the middle of all this, he found himself drawn, again and again, to the home of Marmeladov, the drunkard he had met in the tavern, and to Marmeladov's daughter Sonya, the young woman who had sacrificed everything for her family.", "در میانه همه این‌ها، خودش را بارها و بارها کشیده به خانه مارملادوف، همان مستی که در میخانه دیده بود و به سونیا دختر مارملادوف، زن جوانی که همه چیز را برای خانواده‌اش فدا کرده بود."),
                    StoryParagraph("There was something in Sonya that drew him, something that had nothing to do with her poverty or her profession, but with the simple, unshakeable goodness that shone from her gentle face.", "چیزی در سونیا او را می‌کشید، چیزی که هیچ ربطی به فقر یا حرفه‌اش نداشت، بلکه به نیکی ساده و تزلزل‌ناپذیری داشت که از چهره مهربانش می‌درخشید."),
                    StoryParagraph("He did not yet understand why he felt this way, but he sensed, dimly, that this young woman held the key to something he had been searching for all his life, without ever knowing what it was.", "او هنوز نمی‌فهمید چرا اینطور احساس می‌کند، اما به‌طور محو حس می‌کرد که این زن جوان کلیدی برای چیزی دارد که تمام عمر در جست‌وجویش بود، بی‌آنکه بداند چیست."),
                    StoryParagraph("And so, without fully realizing it, he began to walk a path that would lead him, slowly and painfully, not towards escape, but towards a confession that would save his soul.", "و بنابراین، بدون آنکه کاملاً متوجه باشد، شروع کرد به قدم زدن در مسیری که او را، آهسته و دردناک، نه به سوی فرار، بلکه به سوی اعترافی می‌برد که روحش را نجات می‌داد.")
                )
            ),
            StoryChapter(
                number = 4, title = "Sonya's Love", titlePersian = "عشق سونیا",
                paragraphs = listOf(
                    StoryParagraph("The first time Raskolnikov truly spoke with Sonya was on the evening when he came to her room to tell her that her father had been killed.", "اولین باری که راسکولنیکوف واقعاً با سونیا صحبت کرد، عصر روزی بود که به اتاقش آمد تا به او بگوید پدرش کشته شده است."),
                    StoryParagraph("Marmeladov, the drunken clerk, had been run over by a carriage in the street, and he had died in Raskolnikov's arms, whispering his daughter's name with his last breath.", "مارملادوف، کارمند مست، در خیابان توسط کالسکه‌ای زیر گرفته شده بود و در آغوش راسکولنیکوف مرده بود و با آخرین نفسش نام دخترش را زمزمه کرده بود."),
                    StoryParagraph("Sonya's room was small and bare, with bare walls and a single, cracked window, and yet there was something strangely peaceful about it, something that seemed to belong to another world entirely.", "اتاق سونیا کوچک و بی‌پیرایه بود، با دیوارهای برهنه و یک پنجره ترک‌خورده و با این حال چیزی به‌طرز عجیبی آرام در آن بود، چیزی که به نظر می‌رسید کاملاً به دنیای دیگری تعلق دارد."),
                    StoryParagraph("She was small and thin, with pale blue eyes and a face that had once been beautiful but now bore the marks of suffering, exhaustion, and unshed tears.", "او کوچک و لاغر بود، با چشمان آبی رنگ‌پریده و صورتی که زمانی زیبا بوده اما حالا آثار رنج، خستگی و اشک‌های نریخته را بر خود داشت."),
                    StoryParagraph("She was only eighteen years old, but she had already suffered more than most people suffer in a lifetime.", "او فقط هجده ساله بود، اما از قبل بیش از آنچه بیشتر مردم در یک عمر رنج می‌برند رنج کشیده بود."),
                    StoryParagraph("Her mother, Katerina Ivanovna, had been a proud woman of noble birth who had fallen into poverty, and she was slowly dying of consumption.", "مادرش، کاترینا ایوانوونا، زنی مغرور از تبار اصیل بود که به فقر افتاده بود و آهسته از بیماری سل می‌مرد."),
                    StoryParagraph("Her father, Marmeladov, had drunk away every penny the family had, had sold even his wife's stockings for vodka, had left his children without food for days at a time.", "پدرش، مارملادوف، هر پنی که خانواده داشت را نوشیده بود، حتی جوراب‌های همسرش را برای ودکا فروخته بود، فرزندانش را روزها بدون غذا رها کرده بود."),
                    StoryParagraph("And Sonya, the eldest daughter, had made a choice that had cost her everything: she had become a prostitute, taking the yellow ticket, so that her family might survive.", "و سونیا، دختر بزرگ، انتخابی کرده بود که همه چیز برایش هزینه داشت: او روسپی شده بود، کارت زرد گرفته بود، تا خانواده‌اش زنده بماند."),
                    StoryParagraph("She lived apart from her family now, in a separate room, because she did not wish to bring shame upon them in the eyes of their neighbors, and yet she gave them every penny she earned.", "او حالا جدا از خانواده‌اش زندگی می‌کرد، در اتاقی جداگانه، چون نمی‌خواست در نظر همسایه‌ها شرم بر آن‌ها بیاورد، و با این حال هر پنی که به دست می‌آورد به آن‌ها می‌داد."),
                    StoryParagraph("Raskolnikov had known this about her, had known it from the moment Marmeladov had told him his story in the tavern, and yet when he saw her now, in the flesh, in her small, poor room, he felt something he could not name.", "راسکولنیکوف این را درباره‌اش می‌دانست، از لحظه‌ای که مارملادوف در میخانه داستانش را به او گفته بود می‌دانست و با این حال وقتی حالا می‌دیدش، در گوشت و خون، در اتاق کوچک و فقیرانه‌اش، چیزی حس کرد که نمی‌توانست نامش را ببرد."),
                    StoryParagraph("It was not pity, exactly, and it was not love, exactly, and it was not desire — it was something deeper, something that touched the very core of his being, something that reminded him of the dreams he had had as a child, before the world had taught him to be hard.", "دقیقاً ترحم نبود و دقیقاً عشق نبود و تمایل هم نبود — چیزی عمیق‌تر بود، چیزی که هسته اصلی وجودش را لمس می‌کرد، چیزی که او را به یاد رؤیاهایی می‌انداخت که در کودکی داشته، پیش از آنکه دنیا به او سختی بیاموزد."),
                    StoryParagraph("The next day, he returned to her room, and he sat with her, and he listened to her speak about her faith, about her belief that God saw everything, that God would forgive everyone, that suffering was a path to salvation.", "روز بعد، به اتاقش برگشت و با او نشست و به او گوش داد که درباره ایمانش صحبت می‌کرد، درباره باورش که خدا همه چیز را می‌بیند، که خدا همه را می‌بخشد، که رنج راهی به رستگاری است."),
                    StoryParagraph("He found her faith both beautiful and infuriating; he wanted to argue with her, to prove to her that the world was cruel and meaningless, but he could not bring himself to destroy her hope.", "او ایمانش را هم زیبا و هم خشمگین‌کننده می‌یافت؛ می‌خواست با او بحث کند، به او ثابت کند که دنیا بی‌رحم و بی‌معناست، اما نمی‌توانست خودش را راضی کند امیدش را نابود کند."),
                    StoryParagraph("One evening, without any warning, he told her that he knew who had killed Alyona Ivanovna and Lizaveta.", "یک عصر، بدون هیچ هشداری، به او گفت می‌داند چه کسی آلیونا ایوانوونا و لیزاویتا را کشته است."),
                    StoryParagraph("Sonya stared at him with wide, terrified eyes, and she whispered, 'You?'", "سونیا با چشمانی گشاد و وحشت‌زده نگاهش کرد و زمزمه کرد: «تو؟»"),
                    StoryParagraph("He did not answer directly; he simply bowed his head and waited, and in that long, terrible silence, she understood everything.", "او مستقیم جواب نداد؛ فقط سرش را خم کرد و منتظر ماند و در آن سکوت طولانی و هولناک، او همه چیز را فهمید."),
                    StoryParagraph("And then Sonya did something that Raskolnikov had not expected, that he had not thought possible: she did not scream, she did not run, she did not call for the police — she simply rose from her chair, walked over to him, and embraced him.", "و بعد سونیا کاری کرد که راسکولنیکوف انتظارش را نداشت، که فکر نمی‌کرد ممکن باشد: جیغ نزد، فرار نکرد، پلیس خبر نکرد — فقط از صندلی بلند شد، به طرفش رفت و او را در آغوش گرفت."),
                    StoryParagraph("She held him as a mother holds a child, as a sister holds a brother, as a human being holds another human being in the face of unspeakable horror, and she wept, not for herself, not even for the victims, but for him, for the terrible suffering that had broken his soul.", "او او را در آغوش گرفت همان‌طور که مادر بچه‌ای را در آغوش می‌گیرد، مثل خواهری که برادری را در آغوش می‌گیرد، مثل انسانی که در برابر وحشتی ناگفتنی انسان دیگری را در آغوش می‌گیرد و گریست، نه برای خودش، نه حتی برای قربانیان، بلکه برای او، برای رنج هولناکی که روحش را شکسته بود."),
                    StoryParagraph("Raskolnikov was stunned by her reaction, and something inside him cracked open, and for the first time since the murders, he allowed himself to feel the full weight of what he had done.", "راسکولنیکوف از واکنشش شوکه شد و چیزی در درونش شکافت و باز شد و برای اولین بار پس از قتل‌ها، اجازه داد وزن کامل کاری که کرده بود را حس کند."),
                    StoryParagraph("He buried his face in her shoulder and wept, and he wept for a long time, and Sonya held him, and neither of them spoke, because there were no words that could express what was happening between them.", "صورتش را در شانه‌اش پنهان کرد و گریست و مدت طولانی گریست و سونیا او را نگه داشت و هیچ‌کدام حرف نزدند، چون کلمه‌ای نبود که بتواند بیان کند چه چیزی میانشان می‌گذشت."),
                    StoryParagraph("'What have you done to yourself?' she whispered at last. 'What have you done to your life?'", "بالاخره نجوا کرد: «با خودت چه کرده‌ای؟ با زندگی‌ات چه کرده‌ای؟»"),
                    StoryParagraph("'I killed an old woman,' he said. 'I killed her sister. I killed them both with an axe.'", "گفت: «پیرزنی را کشتم. خواهرش را کشتم. هر دو را با تبر کشتم.»"),
                    StoryParagraph("'You are the unhappiest man on earth,' she said, and there was no judgment in her voice, no condemnation, only a deep, profound sadness, the sadness of someone who understood suffering in a way that most people never could.", "او گفت: «تو بدبخت‌ترین مرد روی زمینی،» و هیچ قضاوتی در صدایش نبود، هیچ محکومیتی، فقط غمی عمیق و ژرف، غم کسی که رنج را به شکلی که بیشتر مردم هرگز نمی‌توانند می‌فهمید."),
                    StoryParagraph("'You have destroyed yourself,' she said. 'And now you must do the hardest thing of all.'", "گفت: «خودت را نابود کرده‌ای. و حالا باید سخت‌ترین کار همه را انجام دهی.»"),
                    StoryParagraph("'You must go to the crossroads, kiss the earth you have defiled, and tell the whole world, out loud, that you are a murderer.'", "«باید به چهارراه بروی، زمینی را که آلوده کرده‌ای ببوسی و به تمام دنیا، بلند، بگویی که قاتلی.»"),
                    StoryParagraph("Raskolnikov was horrified by her words, because confession meant the end of everything he had ever known, but deep down, he knew she was right, and he knew that she was the only person in the world whose judgment he truly trusted.", "راسکولنیکوف از کلماتش وحشت کرد، چون اعتراف یعنی پایان هر چیزی که می‌شناخت، اما در عمق وجودش، می‌دانست که حق با اوست و می‌دانست که او تنها فرد دنیاست که واقعاً به قضاوتش اعتماد دارد."),
                    StoryParagraph("'Will you visit me in prison?' he asked, and his voice was the voice of a child, small and afraid.", "پرسید: «در زندان به دیدنم می‌آیی؟» و صدایش صدای یک بچه بود، کوچک و ترسان."),
                    StoryParagraph("'I will come,' she said. 'I will always come. I will never leave you.'", "گفت: «می‌آیم. همیشه می‌آیم. هرگز ترکت نمی‌کنم.»"),
                    StoryParagraph("And she took a small wooden cross from her neck and placed it around his, and she took another cross for herself, and she said, 'We will carry our crosses together.'", "و صلیب چوبی کوچکی از گردنش درآورد و به گردن او انداخت و صلیب دیگری برای خودش برداشت و گفت: «صلیب‌هایمان را با هم حمل می‌کنیم.»"),
                    StoryParagraph("That night, Raskolnikov left Sonya's room feeling something he had not felt in weeks: not peace, exactly, but something close to it, something that felt almost like hope.", "آن شب، راسکولنیکوف اتاق سونیا را با حسی ترک کرد که هفته‌ها حس نکرده بود: دقیقاً آرامش نبود، اما چیزی نزدیک به آن، چیزی که تقریباً مثل امید حس می‌شد."),
                    StoryParagraph("He walked through the dark streets of Petersburg, and for the first time, he did not feel like a ghost among the living; he felt like a man among men, a sinner among sinners, a human being among human beings.", "او در خیابان‌های تاریک پترزبورگ قدم زد و برای اولین بار، مثل شبحی میان زندگان حس نکرد؛ مثل مردی میان مردان حس کرد، گناهکاری میان گناهکاران، انسانی میان انسان‌ها."),
                    StoryParagraph("He knew that his suffering was only beginning, that the road ahead would be long and painful, that he had not yet paid for what he had done.", "می‌دانست که رنجش تازه شروع شده بود، که راه پیش رو طولانی و دردناک می‌بود، که هنوز برای کاری که کرده بود تاوان نداده بود."),
                    StoryParagraph("But he also knew, for the first time, that he was not alone.", "اما برای اولین بار می‌دانست که تنها نیست."),
                    StoryParagraph("And that, for a man who had spent so long in the darkness, was everything.", "و این، برای مردی که اینقدر طولانی در تاریکی گذرانده بود، همه چیز بود.")
                )
            ),
            StoryChapter(
                number = 5, title = "Confession and Redemption", titlePersian = "اعتراف و رستگاری",
                paragraphs = listOf(
                    StoryParagraph("For many days after his confession to Sonya, Raskolnikov wandered through the streets of Petersburg in a state of unbearable tension, unable to decide whether to give himself up or to continue living in his private hell.", "روزهای زیادی پس از اعترافش به سونیا، راسکولنیکوف در وضعیتی از تنش تحمل‌ناپذیر در خیابان‌های پترزبورگ پرسه زد و نتوانست تصمیم بگیرد که خودش را تسلیم کند یا به زندگی در جهنم شخصی‌اش ادامه دهد."),
                    StoryParagraph("The walls of his room seemed to be closing in on him; every shadow in every corner seemed to be watching him; every voice in the street seemed to be whispering his name.", "دیوارهای اتاقش به نظر می‌رسید رویش تنگ می‌شوند؛ هر سایه‌ای در هر گوشه‌ای به نظر می‌رسید تماشایش می‌کند؛ هر صدایی در خیابان به نظر می‌رسید نامش را زمزمه می‌کند."),
                    StoryParagraph("He could not eat; he could not sleep; he could not think clearly; he was a man possessed, a man haunted, a man whose mind had become his own worst prison.", "نمی‌توانست بخورد؛ نمی‌توانست بخوابد؛ نمی‌توانست واضح فکر کند؛ او مردی تسخیرشده بود، مردی تعقیب‌شده، مردی که ذهنش به بدترین زندان خودش تبدیل شده بود."),
                    StoryParagraph("One morning, without any warning, he went to Sonya and told her that he was ready to confess.", "یک صبح، بدون هیچ هشداری، به سراغ سونیا رفت و به او گفت آماده است اعتراف کند."),
                    StoryParagraph("She did not try to dissuade him; she did not weep or cling to him; she simply took her wooden cross and placed it around his neck, and she told him that she would be waiting for him when he returned.", "او تلاش نکرد منصرفش کند؛ گریه نکرد و به او نچسبید؛ فقط صلیب چوبی‌اش را برداشت و به گردنش انداخت و به او گفت وقتی برگردد منتظرش خواهد بود."),
                    StoryParagraph("'Go to the crossroads,' she said. 'Kneel down. Kiss the earth. And say out loud, so that everyone can hear, that you are a murderer.'", "گفت: «به چهارراه برو. زانو بزن. زمین را ببوس. و بلند بگو، تا همه بشنوند، که قاتلی.»"),
                    StoryParagraph("Raskolnikov walked slowly through the crowded streets, and with every step, he felt as though he were walking toward his own execution.", "راسکولنیکوف آهسته از میان خیابان‌های شلوغ گذشت و با هر قدم، حس کرد مثل اینکه به سمت اعدام خودش می‌رود."),
                    StoryParagraph("The world continued around him, indifferent, oblivious: merchants sold their wares, children played in the gutters, women argued about the price of bread, and no one, no one at all, seemed to notice the extraordinary drama unfolding in the heart of one young man.", "دنیا در اطرافش ادامه می‌یافت، بی‌تفاوت، بی‌خبر: بازرگانان کالاهایشان را می‌فروختند، بچه‌ها در ناودان‌ها بازی می‌کردند، زنان درباره قیمت نان بحث می‌کردند و هیچ‌کس، هیچ‌کس اصلاً، به نظر نمی‌رسید درام فوق‌العاده‌ای که در قلب یک جوان رخ می‌داد را ببیند."),
                    StoryParagraph("When he reached the crossroads, he stopped, and for a long moment, he stood frozen, unable to move, unable to speak, unable to do the one thing that might save him.", "وقتی به چهارراه رسید، ایستاد و برای لحظه‌ای طولانی، یخ‌زده ماند، قادر به حرکت نبود، قادر به صحبت کردن نبود، قادر به انجام آن یک کاری که ممکن بود نجاتش دهد نبود."),
                    StoryParagraph("The memory of the two dead bodies rose up in his mind, and the memory of Sonya's face, and the memory of his mother's tears, and the memory of everything he had lost.", "خاطره دو جسد مرده در ذهنش بالا آمد و خاطره چهره سونیا و خاطره اشک‌های مادرش و خاطره هر چیزی که از دست داده بود."),
                    StoryParagraph("And then, slowly, painfully, he knelt down in the middle of the street, and he pressed his lips to the cold, dirty cobblestones, and he whispered, loud enough for the passersby to hear, 'I am a murderer.'", "و بعد، آهسته، دردناک، در وسط خیابان زانو زد و لب‌هایش را به سنگفرش‌های سرد و کثیف فشار داد و زمزمه کرد، به‌اندازه‌ای بلند که عابران بشنوند: «من قاتلم.»"),
                    StoryParagraph("Some people laughed, thinking he was drunk; others looked at him with pity; others simply walked past, too absorbed in their own lives to care about the strange young man kneeling in the street.", "بعضی خندیدند، فکر کردند مست است؛ بعضی با ترحم نگاهش کردند؛ بعضی فقط از کنارش گذشتند، آنقدر غرق زندگی خودشان که به مرد جوان عجیبی که در خیابان زانو زده بود اهمیت ندهند."),
                    StoryParagraph("But Raskolnikov did not care about any of them; he had done what Sonya had asked of him, and for the first time in months, he felt almost peaceful.", "اما راسکولنیکوف به هیچ‌کدام از آن‌ها اهمیت نمی‌داد؛ او کاری که سونیا خواسته بود را انجام داده بود و برای اولین بار در ماه‌ها، تقریباً آرامش حس کرد."),
                    StoryParagraph("He rose to his feet and walked to the police station, and this time, when he entered, he did not hesitate, did not waver, did not allow himself to think of escape.", "او به پاهایش بلند شد و به کلانتری راه افتاد و این بار، وقتی وارد شد، تردید نکرد، لرزید نه، اجازه نداد به فرار فکر کند."),
                    StoryParagraph("He stood before the chief of police and said, in a clear, steady voice, 'I killed Alyona Ivanovna and her sister Lizaveta with an axe, and I stole from them.'", "او پیش روی رئیس پلیس ایستاد و با صدایی واضح و ثابت گفت: «من آلیونا ایوانوونا و خواهرش لیزاویتا را با تبر کشتم و از آن‌ها دزدیدم.»"),
                    StoryParagraph("The officers stared at him in disbelief, and for a moment, no one spoke, and then, slowly, the reality of what he had said began to sink in.", "افسران با ناباوری نگاهش کردند و برای لحظه‌ای، هیچ‌کس حرف نزد و بعد، آهسته، واقعیت آنچه گفته بود شروع کرد به جا افتادن."),
                    StoryParagraph("Raskolnikov was arrested and taken to a cell, and there, alone in the darkness, he began to weep — not for himself, not for the punishment that awaited him, but for the life he might have lived, the life he had thrown away.", "راسکولنیکوف دستگیر و به سلولی برده شد و آنجا، تنهای تنها در تاریکی، شروع کرد به گریه کردن — نه برای خودش، نه برای مجازاتی که در انتظارش بود، بلکه برای زندگی‌ای که ممکن بود داشته باشد، زندگی‌ای که دور انداخته بود."),
                    StoryParagraph("He was tried for the murders, and because of his confession and his evident remorse, he was sentenced to eight years of hard labor in Siberia, rather than to death, as many had expected.", "او برای قتل‌ها محاکمه شد و به‌خاطر اعتراف و پشیمانی آشکارش، به هشت سال کار سخت در سیبری محکوم شد، نه به اعدام، همان‌طور که بسیاری انتظار داشتند."),
                    StoryParagraph("Sonya, when she heard the sentence, did not weep, did not despair, did not argue; she simply packed her things, said goodbye to her family, and prepared to follow him to Siberia.", "سونیا وقتی حکم را شنید، نه گریه کرد، نه ناامید شد، نه بحث کرد؛ فقط وسایلش را بست، با خانواده‌اش خداحافظی کرد و آماده شد تا به سیبری دنبالش برود."),
                    StoryParagraph("Her mother and sister were horrified, and they begged her not to go, but Sonya was unmoved; she told them that she loved him, that he needed her, and that she would not abandon him no matter what.", "مادر و خواهرش وحشت کردند و التماس کردند نرود، اما سونیا تکان نخورد؛ به آن‌ها گفت که دوستش دارد، که او به او نیاز دارد و هر چه پیش بیاید رهایش نمی‌کند."),
                    StoryParagraph("And so, a few weeks later, on a cold, grey morning in November, Raskolnikov and Sonya set off together for the long, difficult journey to Siberia, and neither of them knew what awaited them at the end of it.", "و بنابراین، چند هفته بعد، در صبحی سرد و خاکستری در ماه نوامبر، راسکولنیکوف و سونیا با هم برای سفر طولانی و دشوار به سیبری راه افتادند و هیچ‌کدام نمی‌دانستند در انتهایش چه چیزی در انتظارشان است."),
                    StoryParagraph("The journey took many weeks, and Raskolnikov sat in silence for most of it, thinking about his crime, about his punishment, about the strange twist of fate that had brought him here.", "سفر هفته‌های بسیاری طول کشید و راسکولنیکوف بیشترش را در سکوت نشست، به جنایتش فکر می‌کرد، به مجازاتش، به پیچش عجیب تقدیری که او را به اینجا آورده بود."),
                    StoryParagraph("But as the miles passed, something began to change in him, something subtle and slow, and by the time they reached the prison colony in Siberia, he was not the same man who had left Petersburg.", "اما با گذشت مایل‌ها، چیزی در او شروع به تغییر کرد، چیزی ظریف و آهسته و تا زمانی که به مستعمره زندان در سیبری رسیدند، او همان مردی نبود که پترزبورگ را ترک کرده بود."),
                    StoryParagraph("In prison, Raskolnikov was at first withdrawn and bitter, refusing to speak to the other prisoners, unable to accept his situation, unable to forgive himself for what he had done.", "در زندان، راسکولنیکوف ابتدا در خود فرو رفته و تلخ بود، از حرف زدن با سایر زندانیان امتناع می‌کرد، نمی‌توانست وضعیتش را بپذیرد، نمی‌توانست خودش را برای کاری که کرده بود ببخشد."),
                    StoryParagraph("Sonya settled in a small town near the prison, and every Sunday, she came to visit him, bringing him bread, books, and news of the outside world, and slowly, patiently, she began to break through his walls.", "سونیا در شهر کوچکی نزدیک زندان ساکن شد و هر یکشنبه، به دیدنش می‌آمد، نان، کتاب و خبرهایی از دنیای بیرون برایش می‌آورد و آهسته و صبورانه، شروع کرد به شکستن دیوارهایش."),
                    StoryParagraph("At first, Raskolnikov accepted her visits coldly, almost with resentment, because her kindness seemed to him an accusation of everything he was not, but she did not waver, and she did not stop coming.", "اول، راسکولنیکوف دیدارهایش را سرد پذیرفت، تقریباً با کینه، چون مهربانی‌اش برایش اتهامی بود به هر چیزی که نبود، اما او متزلزل نشد و از آمدن دست نکشید."),
                    StoryParagraph("Months passed, and then a year, and slowly, without his even realizing it, Raskolnikov began to look forward to her visits, and to feel, in her presence, the first real peace he had known since the murders.", "ماه‌ها گذشت و سپس یک سال و آهسته، بی‌آنکه خودش حتی متوجه شود، راسکولنیکوف شروع کرد به انتظار دیدارهایش و در حضورش، اولین آرامش واقعی را که از زمان قتل‌ها شناخته بود حس کرد."),
                    StoryParagraph("One day, watching her from across the prison yard, Raskolnikov suddenly understood, with a shock that went through his entire body, that he loved her, and that he had perhaps loved her from the very beginning.", "یک روز، در حالی که از آن طرف حیاط زندان تماشایش می‌کرد، راسکولنیکوف ناگهان فهمید، با شوکی که در تمام بدنش پیچید، که دوستش دارد و شاید از همان ابتدا دوستش داشته است."),
                    StoryParagraph("He threw himself at her feet and wept, and for the first time, he wept not out of guilt, or despair, or self-hatred, but out of love, out of gratitude, out of the simple, overwhelming recognition that he was not alone.", "خود را به پای او انداخت و گریست و برای اولین بار، نه از گناه گریست، نه از ناامیدی، نه از نفرت از خود، بلکه از عشق، از سپاسگزاری، از شناخت ساده و فراگیر اینکه تنها نیست."),
                    StoryParagraph("Sonya knelt beside him and held him, and she too wept, and in that moment, on the cold, distant soil of Siberia, both of them began, at last, to heal from the wounds that life had given them.", "سونیا کنارش زانو زد و او را در آغوش گرفت و او هم گریست و در آن لحظه، روی خاک سرد و دورافتاده سیبری، هر دوی آن‌ها بالاخره شروع کردند به بهبودی از زخم‌هایی که زندگی به آن‌ها زده بود."),
                    StoryParagraph("Raskolnikov still had many years of his sentence to serve, and he knew that the road ahead would be long and difficult, but for the first time in his life, he had something worth serving his sentence for.", "راسکولنیکوف هنوز سال‌های بسیاری از محکومیتش را باید می‌گذراند و می‌دانست که راه پیش رو طولانی و دشوار خواهد بود، اما برای اولین بار در زندگی‌اش، چیزی داشت که ارزش گذراندن دوران محکومیتش را داشته باشد."),
                    StoryParagraph("He had killed two women because he believed he was extraordinary, because he believed the rules of ordinary men did not apply to him, and now, sitting in a prison in Siberia, he finally understood how wrong he had been.", "او دو زن را کشته بود چون باور داشت استثنایی است، چون باور داشت قوانین مردان معمولی به او مربوط نمی‌شود و حالا، در زندانی در سیبری نشسته، بالاخره فهمید که چقدر اشتباه کرده بود."),
                    StoryParagraph("There were no extraordinary men, he realized, or rather, every man was extraordinary, in his own small way, and the only true greatness lay not in rising above others, but in loving them.", "مرد استثنایی وجود نداشت، دریافت، یا بهتر بگویم، هر انسانی استثنایی بود، به شیوه کوچک خودش و تنها عظمت واقعی در برتری از دیگران نبود، بلکه در دوست داشتن آن‌ها بود."),
                    StoryParagraph("Sonya had taught him this, not with words or arguments or theories, but with her life, with her quiet sacrifice, with the way she gave everything she had and asked for nothing in return.", "سونیا این را به او آموخته بود، نه با کلمات یا بحث یا نظریه‌ها، بلکه با زندگی‌اش، با فداکاری آرامش، با شیوه‌ای که هر چه داشت می‌داد و در عوض چیزی نمی‌خواست."),
                    StoryParagraph("When the novel ends, Raskolnikov still has seven years of his sentence left to serve, and he is still on the long road towards true peace, but he is no longer alone on that road.", "وقتی رمان به پایان می‌رسد، راسکولنیکوف هنوز هفت سال از محکومیتش را باید بگذراند و هنوز در مسیر طولانی به سوی آرامش واقعی است، اما دیگر در آن مسیر تنها نیست."),
                    StoryParagraph("Sonya remains by his side, patient and loving, and every Sunday, she still comes to visit him, and every Sunday, they sit together and talk about the future they will build when he is free.", "سونیا کنارش می‌ماند، صبور و پر عشق و هر یکشنبه هنوز به دیدنش می‌آید و هر یکشنبه با هم می‌نشینند و درباره آینده‌ای که وقتی آزاد شود خواهند ساخت حرف می‌زنند."),
                    StoryParagraph("And slowly, painfully, one day at a time, the man who had once believed himself to be above all other men was learning, at last, what it truly means to be human.", "و آهسته، دردناک، روزی یکی، مردی که زمانی خودش را بالاتر از همه مردان دیگر می‌دانست، بالاخره داشت می‌آموخت معنای واقعی انسان بودن چیست."),
                    StoryParagraph("This was the redemption that Dostoevsky wanted his readers to find, hidden beneath all the suffering and the crime — the quiet, humble truth that love could heal what nothing else could.", "این همان رستگاری بود که داستایوفسکی می‌خواست خوانندگانش آن را بیابند، پنهان در زیر تمام رنج و جنایت — حقیقت آرام و فروتنانه‌ای که عشق می‌توانست چیزی را درمان کند که هیچ چیز دیگری نمی‌توانست.")
                )
            )
        )
    )

    // ─────────────── ۲: آنا کارنینا ───────────────
    private fun story2() = StoryContent(
        storyId = "adv_anna_karenina",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "A Family in Crisis", titlePersian = "خانواده‌ای در بحران",
                paragraphs = listOf(
                    StoryParagraph("All happy families are alike; each unhappy family is unhappy in its own way.", "همه خانواده‌های خوشبخت شبیه هم هستند؛ هر خانواده بدبختی به شیوه خودش بدبخت است."),
                    StoryParagraph("This truth, which has echoed through the ages, now unfolds in the household of Prince Stepan Arkadyevich Oblonsky.", "این حقیقت که در طول قرن‌ها طنین انداخته، حالا در خانه شاهزاده استپان آرکادیویچ ابلونسکی آشکار می‌شود."),
                    StoryParagraph("Stiva, as his friends call him, has been discovered by his wife Dolly in an affair with the French governess, and the entire household has fallen into chaos.", "استیوا، همان‌طور که دوستانش صدایش می‌زنند، توسط همسرش دالی در رابطه‌ای با معلم سرخانه فرانسوی کشف شده و تمام خانه در آشفتگی فرو رفته است."),
                    StoryParagraph("For three days now, Dolly has refused to leave her rooms, and she has forbidden anyone to mention her husband's name in her presence.", "سه روز است که دالی از ترک اتاق‌هایش امتناع می‌کند و به هیچ‌کس اجازه نداده در حضورش نام شوهرش را ببرد."),
                    StoryParagraph("The children, sensing their mother's distress without understanding its cause, have become anxious and unruly, and the servants, uncertain how to behave, move through the house like ghosts.", "بچه‌ها، که ناراحتی مادرشان را بدون درک علتش حس می‌کنند، مضطرب و سرکش شده‌اند و خدمتکاران که نمی‌دانند چطور رفتار کنند، مثل ارواح در خانه حرکت می‌کنند."),
                    StoryParagraph("Stiva, for his part, is filled with self-reproach, but his remorse is shallow and easily forgotten, because Stiva is a man for whom pleasure has always come before duty.", "استیوا، از طرف خودش، پر از سرزنش خود است، اما پشیمانی‌اش سطحی و به‌راحتی فراموش می‌شود، چون استیوا مردی است که برایش لذت همیشه بر وظیفه مقدم بوده است."),
                    StoryParagraph("He has no intention of changing his way of life, no real desire to become a better man; he only wishes the whole unpleasant business would resolve itself quickly.", "او قصد ندارد شیوه زندگی‌اش را عوض کند، هیچ تمایل واقعی به بهتر شدن ندارد؛ فقط آرزو می‌کند کل این ماجرای ناخوشایند به سرعت خودش را حل کند."),
                    StoryParagraph("In his desperation, Stiva sends a telegram to his sister, Anna Arkadyevna Karenina, in Petersburg, begging her to come to Moscow and help him save his marriage.", "در ناچاری، استیوا تلگرافی به خواهرش، آنا آرکادیونا کارنینا، در پترزبورگ می‌فرستد و التماس می‌کند به مسکو بیاید و کمکش کند ازدواجش را نجات دهد."),
                    StoryParagraph("Anna is the wife of Alexei Alexandrovich Karenin, a senior government official twenty years her senior, a man of cold precision and unbending principle.", "آنا همسر آلکسی آلکساندراویچ کارنین است، مقامی بلندپایه دولتی بیست سال بزرگ‌تر از او، مردی با دقت سرد و اصولی تسلیم‌ناپذیر."),
                    StoryParagraph("Her marriage was never a union of love; it was an arrangement, a social contract, a transaction that had been negotiated by their families when she was barely out of girlhood.", "ازدواجش هرگز پیوندی از عشق نبود؛ ترتیبی بود، قراردادی اجتماعی، معامله‌ای که خانواده‌هایشان وقتی او به سختی از دختری خارج شده بود مذاکره کرده بودند."),
                    StoryParagraph("Karenin has never understood his wife, has never tried to understand her, has never felt the slightest curiosity about the depths of her soul.", "کارنین هرگز همسرش را نفهمیده، هرگز تلاش نکرده بفهمدش، هرگز کمترین کنجکاوی درباره اعماق روحش حس نکرده است."),
                    StoryParagraph("He treats her as he treats his work: with efficiency, with correctness, with a complete absence of warmth.", "او با او همانطور رفتار می‌کند که با کارش رفتار می‌کند: با کارآمدی، با درستی، با فقدان کامل گرما."),
                    StoryParagraph("When the telegram arrives, Anna is sitting in her elegant Petersburg drawing room, reading a French novel, and she feels, upon reading her brother's words, a mixture of pity and amusement.", "وقتی تلگراف می‌رسد، آنا در نشیمن شیک پترزبورگش نشسته و رمانی فرانسوی می‌خواند و با خواندن حرف‌های برادرش، آمیزه‌ای از ترحم و سرگرمی حس می‌کند."),
                    StoryParagraph("She loves Stiva despite all his faults, because she sees in him a warmth and a humanity that her husband utterly lacks.", "او استیوا را با وجود همه عیب‌هایش دوست دارد، چون در او گرمایی و انسانیتی می‌بیند که شوهرش کاملاً از آن بی‌بهره است."),
                    StoryParagraph("She decides, without hesitation, to go to Moscow, to help her brother, to heal what has been broken.", "او بدون تردید تصمیم می‌گیرد به مسکو برود، به برادرش کمک کند، آنچه شکسته را درمان کند."),
                    StoryParagraph("Her husband, when she informs him of her plan, responds with his usual cold politeness, saying only that he hopes her journey will be useful and that she should not stay away too long from their son Seryozha.", "شوهرش وقتی از نقشه‌اش باخبرش می‌کند، با ادب سرد همیشگی‌اش پاسخ می‌دهد و فقط می‌گوید امیدوار است سفرش مفید باشد و نباید زیاد از پسرشان سریوژا دور بماند."),
                    StoryParagraph("There is no affection in his words, no concern for her well-being, no curiosity about her feelings; there is only the dry formality of a man who has never learned to love.", "در حرف‌هایش محبتی نیست، نگرانی‌ای برای رفاهش نیست، کنجکاوی‌ای درباره احساساتش نیست؛ فقط رسمیت خشک مردی است که هرگز یاد نگرفته عشق بورزد."),
                    StoryParagraph("The next morning, Anna boards the night train to Moscow, and as the snow-covered fields of Russia rush past her window, she feels a strange, unfamiliar excitement stirring in her heart.", "صبح روز بعد، آنا سوار قطار شبانه به مسکو می‌شود و در حالی که دشت‌های پوشیده از برف روسیه از پنجره‌اش می‌گذرند، هیجانی عجیب و ناآشنا در قلبش حس می‌کند."),
                    StoryParagraph("She does not know why she feels this way, does not try to understand it; she only knows that she is leaving behind, for a little while, the cold formality of her life in Petersburg.", "نمی‌داند چرا اینطور حس می‌کند، تلاش نمی‌کند بفهمد؛ فقط می‌داند برای مدتی کوتاه، رسمیت سرد زندگی‌اش در پترزبورگ را پشت سر می‌گذارد."),
                    StoryParagraph("At the Moscow railway station, she is met by her brother Stiva, whose handsome face is clouded with shame and whose cheerful eyes cannot quite meet hers.", "در ایستگاه راه‌آهن مسکو، برادرش استیوا به استقبالش می‌آید، چهره خوش‌قیافه‌اش از شرم ابری است و چشمان شادش نمی‌توانند مستقیم به او نگاه کنند."),
                    StoryParagraph("He embraces her warmly, as he always does, and thanks her again and again for coming, and he tells her, with his usual carelessness, that everything will surely work out in the end.", "او مثل همیشه گرم در آغوشش می‌گیرد و بارها و بارها از آمدنش تشکر می‌کند و با بی‌خیالی همیشگی‌اش می‌گوید که مطمئناً در نهایت همه چیز حل می‌شود."),
                    StoryParagraph("As they walk through the crowded station toward the exit, Anna notices, in a group of waiting passengers, a young officer with a kind and serious face, whose eyes, for a brief moment, meet hers.", "در حالی که از میان ایستگاه شلوغ به سمت خروجی می‌روند، آنا در میان گروهی از مسافران منتظر، افسر جوانی با چهره‌ای مهربان و جدی می‌بیند که چشمانش برای لحظه‌ای کوتاه به چشمان او می‌افتد."),
                    StoryParagraph("At that very moment, a terrible cry rises from somewhere on the platform, and everyone turns to see what has happened, and in the confusion that follows, Anna learns that a railway worker has fallen and been crushed by a passing train.", "در همان لحظه، فریاد هولناکی از جایی روی سکو بلند می‌شود و همه برمی‌گردند تا ببینند چه اتفاقی افتاده و در آشفتگی بعدی، آنا می‌فهمد که کارگری راه‌آهن افتاده و قطاری در حال عبور او را له کرده است."),
                    StoryParagraph("The young officer, whose name is Count Alexei Kirillovich Vronsky, rushes forward without hesitation to help, and he gives money to the widow of the dead man without a second thought.", "افسر جوان، که نامش کنت آلکسی کیریلوویچ ورونسکی است، بدون تردید برای کمک می‌شتابد و بی‌درنگ به بیوه مرد مرده پول می‌دهد."),
                    StoryParagraph("Anna is deeply moved by his kindness and by the tragedy she has just witnessed, and she feels, in that moment, that this day will somehow be important in her life.", "آنا از مهربانی او و از تراژدی‌ای که تازه دیده عمیقاً متأثر می‌شود و در آن لحظه حس می‌کند که این روز به‌نحوی در زندگی‌اش مهم خواهد بود."),
                    StoryParagraph("To her, the accident seems like a bad omen for her visit to Moscow, a dark shadow that falls across the beginning of something she does not yet understand.", "به نظرش، آن حادثه مثل فال بدی برای سفرش به مسکو می‌آید، سایه‌ای تاریک که بر آغاز چیزی که هنوز نمی‌فهمد می‌افتد."),
                    StoryParagraph("Vronsky, on his part, is struck by Anna's beauty and by the peculiar grace of her every movement, and he cannot stop himself from looking at her as she walks past him with her brother.", "ورونسکی هم از زیبایی آنا و از ظرافت عجیب هر حرکتش مسحور می‌شود و نمی‌تواند جلوی خودش را بگیرد که وقتی او با برادرش از کنارش می‌گذرد، نگاهش نکند."),
                    StoryParagraph("Although he is, at that time, paying court to Dolly's younger sister Kitty, a sweet and innocent girl of eighteen, he finds his thoughts drifting, again and again, back to the dark-eyed woman he has just seen.", "با اینکه در آن زمان به خواستگاری خواهر کوچک‌تر دالی، کیتی، دختری شیرین و معصوم هجده‌ساله می‌رود، متوجه می‌شود که افکارش بارها و بارها به زن سیاه‌چشمی که تازه دیده برمی‌گردد."),
                    StoryParagraph("Anna herself is unaware of the effect she has on him, just as she is unaware of the effect she has on almost everyone she meets, and all she wants, in those first days in Moscow, is to help her brother and his suffering wife.", "خود آنا از تأثیری که بر او گذاشته بی‌خبر است، همان‌طور که از تأثیری که بر تقریباً همه کسانی که ملاقات می‌کند بی‌خبر است و تنها چیزی که در آن روزهای اول در مسکو می‌خواهد این است که به برادرش و همسر رنج‌کشیده‌اش کمک کند."),
                    StoryParagraph("But she cannot forget the young officer's face, nor the strange sense of recognition she felt when their eyes met, and she knows, even then, that something has begun that cannot be stopped.", "اما نمی‌تواند چهره آن افسر جوان را فراموش کند، و نه حس عجیب آشنایی‌ای که وقتی چشمانشان به هم افتاد حس کرد و حتی همان موقع می‌داند که چیزی شروع شده که نمی‌شود متوقفش کرد."),
                    StoryParagraph("She arrives at Stiva's house, where she finds her sister-in-law Dolly in a state of utter despair, weeping in her room while her children play noisily in the next room, unaware of their parents' pain.", "به خانه استیوا می‌رسد و خواهرشوهرش دالی را در وضعیت ناامیدی مطلق می‌یابد، در اتاقش گریه می‌کند در حالی که بچه‌هایش در اتاق بعدی پر سر و صدا بازی می‌کنند و از رنج والدینشان بی‌خبرند."),
                    StoryParagraph("Anna sits with Dolly for hours, listening to her grief, holding her hand, and speaking to her with a gentleness that no one else in the family could have managed.", "آنا ساعت‌ها با دالی می‌نشیند، به غمش گوش می‌دهد، دستش را می‌گیرد و با مهربانی‌ای با او سخن می‌گوید که هیچ‌کس دیگر در خانواده نمی‌توانست."),
                    StoryParagraph("She does not defend her brother, does not make excuses for him, but she speaks to Dolly of forgiveness, of the strength of women, of the importance of holding a family together for the sake of the children.", "او از برادرش دفاع نمی‌کند، برایش بهانه نمی‌آورد، اما با دالی از بخشش می‌گوید، از قدرت زنان، از اهمیت حفظ خانواده برای خاطر بچه‌ها."),
                    StoryParagraph("By the end of the day, Dolly has agreed, reluctantly, to give Stiva another chance, not because she has forgiven him, but because she cannot imagine a life without him and her children.", "تا پایان روز، دالی به‌اکراه موافقت کرده به استیوا فرصت دیگری بدهد، نه چون بخشیده استش، بلکه چون نمی‌تواند زندگی‌ای بدون او و بچه‌هایش تصور کند."),
                    StoryParagraph("Anna is pleased with her success, but she is also troubled, because she knows in her heart that forgiving a man like Stiva is not the same as trusting him, and that Dolly's happiness might be fragile.", "آنا از موفقیتش خوشحال است، اما مضطرب هم هست، چون در قلبش می‌داند بخشیدن مردی مثل استیوا همان اعتماد کردن به او نیست و خوشبختی دالی ممکن است شکننده باشد."),
                    StoryParagraph("That evening, she attends a grand ball at the governor's house, and it is there, in that glittering hall of candles and music, that everything changes.", "آن شب، در رقصی باشکوه در خانه فرماندار شرکت می‌کند و آنجا است، در آن تالار پرزرق‌وبرق شمع و موسیقی، که همه چیز عوض می‌شود."),
                    StoryParagraph("Kitty, who loves Vronsky with all the innocence of her young heart, has been dreaming of this ball for weeks, and she wears a pale pink gown that makes her look like a princess.", "کیتی که با تمام معصومیت قلب جوانش عاشق ورونسکی است، هفته‌ها رویای این رقص را در سر داشته و لباس صورتی کم‌رنگی پوشیده که او را شبیه شاهزاده‌خانمی می‌کند."),
                    StoryParagraph("She believes that tonight, at last, Vronsky will propose to her, and she has rehearsed the moment in her mind so many times that she is certain of what will happen.", "باور دارد که امشب، بالاخره، ورونسکی خواستگاری‌اش می‌کند و آن لحظه را آنقدر بارها در ذهنش مرور کرده که از آنچه خواهد شد مطمئن است."),
                    StoryParagraph("But when Vronsky arrives, his eyes search the room for someone else, and when he finds Anna, standing quietly near a window in her simple black gown, he forgets entirely that Kitty exists.", "اما وقتی ورونسکی می‌رسد، چشمانش کس دیگری را در اتاق می‌جوید و وقتی آنا را می‌یابد که در لباس ساده سیاهش آرام نزدیک پنجره ایستاده، کاملاً فراموش می‌کند که کیتی وجود دارد."),
                    StoryParagraph("He walks over to Anna and asks her to dance the first waltz, and she accepts, and as they move together across the ballroom floor, something between them begins that neither of them can control.", "او به طرف آنا می‌رود و از او می‌خواهد اولین والس را برقصند و او می‌پذیرد و در حالی که با هم روی زمین تالار رقص می‌چرخند، چیزی میانشان شروع می‌شود که هیچ‌کدام نمی‌توانند کنترل کنند."),
                    StoryParagraph("Kitty watches from the side, and with every turn of the dance, her heart breaks a little more, until at last, unable to bear it any longer, she flees the ballroom in tears.", "کیتی از کنار تماشا می‌کند و با هر چرخی که می‌زنند قلبش کمی بیشتر می‌شکند، تا بالاخره، چون دیگر نتوانست تحمل کند، گریان از تالار فرار می‌کند."),
                    StoryParagraph("Anna notices Kitty's pain, and she feels a sharp pang of guilt, but even that guilt cannot stop her from dancing with Vronsky again and again, until the ball comes to an end.", "آنا درد کیتی را می‌بیند و نیش تندی از گناه حس می‌کند، اما حتی آن گناه هم نمی‌تواند مانعش شود که بارها و بارها با ورونسکی برقصد، تا وقتی رقص به پایان می‌رسد."),
                    StoryParagraph("That night, as she lies in her bed at Stiva's house, Anna tells herself that she has done nothing wrong, that she has only danced with a young man, that her feelings are foolish and will pass.", "آن شب، در حالی که در تختش در خانه استیوا دراز کشیده، آنا به خودش می‌گوید کار اشتباهی نکرده، فقط با جوانی رقصیده، احساساتش احمقانه‌اند و می‌گذرند."),
                    StoryParagraph("But deep inside, she knows the truth; she knows that something has awakened in her that she had long thought dead, and she knows that the safe, orderly life she has built for herself in Petersburg will never feel the same again.", "اما در عمق وجودش، حقیقت را می‌داند؛ می‌داند که چیزی در او بیدار شده که مدت‌ها فکر می‌کرد مرده است و می‌داند که زندگی امن و منظمی که در پترزبورگ برای خودش ساخته هرگز دیگر همان حس را نخواهد داشت."),
                    StoryParagraph("The next morning, she goes to see Dolly one last time before her departure, and she finds her sister-in-law calmer, ready to try again, grateful for Anna's help.", "صبح روز بعد، پیش از رفتنش یک بار آخر به دیدن دالی می‌رود و خواهرشوهرش را آرام‌تر می‌یابد، آماده تلاش دوباره، سپاسگزار برای کمک آنا."),
                    StoryParagraph("Anna embraces her warmly, and then she embraces the children, and then she goes to the station to catch the train back to Petersburg, hoping that distance will help her forget the young officer's face.", "آنا او را گرم در آغوش می‌گیرد و بعد بچه‌ها را در آغوش می‌گیرد و سپس به ایستگاه می‌رود تا قطار بازگشت به پترزبورگ را بگیرد، به امید آنکه فاصله کمکش کند چهره افسر جوان را فراموش کند."),
                    StoryParagraph("But when she steps onto the platform, she sees him again, standing there in the falling snow, waiting for her, and she knows, with a certainty that chills her, that he has followed her.", "اما وقتی روی سکو قدم می‌گذارد، او را دوباره می‌بیند، آنجا در برف در حال بارش ایستاده، منتظر او، و با اطمینانی که سردش می‌کند می‌داند که او دنبالش آمده است."),
                    StoryParagraph("Vronsky walks up to her and says, in a low voice, that he had to see her again, that he could not let her leave without telling her what he felt.", "ورونسکی به طرفش می‌رود و با صدایی آهسته می‌گوید که باید دوباره ببیندش، که نمی‌تواند بگذارد بدون آنکه احساساتش را به او بگوید برود."),
                    StoryParagraph("Anna tells him, calmly, that she is a married woman, that she loves her husband, that she loves her son, and that she does not want to hear such words from him ever again.", "آنا آرام به او می‌گوید که زنی متأهل است، شوهرش را دوست دارد، پسرش را دوست دارد و نمی‌خواهد هرگز دوباره چنین کلماتی از او بشنود."),
                    StoryParagraph("But even as she speaks these words, she knows they are not entirely true, and Vronsky, looking into her eyes, knows it too, and he smiles, not with triumph, but with a strange and sad tenderness.", "اما حتی همان‌طور که این کلمات را می‌گوید، می‌داند که کاملاً درست نیستند و ورونسکی، در حالی که به چشمانش نگاه می‌کند، او هم می‌داند و لبخند می‌زند، نه از پیروزی، بلکه با مهربانی عجیب و غمگینی."),
                    StoryParagraph("Anna boards the train, and as it pulls away from the station, she looks out the window and sees him standing there, watching her go, and she feels something inside her break.", "آنا سوار قطار می‌شود و وقتی قطار از ایستگاه دور می‌شود، از پنجره به بیرون نگاه می‌کند و او را می‌بیند که همان‌جا ایستاده و رفتنش را تماشا می‌کند و حس می‌کند چیزی در درونش شکست."),
                    StoryParagraph("She weeps quietly in her compartment, and she tells herself that she will forget him, that she will return to her old life, that everything will go back to the way it was before.", "در کوپه‌اش بی‌صدا گریه می‌کند و به خودش می‌گوید که فراموشش می‌کند، به زندگی قدیمی‌اش برمی‌گردد، همه چیز به همان شکلی که بود برمی‌گردد."),
                    StoryParagraph("But she knows, in the deepest part of her being, that she is lying to herself, and that the life she is returning to is not the same life at all, because she is no longer the same woman who had left it.", "اما در عمیق‌ترین بخش وجودش می‌داند که به خودش دروغ می‌گوید و زندگی‌ای که به آن برمی‌گردد اصلاً همان زندگی نیست، چون دیگر همان زنی نیست که ترکش کرده بود."),
                    StoryParagraph("She had been kissed by fate, and fate, once invited in, does not easily leave, and she knows that her life will be divided forever into the time before this moment and the time after it.", "تقدیر او را بوسیده بود و تقدیر، وقتی یک بار دعوت شود، به‌آسانی نمی‌رود و می‌داند که زندگی‌اش برای همیشه به زمان پیش از این لحظه و زمان پس از آن تقسیم می‌شود."),
                    StoryParagraph("The train rushes on through the winter night, carrying her back to Petersburg, to her husband, to her son, to the life she has promised to live.", "قطار در شب زمستانی به پیش می‌رود و او را به پترزبورگ برمی‌گرداند، نزد شوهرش، نزد پسرش، نزد زندگی‌ای که قول داده بگذراند."),
                    StoryParagraph("But even as it carries her home, she knows, with a certainty that terrifies her, that she is not going home at all, but towards something entirely new and entirely dangerous.", "اما حتی همان‌طور که او را به خانه می‌برد، با اطمینانی که وحشتزده‌اش می‌کند می‌داند که اصلاً به خانه نمی‌رود، بلکه به سوی چیزی کاملاً جدید و کاملاً خطرناک می‌رود."),
                    StoryParagraph("And so begins the story of Anna Karenina, the story of a woman who broke the rules of her society and paid for it with everything she had.", "و اینگونه داستان آنا کارنینا آغاز می‌شود، داستان زنی که قوانین جامعه‌اش را شکست و با هر چه داشت تاوانش را پرداخت."),
                    StoryParagraph("It is a story that has been told and retold for more than a century, and it will continue to be told as long as there are people who understand what it means to love beyond the boundaries of the permitted.", "داستانی است که بیش از یک قرن است تعریف و بازتعریف می‌شود و تا وقتی افرادی هستند که می‌فهمند عشق ورزیدن فراتر از مرزهای مجاز یعنی چه، همچنان تعریف خواهد شد.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Forbidden Love", titlePersian = "عشق ممنوع",
                paragraphs = listOf(
                    StoryParagraph("When Anna returns to Petersburg, she finds that the life she had left behind has not changed at all, but she herself has changed, and the change makes everything around her feel strange and cold.", "وقتی آنا به پترزبورگ بازمی‌گردد، می‌بیند زندگی‌ای که پشت سر گذاشته بود اصلاً تغییر نکرده، اما خودش تغییر کرده و این تغییر همه چیز اطرافش را عجیب و سرد می‌کند."),
                    StoryParagraph("Her husband Alexei Alexandrovich, as always, greets her with formal politeness, asking about her journey, her brother's health, and her sister-in-law's situation, without a single question that suggests he truly cares.", "شوهرش آلکسی آلکساندراویچ، مثل همیشه، با ادب رسمی به استقبالش می‌آید و درباره سفرش، سلامت برادرش و وضعیت خواهرشوهرش می‌پرسد، بدون حتی یک سؤال که نشان دهد واقعاً اهمیت می‌دهد."),
                    StoryParagraph("Their son Seryozha, however, runs into her arms with all the joy of a child who has missed his mother, and for a few moments, Anna feels that perhaps she really is home.", "اما پسرشان سریوژا با تمام شادی بچه‌ای که دلتنگ مادرش شده به آغوشش می‌دود و برای چند لحظه، آنا حس می‌کند که شاید واقعاً به خانه برگشته است."),
                    StoryParagraph("She spends the next few days in her usual routine, visiting friends, attending dinners, receiving guests, and every day, she tells herself that the strange excitement she felt in Moscow was nothing but a passing fancy.", "روزهای بعد را در روال همیشگی‌اش می‌گذراند، به دیدن دوستان می‌رود، در شام‌ها شرکت می‌کند، مهمان می‌پذیرد و هر روز به خودش می‌گوید هیجان عجیبی که در مسکو حس کرده فقط هوسی گذرا بوده است."),
                    StoryParagraph("But she cannot quite believe her own words, because every time she closes her eyes, she sees Vronsky's face, and every time she hears footsteps behind her, she turns, half-hoping, half-fearing, that it will be him.", "اما نمی‌تواند کاملاً به حرف‌های خودش باور داشته باشد، چون هر بار چشمانش را می‌بندد چهره ورونسکی را می‌بیند و هر بار صدای قدم‌هایی پشت سرش می‌شنود برمی‌گردد، نیمی امیدوار، نیمی هراسان، که او باشد."),
                    StoryParagraph("Then, a few weeks after her return, she sees him at a party, standing across the room, looking at her with those serious eyes that she remembers so well.", "سپس، چند هفته پس از بازگشتش، در مهمانی می‌بیندش، آن طرف اتاق ایستاده و با همان چشمان جدی که خوب به یاد دارد نگاهش می‌کند."),
                    StoryParagraph("Her heart stops, then races, then stops again, and she has to sit down because her legs will not hold her, and she knows then that all her efforts to forget him have been in vain.", "قلبش می‌ایستد، سپس تند می‌زند، سپس دوباره می‌ایستد و مجبور می‌شود بنشیند چون پاهایش نگهش نمی‌دارند و آن موقع می‌داند که تمام تلاش‌هایش برای فراموش کردنش بیهوده بوده است."),
                    StoryParagraph("From that evening onwards, Vronsky begins to appear everywhere Anna goes: at balls, at the theater, at the homes of mutual friends, at dinners, at concerts, at every possible place where polite society gathers.", "از آن شب به بعد، ورونسکی شروع می‌کند در هر جایی که آنا می‌رود ظاهر شدن: در رقص‌ها، در تئاتر، در خانه‌های دوستان مشترک، در شام‌ها، در کنسرت‌ها، در هر جای ممکنی که جامعه مؤدبانه جمع می‌شود."),
                    StoryParagraph("He does not speak to her of love again, but he does not need to, because his presence speaks louder than any words could, and everyone around them begins to notice.", "او دیگر با او از عشق حرف نمی‌زند، اما نیازی نیست، چون حضورش بلندتر از هر کلمه‌ای سخن می‌گوید و همه اطرافیانشان شروع می‌کنند به توجه."),
                    StoryParagraph("Society, which had once welcomed Anna as one of its most admired women, begins to whisper behind her back, to raise eyebrows, to exchange meaningful glances whenever she enters a room.", "جامعه‌ای که زمانی آنا را به‌عنوان یکی از محبوب‌ترین زنانش پذیرفته بود، شروع می‌کند پشت سرش پچ‌پچ کردن، ابرو بالا بردن، نگاه‌های معنادار ردوبدل کردن هر بار که وارد اتاقی می‌شود."),
                    StoryParagraph("Her husband, who is too proud to ask and too cold to care, says nothing for a long time, but Anna can feel his disapproval growing like a silent pressure around her.", "شوهرش که بیش از حد مغرور است که بپرسد و بیش از حد سرد که اهمیت دهد، مدت طولانی چیزی نمی‌گوید، اما آنا می‌تواند نارضایتی‌اش را مثل فشاری خاموش دور خودش حس کند."),
                    StoryParagraph("One evening, after a particularly painful party where she has felt the eyes of everyone upon her, Karenin finally speaks to her about it in his calm, measured voice.", "یک شب، پس از مهمانی‌ای به‌ویژه دردناک که در آن نگاه همه را روی خودش حس کرده، کارنین بالاخره با صدای آرام و سنجیده‌اش درباره‌اش با او صحبت می‌کند."),
                    StoryParagraph("He reminds her of her duties as a wife and a mother, of the importance of reputation, of the sacredness of the family, and he asks her, without anger but with cold authority, to end whatever it is that is going on.", "او وظایفش را به‌عنوان همسر و مادر یادآوری می‌کند، اهمیت آبرو را، قداست خانواده را و بدون خشم اما با اقتدار سردی از او می‌خواهد هر چه در جریان است را تمام کند."),
                    StoryParagraph("Anna listens to him in silence, and when he has finished, she simply says that she has done nothing wrong, that she is merely a friend of Count Vronsky, and that her husband has no right to speak to her in such a way.", "آنا در سکوت به او گوش می‌دهد و وقتی تمام می‌کند، فقط می‌گوید که کار اشتباهی نکرده، فقط دوست کنت ورونسکی است و شوهرش حق ندارد با او چنین حرف بزند."),
                    StoryParagraph("But even as she says these words, she knows they are not true, and Karenin knows it too, and the distance between them, which has always been there, suddenly becomes an ocean.", "اما حتی همان‌طور که این کلمات را می‌گوید، می‌داند که درست نیستند و کارنین هم می‌داند و فاصله‌ای که همیشه میانشان بود، ناگهان به اقیانوسی تبدیل می‌شود."),
                    StoryParagraph("That night, Anna lies awake for hours, and for the first time since her return, she allows herself to think, honestly, about what she truly wants.", "آن شب، آنا ساعت‌ها بیدار دراز می‌کشد و برای اولین بار پس از بازگشتش، به خودش اجازه می‌دهد صادقانه فکر کند که واقعاً چه می‌خواهد."),
                    StoryParagraph("She wants Vronsky, she wants to be free, she wants to live a life that is truly hers, and yet she also loves her son, respects her husband in a strange, unfeeling way, and does not want to lose the world that has made her who she is.", "ورونسکی را می‌خواهد، می‌خواهد آزاد باشد، می‌خواهد زندگی‌ای داشته باشد که واقعاً مال خودش باشد و با این حال پسرش را هم دوست دارد، به‌طرز عجیب و بی‌احساسی به شوهرش احترام می‌گذارد و نمی‌خواهد دنیایی را از دست بدهد که او را آن کسی ساخته که بود."),
                    StoryParagraph("It is an impossible situation, and she knows it, and yet she cannot bring herself to do what is expected of her, which is to turn Vronsky away once and for all.", "وضعیتی غیرممکن است و می‌داند و با این حال نمی‌تواند خودش را راضی کند کاری که از او انتظار می‌رود را انجام دهد، یعنی ورونسکی را برای همیشه براند."),
                    StoryParagraph("A few days later, at a horse race in which Vronsky is riding, Anna attends with her husband, and she watches with her heart in her throat as the young officer races towards the finish line.", "چند روز بعد، در مسابقه اسب‌دوانی‌ای که ورونسکی در آن می‌تازد، آنا با شوهرش شرکت می‌کند و با قلبش در گلویش تماشا می‌کند که آن افسر جوان به سمت خط پایان می‌تازد."),
                    StoryParagraph("Then, just as he is about to win, something goes wrong; his horse stumbles, and he falls to the ground, and Anna, unable to control herself, cries out loud in front of the entire crowd.", "سپس، درست وقتی دارد برنده می‌شود، چیزی اشتباه می‌شود؛ اسبش لیز می‌خورد و او روی زمین می‌افتد و آنا که نمی‌تواند خودش را کنترل کند، در برابر تمام جمعیت بلند فریاد می‌کشد."),
                    StoryParagraph("The sound of her cry silences the crowd, and everyone turns to look at her, and her husband, sitting beside her, feels every eye upon them both, and knows, in that moment, that everything has been exposed.", "صدای فریادش جمعیت را ساکت می‌کند و همه برمی‌گردند که به او نگاه کنند و شوهرش که کنارش نشسته، نگاه همه را روی هر دو حس می‌کند و در آن لحظه می‌داند که همه چیز آشکار شده است."),
                    StoryParagraph("Anna herself realizes immediately what she has done, and she looks at her husband with a strange mixture of fear and defiance, and in that look, Karenin sees the truth he has been avoiding.", "خود آنا هم فوراً می‌فهمد چه کرده و با آمیزه عجیبی از ترس و سرکشی به شوهرش نگاه می‌کند و در آن نگاه، کارنین حقیقتی را می‌بیند که از آن دوری می‌کرد."),
                    StoryParagraph("That night, in the carriage on the way home, Karenin confronts her with cold fury, and for the first time in their marriage, he allows his true feelings to show.", "آن شب، در کالسکه در راه خانه، کارنین با خشمی سرد با او روبرو می‌شود و برای اولین بار در ازدواجشان، اجازه می‌دهد احساسات واقعی‌اش نمایان شود."),
                    StoryParagraph("He tells her that he has known for some time, that he had hoped she would come to her senses, that he does not care about love but he cares deeply about propriety, and that he will not be made a fool of by her.", "او به او می‌گوید که مدتی است می‌داند، امیدوار بود به خودش بیاید، به عشق اهمیت نمی‌دهد اما به آبرو عمیقاً اهمیت می‌دهد و اجازه نمی‌دهد او دستش بیندازد."),
                    StoryParagraph("Anna, exhausted by years of pretending, finally breaks, and she confesses, in a voice that is almost calm, that she loves Vronsky, that she cannot help it, that she is sorry but she cannot be sorry enough to stop.", "آنا که از سال‌ها تظاهر خسته شده، بالاخره فرو می‌ریزد و با صدایی که تقریباً آرام است اعتراف می‌کند که ورونسکی را دوست دارد، نمی‌تواند جلویش را بگیرد، متأسف است اما نمی‌تواند آنقدر متأسف باشد که متوقف شود."),
                    StoryParagraph("Karenin listens to her in silence, and when she has finished, he tells her, in the same cold voice he has used all their married life, that he will not grant her a divorce and that he will not let her see her son if she leaves him.", "کارنین در سکوت به او گوش می‌دهد و وقتی تمام می‌کند، با همان صدای سردی که تمام زندگی زناشویی‌شان به کار برده می‌گوید که به او طلاق نمی‌دهد و اگر ترکش کند اجازه نمی‌دهد پسرش را ببیند."),
                    StoryParagraph("Anna is stunned by his words, and she realizes, in that moment, that her husband is not the weak, cold man she has always dismissed him as, but a man who will fight back with every weapon he has.", "آنا از کلماتش شوکه می‌شود و در آن لحظه می‌فهمد که شوهرش آن مرد ضعیف و سردی که همیشه دست‌کمش می‌گرفت نبود، بلکه مردی است که با هر سلاحی که دارد می‌جنگد."),
                    StoryParagraph("But she also realizes, in that same moment, that she does not care; she loves Vronsky, and she would rather lose everything than continue to live a lie.", "اما در همان لحظه می‌فهمد که اهمیت نمی‌دهد؛ ورونسکی را دوست دارد و ترجیح می‌دهد همه چیز را از دست بدهد تا به زندگی در دروغ ادامه دهد."),
                    StoryParagraph("A few weeks later, she leaves her husband's house and goes to live with Vronsky, and from that day on, society closes its doors to her, one by one, until she finds herself almost entirely alone.", "چند هفته بعد، خانه شوهرش را ترک می‌کند و می‌رود با ورونسکی زندگی کند و از آن روز به بعد، جامعه درهایش را یکی‌یکی به رویش می‌بندد، تا خودش را تقریباً کاملاً تنها می‌یابد."),
                    StoryParagraph("Her old friends will not receive her, her old acquaintances will not greet her in public, and even the servants in shops look at her with knowing, disapproving eyes.", "دوستان قدیمی‌اش دیگر نمی‌پذیرندش، آشنایان قدیمی‌اش در ملا عام به او سلام نمی‌کنند و حتی پیشخدمت‌های مغازه‌ها با نگاهی دانا و نارضایتی به او نگاه می‌کنند."),
                    StoryParagraph("Only a few people remain loyal to her, and among them is her brother Stiva, who, with his usual carelessness, says that he cannot judge her, because he himself has done worse things and no one has punished him for them.", "فقط چند نفر به او وفادار می‌مانند و از جمله آن‌ها برادرش استیوا است که با بی‌خیالی همیشگی‌اش می‌گوید نمی‌تواند قضاوتش کند، چون خودش کارهای بدتری کرده و هیچ‌کس مجازاتش نکرده است."),
                    StoryParagraph("Anna is grateful for his support, but she is also aware of the double standard, and she knows that no amount of argument will ever change the world's mind about her.", "آنا برای حمایتش سپاسگزار است، اما از استاندارد دوگانه هم آگاه است و می‌داند هیچ استدلالی هرگز نظر دنیا را درباره‌اش تغییر نمی‌دهد."),
                    StoryParagraph("She and Vronsky live together in his apartment in Petersburg, and at first, they are happy, or at least as happy as two people in their situation can be.", "او و ورونسکی در آپارتمانش در پترزبورگ با هم زندگی می‌کنند و اول، خوشحال هستند، یا حداقل تا آنجا که دو نفر در موقعیت آن‌ها می‌توانند خوشحال باشند."),
                    StoryParagraph("But the shadow of what she has lost hangs over everything, and Anna, for all her courage, cannot stop thinking about her son Seryozha, who is now forbidden to see her.", "اما سایه آنچه از دست داده بر همه چیز آویزان است و آنا با تمام شجاعتش نمی‌تواند از فکر کردن به پسرش سریوژا که حالا دیدنش برایش ممنوع است دست بکشد."),
                    StoryParagraph("She writes him letters, which Karenin tears up without showing them, and she asks visitors to carry messages to him, and she spends hours staring at his photograph in silent grief.", "برای او نامه می‌نویسد که کارنین بدون نشان دادنشان پاره می‌کند و از ملاقات‌کنندگان می‌خواهد پیام‌هایی به او برسانند و ساعت‌ها به عکسش خیره می‌شود، در غم خاموش."),
                    StoryParagraph("Vronsky tries to comfort her, but he does not understand, because he has never loved anyone as she loves her son, and he cannot see why she will not simply move on.", "ورونسکی تلاش می‌کند دلداری‌اش دهد، اما نمی‌فهمد، چون او هرگز کسی را آنقدر که آنا پسرش را دوست دارد دوست نداشته و نمی‌فهمد چرا او به‌سادگی رها نمی‌کند."),
                    StoryParagraph("This is the first crack in their relationship, small at first, but growing slowly wider with every passing day, until it becomes a chasm that neither of them can cross.", "این اولین ترک در رابطه‌شان است، اول کوچک، اما آهسته با هر روزی که می‌گذرد پهن‌تر می‌شود، تا به شکافی تبدیل می‌شود که هیچ‌کدام نمی‌توانند از آن عبور کنند."),
                    StoryParagraph("And so, even in the first months of their life together, the seeds of their destruction have already been planted, waiting patiently for the right moment to grow.", "و بنابراین، حتی در همان ماه‌های اول زندگی مشترکشان، بذرهای نابودی‌شان از قبل کاشته شده است، صبورانه منتظر لحظه مناسب برای رشد."),
                    StoryParagraph("Tolstoy understood, better than any writer of his age, that love alone was not enough to sustain a life, and that society, for all its hypocrisy, had powers that no individual could fight forever.", "تولستوی بهتر از هر نویسنده عصرش می‌فهمید که عشق به‌تنهایی برای نگه داشتن یک زندگی کافی نیست و جامعه با تمام ریاکاری‌اش قدرت‌هایی داشت که هیچ فردی نمی‌توانست تا ابد با آن‌ها بجنگد.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Public Scandal", titlePersian = "رسوایی عمومی",
                paragraphs = listOf(
                    StoryParagraph("Karenin finally learns the truth in the most humiliating way possible: through a letter from a society woman who claims to be his friend and who writes to inform him of his wife's affair with Count Vronsky.", "کارنین بالاخره حقیقت را به تحقیرآمیزترین شکل ممکن می‌فهمد: از طریق نامه‌ای از زنی اشرافی که ادعا می‌کند دوستش است و می‌نویسد تا او را از رابطه همسرش با کنت ورونسکی باخبر کند."),
                    StoryParagraph("He reads the letter three times, sitting alone in his study, and each time he reads it, his face grows paler and his hands begin to tremble more violently.", "او نامه را سه بار می‌خواند، تنهای تنها در دفترش نشسته و هر بار که می‌خواندش، صورتش رنگ‌پریده‌تر می‌شود و دست‌هایش شدیدتر می‌لرزند."),
                    StoryParagraph("But when he rises from his chair, his expression is once again cold and impassive, and his movements are once again precise and controlled, because Karenin has spent his entire life learning to suppress every emotion that might make him appear weak.", "اما وقتی از صندلی بلند می‌شود، حالتش دوباره سرد و بی‌احساس است و حرکاتش دوباره دقیق و کنترل‌شده، چون کارنین تمام عمرش را صرف آموختن سرکوب هر احساسی کرده که ممکن بود ضعیف نشانش دهد."),
                    StoryParagraph("He does not challenge Vronsky to a duel, as many men of his class would have done, because he considers duels barbaric and irrational, and because he has no intention of risking his own life over a matter of mere personal honor.", "او ورونسکی را به دوئل دعوت نمی‌کند، همان‌طور که بسیاری از مردان طبقه‌اش می‌کردند، چون دوئل را وحشیانه و غیرعقلانی می‌داند و چون قصد ندارد جان خودش را بر سر موضوعی از شرافت شخصی محض به خطر بیندازد."),
                    StoryParagraph("He does not seek a divorce, because a public trial would expose his private humiliation to the entire world, and because he believes that even a broken marriage should be preserved for the sake of appearances.", "او طلاق نمی‌خواهد، چون محاکمه علنی تحقیر خصوصی‌اش را به تمام دنیا نشان می‌دهد و چون باور دارد حتی ازدواج شکسته هم باید به خاطر ظاهر حفظ شود."),
                    StoryParagraph("Instead, he decides on a course of action that is both crueler and more calculated: he will continue the marriage in name only, will keep Anna as his wife in the eyes of the law, but will deprive her of everything that makes a marriage worth having.", "در عوض، تصمیم به روشی می‌گیرد که هم بی‌رحمانه‌تر و هم حساب‌شده‌تر است: ازدواج را فقط اسمی ادامه می‌دهد، آنا را در نظر قانون به‌عنوان همسرش نگه می‌دارد، اما هر چیزی که ازدواج را ارزش زیستن می‌بخشد از او دریغ می‌کند."),
                    StoryParagraph("He will not divorce her, will not let her see Seryozha, will not allow her to live in his house, will not even permit her to keep the money that is technically hers, and in this way, he will punish her without ever raising his voice.", "او طلاقش نمی‌دهد، اجازه نمی‌دهد سریوژا را ببیند، اجازه نمی‌دهد در خانه‌اش زندگی کند، حتی اجازه نمی‌دهد پولی که رسماً مال خودش است را نگه دارد و به این شکل، بدون آنکه هرگز صدایش را بلند کند، مجازاتش می‌کند."),
                    StoryParagraph("When he informs Anna of this decision, he speaks in the same calm, measured voice he has always used, and he does not look at her as he speaks, but stares instead at the window as if she were not in the room.", "وقتی این تصمیم را به آنا اطلاع می‌دهد، با همان صدای آرام و سنجیده‌ای که همیشه به کار برده صحبت می‌کند و همان‌طور که صحبت می‌کند به او نگاه نمی‌کند، بلکه به پنجره خیره می‌شود گویی او در اتاق نیست."),
                    StoryParagraph("Anna listens in silence, and when he has finished, she does not argue, does not plead, does not scream, because she knows that no argument, no plea, no scream will move a man who has decided to be unmovable.", "آنا در سکوت گوش می‌دهد و وقتی تمام می‌کند، نه بحث می‌کند، نه التماس، نه جیغ می‌کشد، چون می‌داند هیچ استدلالی، هیچ التماسی، هیچ جیغی مردی را که تصمیم گرفته تسلیم‌ناپذیر باشد حرکت نمی‌دهد."),
                    StoryParagraph("She simply looks at him for a long moment, and then she says, in a voice that is almost peaceful, that she has never hated anyone as much as she hates him now.", "او فقط لحظه‌ای طولانی نگاهش می‌کند و بعد با صدایی که تقریباً آرام است می‌گوید که هرگز از هیچ‌کس آنقدر که حالا از او متنفر است متنفر نبوده."),
                    StoryParagraph("She leaves the house that same day, taking only what she can carry, and she goes to Vronsky, and she tells him that she has lost everything for him, that she has nothing left but him.", "او همان روز خانه را ترک می‌کند و فقط آنچه می‌تواند حمل کند می‌برد و به سراغ ورونسکی می‌رود و به او می‌گوید که همه چیز را برایش از دست داده، جز او چیزی برایش نمانده است."),
                    StoryParagraph("Vronsky, who is young and in love and has never truly understood the price that Anna is paying, tells her that they will go abroad, that they will start a new life, that they will be happy.", "ورونسکی، که جوان و عاشق است و هرگز واقعاً بهایی که آنا می‌پردازد را نفهمیده، به او می‌گوید که به خارج می‌روند، زندگی جدیدی شروع می‌کنند، خوشحال خواهند بود."),
                    StoryParagraph("But Anna knows, even as he speaks, that happiness is not something one can simply decide to have, and that the world they have left behind will follow them wherever they go.", "اما آنا می‌داند، همان‌طور که او صحبت می‌کند، که خوشبختی چیزی نیست که آدم به‌سادگی تصمیم بگیرد داشته باشد و دنیایی که پشت سر گذاشته‌اند هر جا بروند دنبالشان می‌آید."),
                    StoryParagraph("In the months that follow, Anna discovers the true cost of her choice.", "در ماه‌های بعدی، آنا بهای واقعی انتخابش را کشف می‌کند."),
                    StoryParagraph("She discovers that she is not welcome in polite society in Russia, that her old friends no longer answer her letters, that her very name has become a byword for scandal.", "او کشف می‌کند که در جامعه مؤدبانه روسیه پذیرفته نیست، دوستان قدیمی‌اش دیگر به نامه‌هایش جواب نمی‌دهند، خود نامش به کنایه‌ای برای رسوایی تبدیل شده است."),
                    StoryParagraph("She discovers that Vronsky, though he loves her, does not understand her suffering, that he cannot comprehend the depth of her loss, that he cannot fill the void that her son's absence has left in her heart.", "او کشف می‌کند که ورونسکی، هرچند دوستش دارد، رنجش را نمی‌فهمد، نمی‌تواند عمق فقدانش را درک کند، نمی‌تواند خالی‌بودنی که غیبت پسرش در قلبش گذاشته را پر کند."),
                    StoryParagraph("She discovers that she has become, in the eyes of the world, not a woman who followed her heart, but a woman who betrayed her husband, abandoned her child, and disgraced her family.", "او کشف می‌کند که در نظر دنیا به زنی تبدیل شده که قلبش را دنبال کرد، نه؛ به زنی که به شوهرش خیانت کرد، فرزندش را رها کرد و خانواده‌اش را رسوا کرد."),
                    StoryParagraph("She discovers that her beauty, which was once her greatest asset, has become a curse, because it draws the eyes of men and the whispers of women wherever she goes.", "او کشف می‌کند که زیبایی‌اش که زمانی بزرگ‌ترین سرمایه‌اش بود، به نفرینی تبدیل شده، چون نگاه مردان و پچ‌پچ زنان را هر جا می‌رود جلب می‌کند."),
                    StoryParagraph("She discovers that she is more alone than she has ever been in her life, more alone than she ever imagined possible, and the discovery nearly destroys her.", "او کشف می‌کند که تنهاتر از هر زمان دیگری در زندگی‌اش است، تنهاتر از آنچه هرگز تصور می‌کرد ممکن باشد و این کشف تقریباً نابودش می‌کند."),
                    StoryParagraph("She writes a letter to Karenin, begging him to let her see her son, just once, just for a few minutes, and she sends it with trembling hands and waits for the reply with unbearable anxiety.", "او نامه‌ای به کارنین می‌نویسد و التماس می‌کند اجازه دهد پسرش را ببیند، فقط یک بار، فقط برای چند دقیقه و آن را با دستانی لرزان می‌فرستد و با اضطراب تحمل‌ناپذیری منتظر جواب می‌ماند."),
                    StoryParagraph("Karenin does not reply, and the silence is more cruel than any refusal could have been, because it denies her even the mercy of a clear answer.", "کارنین جواب نمی‌دهد و سکوت از هر رد کردنی بی‌رحمانه‌تر است، چون حتی رحمت یک جواب روشن را از او دریغ می‌کند."),
                    StoryParagraph("Anna sinks into a deep depression, from which not even Vronsky's love can lift her, and she begins to rely on morphine to sleep, and then to function, and then simply to survive.", "آنا در افسردگی عمیقی فرو می‌رود که حتی عشق ورونسکی نمی‌تواند از آن بلندش کند و شروع می‌کند به تکیه بر مورفین برای خوابیدن و بعد برای کار کردن و بعد صرفاً برای زنده ماندن."),
                    StoryParagraph("She becomes jealous of Vronsky, irrationally, obsessively jealous, because she has lost everything else and cannot bear the thought of losing him too.", "او به ورونسکی حسادت می‌کند، به‌طور غیرعقلانی، به‌طور وسواس‌گونه، چون همه چیز دیگر را از دست داده و نمی‌تواند فکر از دست دادن او را هم تحمل کند."),
                    StoryParagraph("She accuses him of loving other women, of wishing he had never met her, of planning to leave her, and Vronsky, who has sacrificed his career and his reputation for her, begins to feel trapped.", "او متهمش می‌کند که زنان دیگر را دوست دارد، که آرزو می‌کند هرگز ندیده بودش، که نقشه ترکش را می‌کشد و ورونسکی که حرفه و آبرویش را برایش فدا کرده، شروع می‌کند به حس گرفتاری."),
                    StoryParagraph("They go to Italy, hoping a change of scene will help, and for a few months, they are happy in Venice and Rome, but the happiness does not last, because the problems they have brought with them cannot be left behind.", "آن‌ها به ایتالیا می‌روند، به امید آنکه تغییر منظره کمک کند و برای چند ماه، در ونیز و روم خوشحال هستند، اما خوشبختی دوام نمی‌آورد، چون مشکلاتی که با خود آورده‌اند را نمی‌شود پشت سر گذاشت."),
                    StoryParagraph("When they return to Russia, they find that nothing has changed, that society still rejects Anna, that Karenin still refuses to grant her a divorce, that she still cannot see her son.", "وقتی به روسیه برمی‌گردند، می‌بینند هیچ چیز عوض نشده، جامعه هنوز آنا را طرد می‌کند، کارنین هنوز از دادن طلاق امتناع می‌کند، او هنوز نمی‌تواند پسرش را ببیند."),
                    StoryParagraph("They settle on Vronsky's country estate, where they live in isolation, cut off from the world that has condemned them, and there, in the quiet of the countryside, Anna's descent into despair accelerates.", "آن‌ها در ملک روستایی ورونسکی ساکن می‌شوند، جایی که در انزوا زندگی می‌کنند، جدا از دنیایی که محکومشان کرده و آنجا، در سکوت حومه شهر، سقوط آنا به ناامیدی شتاب می‌گیرد."),
                    StoryParagraph("She reads endlessly, trying to fill the emptiness with words, but no book can give her back her son, no poem can restore her reputation, no novel can make her forgive herself for what she has done.", "او بی‌پایان می‌خواند و تلاش می‌کند خالی‌بودن را با کلمات پر کند، اما هیچ کتابی نمی‌تواند پسرش را برگرداندش، هیچ شعری نمی‌تواند آبرویش را بازگرداند، هیچ رمانی نمی‌تواند او را وادار کند خودش را برای کاری که کرده ببخشد."),
                    StoryParagraph("She begins to see Vronsky as the cause of all her suffering, rather than as the man she loves, and this change in perception is the beginning of the end.", "او شروع می‌کند به دیدن ورونسکی به‌عنوان علت همه رنجش، نه مردی که دوست دارد و این تغییر در ادراک آغاز پایان است."),
                    StoryParagraph("The love that had once seemed worth every sacrifice now seems to her like a chain, a burden, a sentence of lifelong suffering.", "عشقی که زمانی به نظر می‌رسید ارزش هر فداکاری را داشته باشد، حالا برایش مثل زنجیری به نظر می‌رسد، باری، حکمی به رنج ابدی."),
                    StoryParagraph("And so, slowly, tragically, the woman who had once been the most admired lady of Petersburg society becomes a shadow of herself, a ghost haunted by her own choices, a prisoner of her own heart.", "و اینگونه، آهسته، به‌طرز تراژیک، زنی که زمانی محبوب‌ترین بانوی جامعه پترزبورگ بود به سایه‌ای از خودش تبدیل می‌شود، شبحی که توسط انتخاب‌های خودش تسخیر شده، زندانی قلب خودش.")
                )
            ),
            StoryChapter(
                number = 4, title = "Escape to Italy", titlePersian = "فرار به ایتالیا",
                paragraphs = listOf(
                    StoryParagraph("The decision to leave Russia was made in haste, in the aftermath of a particularly ugly scene at the opera, where Anna had been publicly humiliated by a woman who had refused to sit beside her.", "تصمیم به ترک روسیه در عجله گرفته شد، پس از صحنه‌ای به‌ویژه زشت در اپرا، جایی که آنا توسط زنی که از نشستن کنارش امتناع کرده بود علناً تحقیر شد."),
                    StoryParagraph("Vronsky, seeing the pain in her eyes, had taken her hand and told her that they would go to Italy, to Venice, to Rome, to anywhere in the world where she could be happy.", "ورونسکی با دیدن درد در چشمانش دستش را گرفته بود و به او گفته بود که به ایتالیا می‌روند، به ونیز، به روم، به هر جای دنیا که بتواند خوشحال باشد."),
                    StoryParagraph("They traveled first to Venice, arriving on a warm autumn evening when the canals were golden in the setting sun and the whole city seemed to belong to another century.", "آن‌ها اول به ونیز سفر کردند و در عصری گرم از پاییز رسیدند، همان‌وقت که کانال‌ها در غروب آفتاب طلایی بودند و تمام شهر به نظر می‌رسید به قرنی دیگر تعلق دارد."),
                    StoryParagraph("For the first few weeks, Anna was happy, or as close to happy as she had been in months, and she allowed herself to believe that they had finally escaped their past.", "برای چند هفته اول، آنا خوشحال بود، یا هر چه نزدیک به خوشحالی که در ماه‌ها بوده، و به خودش اجازه داد باور کند که بالاخره از گذشته‌شان فرار کرده‌اند."),
                    StoryParagraph("They took a palazzo on the Grand Canal, with high ceilings and frescoed walls and windows that opened onto the water, and Anna spent her days reading, painting, and walking with Vronsky through the narrow streets.", "آن‌ها قصر کوچکی در کانال بزرگ گرفتند، با سقف‌های بلند و دیوارهای نقاشی‌شده و پنجره‌هایی که به آب باز می‌شدند و آنا روزهایش را با خواندن، نقاشی کردن و قدم زدن با ورونسکی در خیابان‌های باریک می‌گذراند."),
                    StoryParagraph("But the happiness did not last, because Anna's mind was not a place that could be at peace, and because the wounds she had suffered were not the kind that fresh surroundings could heal.", "اما خوشبختی دوام نیاورد، چون ذهن آنا جایی نبود که بتواند در آرامش باشد و چون زخم‌هایی که متحمل شده بود از نوعی نبودند که محیط تازه درمانشان کند."),
                    StoryParagraph("She began to think about Seryozha, and once the thought had entered her mind, it would not leave, and it grew more painful with every passing day.", "او شروع کرد به فکر کردن درباره سریوژا و وقتی این فکر وارد ذهنش شد، نمی‌رفت و با هر روزی که می‌گذشت دردناک‌تر می‌شد."),
                    StoryParagraph("She wrote letters to Karenin, begging him to let her see her son, and when he did not reply, she wrote again, and again, and again, until her letters became a stream of desperate pleas that Karenin did not even bother to open.", "او نامه‌هایی به کارنین نوشت و التماس کرد اجازه دهد پسرش را ببیند و وقتی جواب نداد، دوباره و دوباره و دوباره نوشت، تا وقتی نامه‌هایش به جوی از التماس‌های ناامیدانه تبدیل شدند که کارنین حتی زحمت باز کردنشان را هم به خود نمی‌داد."),
                    StoryParagraph("The silence was more cruel than any reply could have been, because it denied her even the mercy of knowing whether her son remembered her, whether he missed her, whether he hated her for leaving.", "سکوت از هر جوابی بی‌رحمانه‌تر بود، چون حتی رحمت دانستن اینکه آیا پسرش به یادش می‌آورد، آیا دلتنگش می‌شود، آیا برای رفتنش از او متنفر است را از او دریغ می‌کرد."),
                    StoryParagraph("She began to imagine that Seryozha had forgotten her, that he had grown to hate her, that Karenin had poisoned his mind against her, and these imaginings became more real to her than any reality.", "او شروع کرد به تصور کردن که سریوژا فراموشش کرده، که به نفرت از او بزرگ شده، که کارنین ذهنش را علیه او مسموم کرده و این تصورات برایش واقعی‌تر از هر واقعیتی شدند."),
                    StoryParagraph("Vronsky, meanwhile, threw himself into painting with a passion that Anna could not share, and she watched him with a mixture of love and resentment, because he could lose himself in his art while she could lose herself in nothing.", "ورونسکی در همین حال، با شوری که آنا نمی‌توانست شریک شود، خود را در نقاشی غرق کرد و او با آمیزه‌ای از عشق و کینه تماشایش می‌کرد، چون او می‌توانست خودش را در هنرش گم کند در حالی که آنا نمی‌توانست در هیچ چیزی گم شود."),
                    StoryParagraph("He made friends with a group of artists, and he began to spend more and more time with them, and Anna, though she never complained, resented every moment he spent away from her.", "او با گروهی از هنرمندان دوست شد و شروع کرد به گذراندن وقت بیشتر و بیشتری با آن‌ها و آنا، هرچند هرگز شکایت نمی‌کرد، از هر لحظه‌ای که دور از او می‌گذراند ناراحت بود."),
                    StoryParagraph("Her jealousy, which had been dormant during the first months of their life together, began to awaken, and once awakened, it grew with terrifying speed.", "حسادتش که در ماه‌های اول زندگی مشترکشان خفته بود، شروع کرد به بیدار شدن و وقتی بیدار شد، با سرعتی هولناک رشد کرد."),
                    StoryParagraph("She began to imagine that Vronsky was falling in love with other women, that he found her less beautiful than before, that he regretted the sacrifices he had made for her.", "او شروع کرد به تصور کردن که ورونسکی عاشق زنان دیگر می‌شود، که او را کمتر از قبل زیبا می‌یابد، که از فداکاری‌هایی که برایش کرده پشیمان است."),
                    StoryParagraph("These imaginings were not based on any evidence, but they did not need to be, because jealousy does not require evidence; it only requires fear.", "این تصورات بر هیچ مدرکی بنا نشده بودند، اما نیازی به مدرک نداشتند، چون حسادت به مدرک نیاز ندارد؛ فقط به ترس نیاز دارد."),
                    StoryParagraph("She began to check Vronsky's pockets, to read his letters, to question his friends, and when he discovered what she was doing, he was hurt and angry, and they had their first real quarrel.", "او شروع کرد به بررسی جیب‌های ورونسکی، خواندن نامه‌هایش، بازجویی از دوستانش و وقتی او کشف کرد چه می‌کند، زخمی و عصبانی شد و آن‌ها اولین دعوای واقعی‌شان را کردند."),
                    StoryParagraph("The quarrel ended in tears and apologies, as such quarrels often do, but it left behind a residue of distrust that neither of them could wash away.", "دعوا مثل چنین دعواهایی اغلب با اشک و عذرخواهی تمام شد، اما باقی‌مانده‌ای از بی‌اعتمادی جا گذاشت که هیچ‌کدام نمی‌توانستند پاکش کنند."),
                    StoryParagraph("They moved on to Rome, and then to Naples, and then to a small town in the Italian countryside, but the pattern repeated itself wherever they went: a few weeks of happiness, followed by weeks of suspicion and quarreling and despair.", "آن‌ها به روم و بعد ناپل و بعد شهر کوچکی در حومه ایتالیا رفتند، اما الگو هر جا می‌رفتند تکرار می‌شد: چند هفته خوشبختی، به دنبالش هفته‌هایی از سوءظن و دعوا و ناامیدی."),
                    StoryParagraph("Anna began to write poetry in secret, and the poems were all about death, about escape, about the peace that could only be found beyond the grave.", "آنا شروع کرد به نوشتن شعر مخفیانه و همه شعرها درباره مرگ بودند، درباره فرار، درباره آرامشی که فقط فراتر از قبر یافت می‌شود."),
                    StoryParagraph("She thought about killing herself, not once but many times, and each time, she found a reason to live: Vronsky's love, the hope of seeing Seryozha again, the memory of the woman she had once been.", "او به کشتن خودش فکر کرد، نه یک بار بلکه بارها و هر بار، دلیلی برای زندگی پیدا می‌کرد: عشق ورونسکی، امید دیدن دوباره سریوژا، خاطره زنی که زمانی بوده است."),
                    StoryParagraph("But as time went on, the reasons became fewer and weaker, and the despair became stronger and more insistent, until she could no longer remember a time when she had not felt this way.", "اما با گذشت زمان، دلایل کمتر و ضعیف‌تر شدند و ناامیدی قوی‌تر و پافشارتر شد، تا وقتی دیگر نمی‌توانست زمانی را به یاد آورد که اینطور حس نکرده باشد."),
                    StoryParagraph("One evening, watching the sun set over the sea, Anna turned to Vronsky and told him that she wanted to return to Russia.", "یک عصر، در حالی که تماشا می‌کرد خورشید بر دریا غروب می‌کند، آنا به ورونسکی رو کرد و به او گفت که می‌خواهد به روسیه برگردد."),
                    StoryParagraph("Vronsky was surprised, because he had believed they were running away from Russia forever, but he agreed without argument, because he could deny her nothing, and because he too had begun to feel that their life in Italy was a kind of exile.", "ورونسکی تعجب کرد، چون باور داشت برای همیشه از روسیه فرار می‌کنند، اما بدون بحث موافقت کرد، چون نمی‌توانست چیزی از او دریغ کند و چون خودش هم شروع کرده بود به حس اینکه زندگی‌شان در ایتالیا نوعی تبعید است."),
                    StoryParagraph("They returned to Petersburg in the spring, hoping that time had healed the wounds of the past, and they discovered, within days of their arrival, that nothing had healed, that nothing had changed, that the world still regarded them as pariahs.", "آن‌ها در بهار به پترزبورگ برگشتند، به امید آنکه زمان زخم‌های گذشته را التیام داده باشد و در عرض چند روز از ورودشان کشف کردند که هیچ چیز التیام نیافته، هیچ چیز عوض نشده، دنیا هنوز آن‌ها را مثل مطرودانی می‌بیند."),
                    StoryParagraph("Anna went to the theater one evening, hoping to see her old friends, and she was met with such open hostility that she had to leave before the first act was over.", "آنا یک عصر به تئاتر رفت، به امید دیدن دوستان قدیمی‌اش و با چنان خصومت آشکاری روبرو شد که مجبور شد قبل از تمام شدن پرده اول برود."),
                    StoryParagraph("The world, which had once welcomed her as one of its brightest ornaments, now rejected her as if she had committed a crime, and she realized, at last, that the crime she had committed was not adultery, but honesty.", "دنیایی که زمانی به‌عنوان یکی از درخشان‌ترین زینت‌هایش پذیرفته بودش، حالا طردش می‌کرد گویی جنایتی مرتکب شده و در نهایت فهمید که جنایتی که مرتکب شده زنا نبود، صداقت بود."),
                    StoryParagraph("She and Vronsky retreated to his country estate, and there, far from the eyes of the world, they tried to build a life together, but the seeds of destruction had been planted long before.", "او و ورونسکی به ملک روستایی‌اش عقب‌نشینی کردند و آنجا، دور از نگاه دنیا، تلاش کردند زندگی مشترکی بسازند، اما بذرهای نابودی خیلی قبل‌تر کاشته شده بودند."),
                    StoryParagraph("The isolation, which they had hoped would protect them, only made Anna's desperation worse, and the love, which had once seemed worth any sacrifice, now seemed to her like a burden too heavy to bear.", "انزوا، که امید داشتند از آن‌ها محافظت کند، فقط ناامیدی آنا را بدتر کرد و عشق، که زمانی به نظر می‌رسید ارزش هر فداکاری را داشته باشد، حالا برایش مثل باری تحمل‌ناپذیر سنگین به نظر می‌رسید."),
                    StoryParagraph("And so, slowly, relentlessly, the tragedy that had begun on a snowy railway platform in Moscow moved toward its inevitable and terrible conclusion.", "و اینگونه، آهسته، بی‌امان، تراژدی‌ای که در سکوی برفی ایستگاه راه‌آهن مسکو آغاز شده بود به سمت نتیجه اجتناب‌ناپذیر و هولناکش پیش می‌رفت.")
                )
            ),
            StoryChapter(
                number = 5, title = "The Tragic End", titlePersian = "پایان تراژیک",
                paragraphs = listOf(
                    StoryParagraph("The quarrel that would prove to be their last began, as most of their quarrels did, over a small and insignificant matter.", "دعوایی که ثابت شد آخرینشان است، مثل بیشتر دعواهایشان، بر سر موضوعی کوچک و بی‌اهمیت آغاز شد."),
                    StoryParagraph("Vronsky had received a letter from his mother, asking him to visit her on some family business, and Anna had immediately accused him of wanting to see another woman.", "ورونسکی نامه‌ای از مادرش دریافت کرده بود که از او می‌خواست برای کاری خانوادگی به دیدنش برود و آنا بلافاصله متهمش کرد که می‌خواهد زن دیگری را ببیند."),
                    StoryParagraph("She had no evidence, of course, but she did not need any; her jealousy had become a kind of madness, a fever that distorted everything she saw and heard.", "البته مدرکی نداشت، اما نیازی هم نداشت؛ حسادتش نوعی جنون شده بود، تبی که هر چیزی که می‌دید و می‌شنید را تحریف می‌کرد."),
                    StoryParagraph("Vronsky, exhausted by her constant suspicions, tried to explain, tried to reassure her, tried to reason with her, but she would not listen, because she did not want to listen.", "ورونسکی که از سوءظن‌های مداومش خسته شده بود، تلاش کرد توضیح دهد، تلاش کرد اطمینان دهد، تلاش کرد منطقی صحبت کند، اما او گوش نمی‌داد، چون نمی‌خواست گوش دهد."),
                    StoryParagraph("She screamed at him, accused him of every crime she could imagine, told him that she had sacrificed everything for him and that he had repaid her with nothing but coldness and betrayal.", "سرش فریاد زد، به هر جنایتی که می‌توانست تصور کند متهمش کرد، به او گفت که همه چیز را برایش فدا کرده و او در عوض چیزی جز سردی و خیانت به او نداده."),
                    StoryParagraph("Vronsky, for the first time in their relationship, lost his temper, and he told her, in a voice that was cold with anger, that he could not live like this anymore, that he needed air, that he needed space.", "ورونسکی برای اولین بار در رابطه‌شان عصبانی شد و با صدایی که از خشم سرد بود به او گفت که دیگر نمی‌تواند اینطور زندگی کند، به هوا نیاز دارد، به فضا نیاز دارد."),
                    StoryParagraph("Then he left the house and rode to the station, intending to take the train to his mother's estate, and he did not look back.", "بعد خانه را ترک کرد و به سمت ایستگاه راند، قصد داشت با قطار به ملک مادرش برود و به عقب نگاه نکرد."),
                    StoryParagraph("Anna watched him go, and something inside her snapped, like a thread stretched too thin for too long.", "آنا رفتنش را تماشا کرد و چیزی در درونش شکست، مثل نخی که خیلی طولانی کشیده شده و خیلی نازک شده بود."),
                    StoryParagraph("She ran to her room and began to write him a letter, a letter full of reproaches and pleas and confessions of love, a letter that she knew would never be enough, that nothing would ever be enough.", "او به اتاقش دوید و شروع کرد به نوشتن نامه‌ای برایش، نامه‌ای پر از سرزنش و التماس و اعتراف به عشق، نامه‌ای که می‌دانست هرگز کافی نخواهد بود، هیچ چیز هرگز کافی نخواهد بود."),
                    StoryParagraph("She sent the letter by telegram, and then she waited, and the waiting was more unbearable than anything she had ever endured.", "او نامه را با تلگراف فرستاد و بعد منتظر ماند و انتظار از هر چیزی که تا حالا تحمل کرده بود غیرقابل تحمل‌تر بود."),
                    StoryParagraph("When no reply came, she decided to follow him to the station, to see him one more time, to make him understand, to make him come back.", "وقتی جوابی نیامد، تصمیم گرفت دنبالش تا ایستگاه برود، یک بار آخر ببیندش، وادارش کند بفهمد، وادارش کند برگردد."),
                    StoryParagraph("She dressed hastily, without care, and she went out into the cold autumn evening, and the wind was bitter and the sky was grey and the streets were empty and she had never felt so alone.", "با عجله لباس پوشید، بدون دقت و در عصر سرد پاییزی بیرون رفت و باد تلخ بود و آسمان خاکستری و خیابان‌ها خالی و هرگز اینقدر تنها حس نکرده بود."),
                    StoryParagraph("At the station, she saw Vronsky's carriage waiting, and she saw Vronsky himself standing on the platform, reading a letter, and she saw the expression on his face, and in that expression she read her own doom.", "در ایستگاه، کالسکه ورونسکی را دید که منتظر بود و خود ورونسکی را دید که روی سکو ایستاده و نامه‌ای می‌خواند و حالت صورتش را دید و در آن حالت عذاب خودش را خواند."),
                    StoryParagraph("He was reading a letter from his mother, and his expression was one of relief, of freedom, of a man who had finally decided to end something that had become a burden.", "او نامه‌ای از مادرش می‌خواند و حالتش یکی از آسودگی بود، آزادی، مردی که بالاخره تصمیم گرفته چیزی را که باری شده بود تمام کند."),
                    StoryParagraph("Anna did not approach him; she did not speak to him; she simply stood at a distance and watched, and as she watched, the last spark of hope within her died.", "آنا به او نزدیک نشد؛ با او صحبت نکرد؛ فقط از فاصله‌ای ایستاد و تماشا کرد و همان‌طور که تماشا می‌کرد، آخرین شراره امید درونش مرد."),
                    StoryParagraph("She turned and walked along the platform, slowly, as though she had all the time in the world, and she came to the edge of the platform, where the rails gleamed dully in the light of the lamps.", "او برگشت و در طول سکو راه افتاد، آهسته، گویی تمام دنیا وقت دارد و به لبه سکو رسید، جایی که ریل‌ها در نور چراغ‌ها به‌طرز کدری می‌درخشیدند."),
                    StoryParagraph("She thought about her life, about her choices, about all the love she had given and all the suffering she had received in return.", "او به زندگی‌اش فکر کرد، به انتخاب‌هایش، به تمام عشقی که داده بود و تمام رنجی که در عوض دریافت کرده بود."),
                    StoryParagraph("She thought about Seryozha, and the thought was like a knife in her heart, because she knew that she would never see him again, that Karenin would never let her, that the world would never let her.", "به سریوژا فکر کرد و فکر مثل چاقویی در قلبش بود، چون می‌دانست که هرگز دوباره نمی‌بیندش، که کارنین هرگز اجازه نخواهد داد، که دنیا هرگز اجازه نخواهد داد."),
                    StoryParagraph("She thought about Vronsky, and the thought was even more painful, because she loved him still, in spite of everything, in spite of the pain, in spite of the quarrels, and she knew that love was not enough, that it had never been enough.", "به ورونسکی فکر کرد و فکر حتی دردناک‌تر بود، چون هنوز دوستش داشت، به رغم همه چیز، به رغم درد، به رغم دعواها و می‌دانست که عشق کافی نبود، هرگز کافی نبوده است."),
                    StoryParagraph("A train was approaching, and the sound of it grew louder and louder, and the ground trembled beneath her feet, and she felt, for the first time in months, a strange and terrible peace.", "قطاری نزدیک می‌شد و صدایش بلندتر و بلندتر شد و زمین زیر پاهایش می‌لرزید و برای اولین بار در ماه‌ها، آرامشی عجیب و هولناک حس کرد."),
                    StoryParagraph("She remembered the first time she had met Vronsky, at a railway station, and how the sight of a man crushed by a train had seemed to her like a bad omen, and she understood, at last, that the omen had been true.", "اولین باری که ورونسکی را دیده بود به یاد آورد، در ایستگاه راه‌آهن و اینکه دیدن مردی که توسط قطاری له شده بود چطور برایش مثل فال بدی به نظر رسیده و در نهایت فهمید که آن فال درست بوده است."),
                    StoryParagraph("She remembered the words of a woman she had met in Moscow, who had told her that she should not allow herself to feel too much, and she realized, with a bitter smile, that the woman had been right.", "کلمات زنی که در مسکو ملاقات کرده بود را به یاد آورد، که به او گفته بود نباید به خودش اجازه دهد زیاد احساس کند و با لبخندی تلخ فهمید که آن زن درست گفته بوده است."),
                    StoryParagraph("She removed her gloves and her hat, as though preparing for sleep, and she placed them carefully on the ground beside her, and then she stepped forward, toward the rails, toward the darkness, toward the peace that she had been seeking for so long.", "دستکش‌ها و کلاهش را درآورد، گویی برای خواب آماده می‌شود و آن‌ها را با دقت روی زمین کنارش گذاشت و بعد به جلو قدم گذاشت، به سمت ریل‌ها، به سمت تاریکی، به سمت آرامشی که اینقدر طولانی در جست‌وجویش بود."),
                    StoryParagraph("The train was very close now, and the driver was blowing the whistle, and the sound was so loud that it filled the entire world.", "قطار حالا خیلی نزدیک بود و راننده سوت می‌کشید و صدا آنقدر بلند بود که تمام دنیا را پر می‌کرد."),
                    StoryParagraph("She thought, in her last moments, about the light, about the hope, about all the things she had loved and lost, and then she thought no more.", "در لحظات آخرش به نور فکر کرد، به امید، به تمام چیزهایی که دوست داشته و از دست داده و بعد دیگر فکر نکرد."),
                    StoryParagraph("The train passed, and there was a terrible sound, and then there was silence.", "قطار گذشت و صدای هولناکی بود و بعد سکوت بود."),
                    StoryParagraph("When Vronsky, who had heard the commotion from the platform, ran to the tracks and saw what had happened, he collapsed to the ground and wept like a child.", "وقتی ورونسکی که از سکو صدای همهمه را شنیده بود به سمت ریل دوید و دید چه اتفاقی افتاده، روی زمین فرو ریخت و مثل بچه‌ای گریه کرد."),
                    StoryParagraph("He wept for Anna, whom he had loved and could not save; he wept for himself, who would carry the guilt of her death forever; he wept for the child they would never have, and for the life they would never live.", "او برای آنا گریه کرد، که دوستش داشت و نمی‌توانست نجاتش دهد؛ برای خودش گریه کرد، که تا ابد گناه مرگش را با خود حمل می‌کند؛ برای بچه‌ای که هرگز نخواهند داشت و زندگی‌ای که هرگز نخواهند زیست گریه کرد."),
                    StoryParagraph("Anna Karenina was dead, and with her died the last hope of the woman who had dared to love beyond the boundaries that society had set for her.", "آنا کارنینا مرده بود و با او آخرین امید زنی که جرأت کرده بود فراتر از مرزهایی که جامعه برایش گذاشته بود عشق بورزد مرد."),
                    StoryParagraph("She had paid for that love with her life, and the world, which had condemned her, did not weep for her, did not mourn her, did not even remember her for long.", "او برای آن عشق با زندگی‌اش پرداخته بود و دنیا، که محکومش کرده بود، برایش گریه نکرد، عزادارش نشد، حتی مدت طولانی به یادش نیاورد."),
                    StoryParagraph("But her story lived on, in the pages of a novel that would be read for generations, and in the hearts of every reader who understood what it meant to love too much and to lose everything.", "اما داستانش زنده ماند، در صفحات رمانی که برای نسل‌ها خوانده می‌شود و در قلب هر خواننده‌ای که می‌فهمد عشق ورزیدن بیش از حد و از دست دادن همه چیز یعنی چه."),
                    StoryParagraph("Vronsky, devastated by her death, joined the army and volunteered for the most dangerous missions, seeking death in battle but never finding it, and he lived, in the end, to a lonely old age.", "ورونسکی که از مرگش نابود شده بود، به ارتش پیوست و برای خطرناک‌ترین مأموریت‌ها داوطلب شد، در نبرد به دنبال مرگ می‌گشت اما هرگز پیدایش نمی‌کرد و در نهایت، تا پیری تنها زندگی کرد."),
                    StoryParagraph("He never married, never loved again, never forgave himself for what had happened, and every year, on the anniversary of her death, he would go to the railway station and stand on the platform and remember.", "هرگز ازدواج نکرد، هرگز دوباره عاشق نشد، هرگز خودش را برای آنچه اتفاق افتاده بود نبخشید و هر سال، در سالگرد مرگش، به ایستگاه راه‌آهن می‌رفت و روی سکو می‌ایستاد و به یاد می‌آورد."),
                    StoryParagraph("And so the story of Anna Karenina ends, as it must end, in tragedy and in tears, but also in beauty, because the story of a woman who loved too much is also the story of a woman who lived too much, who felt too much, who was more alive than those who never risked anything.", "و اینگونه داستان آنا کارنینا پایان می‌یابد، همان‌طور که باید پایان یابد، در تراژدی و در اشک، اما در زیبایی هم، چون داستان زنی که بیش از حد عشق ورزید داستان زنی است که بیش از حد زندگی کرد، بیش از حد حس کرد، زنده‌تر از کسانی بود که هرگز چیزی را به خطر نینداختند."),
                    StoryParagraph("She was not a saint, and she was not a villain; she was simply a woman, a human being, with all the weakness and all the beauty that being human entails, and she deserved better than the world gave her.", "او نه قدیس بود و نه شریر؛ فقط یک زن بود، یک انسان، با تمام ضعف و تمام زیبایی‌ای که انسان بودن در بر دارد و سزاوار بهتر از آنچه دنیا به او داد بود."),
                    StoryParagraph("Tolstoy wrote this novel not to condemn her, but to understand her, and in understanding her, to understand all of us, with our impossible desires and our inevitable suffering and our unending search for love.", "تولستوی این رمان را نه برای محکوم کردنش نوشت، بلکه برای فهمیدنش و در فهمیدنش، برای فهمیدن همه ما، با امیال غیرممکنمان و رنج اجتناب‌ناپذیرمان و جست‌وجوی بی‌پایانمان برای عشق."),
                    StoryParagraph("And that is why Anna Karenina is one of the greatest novels ever written, and why, more than a century after its publication, we still read it, and still weep for her.", "و به همین دلیل است که آنا کارنینا یکی از بزرگ‌ترین رمان‌هایی است که تاکنون نوشته شده و چرا، بیش از یک قرن پس از انتشارش، هنوز می‌خوانیمش و هنوز برایش گریه می‌کنیم.")
                )
            )
        )
    )

    // ─────────────── ۳: مسخ ───────────────
    private fun story3() = StoryContent(
        storyId = "adv_metamorphosis",
        chapters = listOf(
            StoryChapter(
                number = 1, title = "The Awakening", titlePersian = "بیداری",
                paragraphs = listOf(
                    StoryParagraph("One morning, when Gregor Samsa woke from troubled dreams, he found himself transformed in his bed into a monstrous vermin.", "یک صبح، وقتی گرگور سامسا از رؤیاهای آشفته بیدار شد، خود را در تختش به حشره‌ای هیولایی تبدیل شده یافت."),
                    StoryParagraph("He was lying on his hard, as it were armor-plated, back, and when he lifted his head a little, he could see his dome-like brown belly divided into stiff arched segments.", "او روی پشت سخت و زره‌مانندش دراز کشیده بود و وقتی کمی سرش را بلند کرد، می‌توانست شکم قهوه‌ای گنبدمانندش را ببیند که به بخش‌های قوسی سخت تقسیم شده بود."),
                    StoryParagraph("His numerous legs, which were pitifully thin compared to the rest of his bulk, waved helplessly before his eyes.", "پاهای متعددش، که در مقایسه با بقیه جثه‌اش به‌طرز رقت‌انگیزی نازک بودند، درمانده جلوی چشمانش موج می‌زدند."),
                    StoryParagraph("'What has happened to me?' he thought. It was no dream.", "فکر کرد: «چه بر سرم آمده؟» خواب نبود."),
                    StoryParagraph("His room, a proper human room although a little too small, lay peacefully between its four familiar walls.", "اتاقش، اتاقی انسانی و مناسب هرچند کمی کوچک، آرام بین چهار دیوار آشنايش دراز کشیده بود."),
                    StoryParagraph("A collection of textile samples lay spread out on the table — Samsa was a traveling salesman — and above it there hung a picture that he had recently cut out of an illustrated magazine.", "مجموعه‌ای از نمونه‌های پارچه روی میز پهن شده بود — سامسا فروشنده دوره‌گرد بود — و بالای آن تصویری آویزان بود که اخیراً از مجله‌ای مصور بریده بود."),
                    StoryParagraph("Gregor then turned to look out the window at the dull weather, and the sight of the rain falling in torrents made him feel melancholy.", "گرگور سپس به سمت پنجره چرخید تا هوای دلگیر بیرون را نگاه کند و دیدن بارانی که سیل‌آسا می‌بارید او را غمگین کرد."),
                    StoryParagraph("'How about going back to sleep for a few hours and forgetting about this nonsense?' he thought, but he could not carry it out, because he was accustomed to sleeping on his right side, and in his present state he could not get into that position.", "فکر کرد: «چطور است چند ساعت دیگر بخوابم و این مزخرف را فراموش کنم؟» اما نمی‌توانست انجامش دهد، چون به خوابیدن روی پهلوی راست عادت داشت و در وضعیت فعلی نمی‌توانست به آن حالت برسد."),
                    StoryParagraph("No matter how hard he threw himself onto his right side, he always rolled onto his back again.", "هر چقدر سخت تلاش می‌کرد خودش را روی پهلوی راست بیندازد، همیشه دوباره روی پشتش می‌غلتید."),
                    StoryParagraph("He must have tried it a hundred times, shutting his eyes so as not to see his wriggling legs, and only gave up when he began to feel a slight, dull pain in his side, which he had never felt before.", "باید صد بار امتحان کرده باشد، چشمانش را می‌بست تا پاهای لول‌خورنده‌اش را نبیند و فقط وقتی دست کشید که شروع کرد به حس دردی خفیف و کدر در پهلویش، دردی که هرگز قبلاً حس نکرده بود."),
                    StoryParagraph("'Oh, God,' he thought, 'what a demanding job I've chosen! Day in, day out on the road.'", "فکر کرد: «آه، خدای من، چه شغل طاقت‌فرسایی انتخاب کرده‌ام! روز از پی روز در راه.»"),
                    StoryParagraph("The stresses of the job were far greater than those of the actual work in the office, and on top of that there was the misery of traveling, the worries about train connections, the bad and irregular meals, the constant stream of casual acquaintances who never became friends.", "فشارهای شغل خیلی بیشتر از خود کار در دفتر بود و روی آن بدبختی سفر هم بود، نگرانی‌ها درباره اتصالات قطار، غذاهای بد و نامنظم، جریان مداوم آشنایان اتفاقی که هرگز دوست نمی‌شدند."),
                    StoryParagraph("'To hell with it all!' he thought, and he tried to move his legs once more, but they were completely out of control.", "فکر کرد: «به جهنم همه‌اش!» و یک بار دیگر تلاش کرد پاهایش را حرکت دهد، اما کاملاً از کنترل خارج بودند."),
                    StoryParagraph("He looked over at the alarm clock, which was ticking on the chest of drawers, and it was already half past six, and the next train left at seven.", "به ساعت زنگ‌دار نگاه کرد که روی دراور تیک‌تاک می‌کرد و از قبل شش و نیم بود و قطار بعدی ساعت هفت حرکت می‌کرد."),
                    StoryParagraph("'I could still catch it,' he thought, 'if I hurried.' But then he remembered that he could not possibly catch a train in his present condition.", "فکر کرد: «اگر عجله کنم هنوز می‌توانم به آن برسم.» اما بعد به یاد آورد که به هیچ وجه نمی‌تواند در وضعیت فعلی‌اش به قطاری برسد."),
                    StoryParagraph("His first thought, when he found himself in this impossible situation, was not to wonder what had happened to him, but to think about how he could continue to support his family.", "اولین فکرش وقتی خودش را در این وضعیت غیرممکن یافت، نه این بود که بپرسد چه بر سرش آمده، بلکه فکر کردن به اینکه چطور می‌تواند به حمایت از خانواده‌اش ادامه دهد."),
                    StoryParagraph("His father had lost his business five years earlier, and since then, Gregor had been the sole provider for the family.", "پدرش پنج سال پیش تجارتش را از دست داده بود و از آن زمان، گرگور تنها نان‌آور خانواده بود."),
                    StoryParagraph("His mother was sick with asthma, his sister Grete was only seventeen and needed to be sent to a conservatory to study the violin, and the family had debts that had to be paid.", "مادرش از آسم رنج می‌برد، خواهرش گرته فقط هفده ساله بود و باید به کنسرواتوار فرستاده می‌شد تا ویولن بیاموزد و خانواده بدهی‌هایی داشت که باید پرداخت می‌شد."),
                    StoryParagraph("'If I lose my job,' he thought, 'my family will be ruined.' And this thought, even more than the horror of his transformation, filled him with despair.", "فکر کرد: «اگر شغلم را از دست بدهم، خانواده‌ام نابود می‌شود.» و این فکر، حتی بیشتر از وحشت دگردیسی‌اش، او را پر از ناامیدی کرد."),
                    StoryParagraph("He tried to get out of bed, and after much difficulty, he managed to rock himself back and forth until he finally rolled off the bed onto the floor, landing with a dull thud.", "تلاش کرد از تخت بیرون بیاید و بعد از دشواری زیاد، موفق شد خودش را جلو و عقب تکان دهد تا بالاخره از تخت روی زمین افتاد و با صدایی کدر فرود آمد."),
                    StoryParagraph("The fall had not hurt him much, because his body was now strangely hard and armored, but the noise it made was loud enough to be heard in the next room.", "افتادن زیاد آزارش نداد، چون بدنش حالا به‌طرز عجیبی سخت و زره‌پوش بود، اما صدایی که ایجاد کرد آنقدر بلند بود که در اتاق بعدی شنیده شود."),
                    StoryParagraph("'Something must have fallen in Gregor's room,' said his mother from the next room, and Gregor heard his father and sister come to investigate.", "مادرش از اتاق بعدی گفت: «حتماً چیزی در اتاق گرگور افتاده،» و گرگور شنید که پدر و خواهرش برای بررسی می‌آیند."),
                    StoryParagraph("The door to his room was locked from the inside, as it always was at night, and there was no way for anyone to enter without his consent.", "در اتاقش از داخل قفل بود، همان‌طور که همیشه شب‌ها بود و راهی برای کسی نبود که بدون رضایتش وارد شود."),
                    StoryParagraph("'Gregor, are you all right?' his mother called through the door, and her voice was full of anxiety.", "مادرش از پشت در صدا زد: «گرگور، حالت خوب است؟» و صدایش پر از اضطراب بود."),
                    StoryParagraph("Gregor tried to answer, but the sound that came from his throat was not a human voice; it was a strange, animal-like squeaking that he could not control.", "گرگور تلاش کرد جواب دهد، اما صدایی که از گلویش آمد صدای انسانی نبود؛ جیرجیر عجیب و حیوان‌مانندی بود که نمی‌توانست کنترلش کند."),
                    StoryParagraph("'Gregor?' his sister called, 'are you ill? Do you need anything?'", "خواهرش صدا زد: «گرگور؟ مریضی؟ چیزی نیاز داری؟»"),
                    StoryParagraph("He managed to say 'Yes' in a voice that was almost human, and he heard his family sigh with relief on the other side of the door.", "او موفق شد «بله» بگوید با صدایی که تقریباً انسانی بود و شنید که خانواده‌اش از آن طرف در از آسودگی آه کشیدند."),
                    StoryParagraph("'He is awake,' they said to each other. 'Now we can tell him about the visitor from the firm.'", "به هم گفتند: «بیدار است. حالا می‌توانیم درباره بازدیدکننده از شرکت به او بگوییم.»"),
                    StoryParagraph("A short time later, there was a knock at the front door, and the family fell silent.", "کمی بعد، ضربه‌ای به در ورودی خورد و خانواده ساکت شدند."),
                    StoryParagraph("It was the chief clerk from the firm, come to find out why Gregor had not shown up for work.", "کارمند ارشد شرکت بود، آمده بود بفهمد چرا گرگور سر کار نیامده است."),
                    StoryParagraph("'Mr. Samsa,' the clerk called through the door, 'the manager has sent me to inquire why you are not at work.'", "کارمند از پشت در صدا زد: «آقای سامسا، مدیر مرا فرستاده تا بپرسم چرا سر کار نیستید.»"),
                    StoryParagraph("Gregor, still on the floor of his room, listened to the clerk's voice and felt a wave of terror wash over him.", "گرگور که هنوز روی کف اتاقش بود، به صدای کارمند گوش داد و موجی از وحشت او را فرا گرفت."),
                    StoryParagraph("He knew that his family depended on his job, that his job depended on his showing up for work, that his showing up for work was now impossible.", "می‌دانست که خانواده‌اش به شغلش وابسته است، شغلش به حاضر شدنش در محل کار وابسته است و حاضر شدنش در محل کار حالا غیرممکن بود."),
                    StoryParagraph("'Just a moment,' he called out, in a voice that was almost his own, 'I will be ready in a moment.'", "صدا زد: «یک لحظه،» با صدایی که تقریباً صدای خودش بود، «یک لحظه دیگر آماده می‌شوم.»"),
                    StoryParagraph("He began to struggle desperately to get himself upright, to open the door, to show them all that everything was fine, but his body would not obey him.", "او شروع کرد به تقلای ناامیدانه برای ایستادن، باز کردن در، نشان دادن به همه که همه چیز خوب است، اما بدنش اطاعتش نمی‌کرد."),
                    StoryParagraph("'Open the door, Mr. Samsa,' the clerk called again, 'or I shall have to report you to the manager.'", "کارمند دوباره صدا زد: «در را باز کن، آقای سامسا، یا مجبور می‌شوم به مدیر گزارش دهم.»"),
                    StoryParagraph("The family, in the next room, began to plead with Gregor to open the door, and their voices, full of fear and shame, only made his desperation worse.", "خانواده در اتاق بعدی شروع کردند به التماس کردن از گرگور که در را باز کند و صدایشان، پر از ترس و شرم، فقط ناامیدی‌اش را بدتر کرد."),
                    StoryParagraph("Finally, with a supreme effort, he managed to grip the key in his mandibles and turn it in the lock, and the door slowly swung open.", "بالاخره، با تلاشی فوق‌العاده، موفق شد کلید را در آرواره‌هایش بگیرد و در قفل بچرخاند و در آهسته باز شد."),
                    StoryParagraph("The clerk, standing in the doorway, took one look at the creature on the floor and let out a shriek of horror.", "کارمند که در چارچوب در ایستاده بود، یک نگاه به موجود روی زمین انداخت و فریاد وحشتی کشید."),
                    StoryParagraph("Gregor's mother fainted, his sister burst into tears, his father grabbed a walking stick and began to wave it threateningly.", "مادر گرگور غش کرد، خواهرش به گریه افتاد، پدرش عصایی چنگ کرد و شروع کرد به تهدیدآمیز تکان دادنش."),
                    StoryParagraph("'Gregor!' his sister cried. 'What has happened to you? Why have you done this?'", "خواهرش گریه کرد: «گرگور! چه بر سرت آمده؟ چرا این کار را کردی؟»"),
                    StoryParagraph("Gregor tried to speak, tried to explain, tried to reassure them, but the sounds that came from his throat only made them more terrified.", "گرگور تلاش کرد صحبت کند، تلاش کرد توضیح دهد، تلاش کرد به آن‌ها اطمینان دهد، اما صداهایی که از گلویش می‌آمد فقط بیشتر وحشتزده‌شان می‌کرد."),
                    StoryParagraph("He retreated back into his room, and the door was slammed shut and locked from the outside.", "او به اتاقش عقب‌نشینی کرد و در محکم بسته شد و از بیرون قفل شد."),
                    StoryParagraph("And so, in a single morning, without any warning, without any explanation, without any possibility of return, Gregor Samsa's life as a human being came to an end.", "و اینگونه، در یک صبح، بدون هیچ هشداری، بدون هیچ توضیحی، بدون هیچ امکان بازگشتی، زندگی گرگور سامسا به‌عنوان یک انسان به پایان رسید."),
                    StoryParagraph("He was now an insect, a vermin, a monstrous creature that his own family could not bear to look at.", "او حالا حشره‌ای بود، آفتی، موجودی هیولایی که خانواده خودش نمی‌توانست تحمل کند نگاهش کند."),
                    StoryParagraph("And yet, in his mind, he was still Gregor, still the son, still the brother, still the man who loved his family and wanted only to help them.", "و با این حال، در ذهنش، هنوز گرگور بود، هنوز پسر، هنوز برادر، هنوز مردی که خانواده‌اش را دوست داشت و تنها می‌خواست کمکشان کند."),
                    StoryParagraph("But the world did not see his mind; the world saw only the monstrous shell that now contained him, and the world, as it always does, judged him by what it saw.", "اما دنیا ذهنش را نمی‌دید؛ دنیا فقط پوسته هیولایی که حالا دربرش گرفته بود را می‌دید و دنیا، همانطور که همیشه می‌کند، او را با آنچه می‌دید قضاوت می‌کرد."),
                    StoryParagraph("And so began the slow, painful, tragic process of Gregor Samsa's isolation from the human race, an isolation that would end only with his death.", "و اینگونه روند آهسته، دردناک و تراژیک جدایی گرگور سامسا از نسل بشر آغاز شد، جدایی‌ای که فقط با مرگش پایان می‌یافت.")
                )
            ),
            StoryChapter(
                number = 2, title = "The Family's Shock", titlePersian = "شوک خانواده",
                paragraphs = listOf(
                    StoryParagraph("For the first few days after his transformation, Gregor's room was kept locked from the outside, and he was left alone with his thoughts and his hunger.", "برای چند روز اول پس از دگردیسی‌اش، اتاق گرگور از بیرون قفل نگه داشته می‌شد و او با افکار و گرسنگی‌اش تنها رها شده بود."),
                    StoryParagraph("His family, terrified and confused, did not know what to do with him, and so they did nothing, hoping that perhaps everything would somehow return to normal.", "خانواده‌اش که وحشت‌زده و گیج بودند نمی‌دانستند با او چه کنند و بنابراین هیچ کاری نمی‌کردند، به امید آنکه شاید همه چیز به نحوی به حالت عادی برگردد."),
                    StoryParagraph("But nothing returned to normal, and Gregor slowly grew hungrier and weaker, until finally his sister Grete decided to bring him some food.", "اما هیچ چیز به حالت عادی برنگشت و گرگور آهسته گرسنه‌تر و ضعیف‌تر شد، تا وقتی بالاخره خواهرش گرته تصمیم گرفت کمی غذا برایش ببرد."),
                    StoryParagraph("She chose a bowl of milk and some bread, because these were the foods he had always loved, and she placed them on the floor just inside his door, as though he were an animal.", "او کاسه‌ای شیر و کمی نان انتخاب کرد، چون این‌ها غذاهایی بودند که همیشه دوست داشت و آن‌ها را روی زمین درست داخل درش گذاشت، گویی حیوانی است."),
                    StoryParagraph("Gregor, however, no longer had any taste for milk, and though he was desperately hungry, he could not bring himself to drink it.", "اما گرگور دیگر هیچ طعمی برای شیر نداشت و هرچند ناامیدانه گرسنه بود، نمی‌توانست خودش را وادار به نوشیدنش کند."),
                    StoryParagraph("When Grete returned to check on the food, she found the milk untouched, and she was both hurt and puzzled.", "وقتی گرته برگشت تا غذا را بررسی کند، شیر را دست‌نخورده یافت و هم زخمی شد و هم متعجب."),
                    StoryParagraph("She decided to try something different, and she brought him an assortment of foods: old cheese, vegetables, and some leftovers that she had thrown out earlier.", "تصمیم گرفت چیز دیگری امتحان کند و برایش مجموعه‌ای از غذاها آورد: پنیر کهنه، سبزیجات و کمی باقی‌مانده که قبلاً دور انداخته بود."),
                    StoryParagraph("This time, Gregor ate eagerly, and his sister, watching through a crack in the door, saw that he preferred old and rotting food to fresh, and this discovery made her both relieved and disgusted.", "این بار، گرگور با اشتیاق خورد و خواهرش که از شکافی در در نگاه می‌کرد، دید که غذای کهنه و پوسیده را به تازه ترجیح می‌دهد و این کشف هم آسوده‌اش کرد و هم منزجرش کرد."),
                    StoryParagraph("From that day forward, Grete became his caretaker, and each day she brought him food, cleaned his room, and tried, in her own way, to make his existence bearable.", "از آن روز به بعد، گرته مراقبش شد و هر روز برایش غذا می‌آورد، اتاقش را تمیز می‌کرد و به شیوه خودش تلاش می‌کرد وجودش را تحمل‌پذیر کند."),
                    StoryParagraph("She was the only one who could enter his room, the only one who could bear to look at him, the only one who still seemed to think of him as her brother.", "او تنها کسی بود که می‌توانست وارد اتاقش شود، تنها کسی که می‌توانست تحمل کند نگاهش کند، تنها کسی که هنوز به نظر می‌رسید او را به‌عنوان برادرش می‌بیند."),
                    StoryParagraph("His parents could not bear to see him, and they avoided his room entirely, speaking of him in whispers, as though he had already died.", "والدینش نمی‌توانستند تحمل کنند ببینندش و کاملاً از اتاقش دوری می‌کردند و با زمزمه درباره‌اش صحبت می‌کردند، گویی از قبل مرده است."),
                    StoryParagraph("They had lost not only a son, but also the only source of income for the family, and the economic consequences of Gregor's transformation were immediate and severe.", "آن‌ها نه تنها پسری را از دست داده بودند، بلکه تنها منبع درآمد خانواده را هم از دست داده بودند و پیامدهای اقتصادی دگردیسی گرگور فوری و شدید بودند."),
                    StoryParagraph("The family had savings, but they were not enough to live on for long, and the father, who had been retired for years, was too old and weak to find work.", "خانواده پس‌انداز داشتند، اما برای زندگی طولانی کافی نبود و پدر که سال‌ها بازنشسته بود، برای یافتن کار خیلی پیر و ضعیف بود."),
                    StoryParagraph("The mother, though sick, began to take in sewing, and the sister, who had hoped to study music, took a job as a salesgirl in a shop.", "مادر، هرچند مریض، شروع کرد به خیاطی و خواهر، که امید داشت موسیقی بخواند، شغلی به‌عنوان فروشنده در مغازه‌ای گرفت."),
                    StoryParagraph("They also decided to take in lodgers, renting out one of the rooms to three gentlemen who paid them a monthly sum for their board.", "آن‌ها همچنین تصمیم گرفتند مستأجر بپذیرند و یکی از اتاق‌ها را به سه آقا اجاره دهند که ماهانه مبلغی برای اقامتشان می‌پرداختند."),
                    StoryParagraph("Gregor, listening through the wall, heard these strangers in his family's house, and he felt, for the first time, that he was no longer part of the family, but an outsider, an intruder, a burden.", "گرگور که از پشت دیوار گوش می‌داد، این غریبه‌ها را در خانه خانواده‌اش شنید و برای اولین بار حس کرد که دیگر بخشی از خانواده نیست، بلکه بیرونی است، مزاحمی است، باری است."),
                    StoryParagraph("The lodgers, unaware of his existence, ate their meals in the living room and discussed the affairs of the world with the confidence of men who believed they understood everything.", "مستأجرها که از وجود او بی‌خبر بودند، غذایشان را در نشیمن می‌خوردند و درباره امور دنیا با اعتماد مردانی بحث می‌کردند که باور داشتند همه چیز را می‌فهمند."),
                    StoryParagraph("Gregor listened to their conversations, and he began to realize how much he had lost, not just his body, but his place in the world, his voice in the conversation, his right to be heard.", "گرگور به گفت‌وگوهایشان گوش می‌داد و شروع کرد به درک اینکه چقدر از دست داده، نه فقط بدنش، بلکه جایگاهش در دنیا، صدایش در گفت‌وگو، حقش برای شنیده شدن."),
                    StoryParagraph("His sister, meanwhile, tried to make his room more comfortable, moving furniture aside to give him more space to crawl, and taking away the picture he had once loved.", "خواهرش در همین حال تلاش می‌کرد اتاقش را راحت‌تر کند، مبلمان را کنار می‌کشید تا فضای بیشتری برای خزیدنش بدهد و تصویری که زمانی دوست داشت را می‌برد."),
                    StoryParagraph("Gregor was devastated by the removal of the picture, because it was the last reminder of his human life, the last connection to the person he had been.", "گرگور از بردن تصویر نابود شد، چون آخرین یادآور زندگی انسانی‌اش بود، آخرین ارتباط با شخصی که بوده است."),
                    StoryParagraph("He clung to the picture and refused to let his sister take it, and this was the first time he had actively resisted anything since his transformation.", "او به تصویر چنگ زد و از دادنش به خواهرش امتناع کرد و این اولین باری بود که از زمان دگردیسی‌اش فعالانه در برابر چیزی مقاومت می‌کرد."),
                    StoryParagraph("Grete, frightened by his sudden intensity, left the picture where it was and retreated from the room, and Gregor was left alone with his small victory.", "گرته که از شدتش ترسیده بود، تصویر را همان‌جا گذاشت و از اتاق عقب‌نشینی کرد و گرگور با پیروزی کوچکش تنها ماند."),
                    StoryParagraph("But the victory was hollow, because he knew that the picture was only a symbol, and that the reality it symbolized was gone forever.", "اما پیروزی توخالی بود، چون می‌دانست تصویر فقط نمادی بود و واقعیتی که نمادش می‌کرد برای همیشه رفته بود."),
                    StoryParagraph("Days passed, and then weeks, and Gregor's existence settled into a routine of hunger, loneliness, and slow physical decline.", "روزها گذشتند و سپس هفته‌ها و وجود گرگور به روالی از گرسنگی، تنهایی و زوال جسمی آهسته تبدیل شد."),
                    StoryParagraph("He spent most of his time hiding under the sofa, because the darkness comforted him, and because his family could not bear to see him.", "او بیشتر وقتش را زیر مبل پنهان می‌کرد، چون تاریکی آرامش می‌دادش و چون خانواده‌اش نمی‌توانستند تحمل کنند ببینندش."),
                    StoryParagraph("He would crawl out at night, when everyone was asleep, and he would wander around his room, feeling the walls with his antennae, remembering what it had been like to walk upright, to open doors, to speak.", "شب‌ها بیرون می‌خزید، وقتی همه خواب بودند و در اتاقش پرسه می‌زد، دیوارها را با شاخک‌هایش حس می‌کرد و به یاد می‌آورد ایستاده راه رفتن، باز کردن درها، صحبت کردن چه حسی داشت."),
                    StoryParagraph("He thought about his family, about the sacrifices they were making for him, about the burden he had become, and he wished, more than anything, that he could speak to them, that he could explain, that he could apologize.", "به خانواده‌اش فکر می‌کرد، به فداکاری‌هایی که برایش می‌کردند، به باری که شده بود و بیشتر از هر چیزی آرزو می‌کرد می‌توانست با آن‌ها صحبت کند، توضیح دهد، عذرخواهی کند."),
                    StoryParagraph("But his voice was gone, and with it, his ability to communicate, to connect, to be understood, and the isolation that followed was more painful than any physical suffering.", "اما صدایش رفته بود و با آن، توانایی‌اش برای ارتباط برقرار کردن، وصل شدن، فهمیده شدن و انزوایی که در پی آمد از هر رنج جسمی دردناک‌تر بود."),
                    StoryParagraph("One day, his sister noticed that he had not eaten for several days, and she brought him some fresh food, hoping to tempt his appetite.", "یک روز، خواهرش متوجه شد چند روز است نخورده و کمی غذای تازه برایش آورد، به امید آنکه اشتهایش را تحریک کند."),
                    StoryParagraph("But Gregor could not eat, not because he was not hungry, but because the food reminded him of everything he had lost, and eating it felt like a betrayal of his former self.", "اما گرگور نمی‌توانست بخورد، نه چون گرسنه نبود، بلکه چون غذا او را به یاد هر چیزی که از دست داده بود می‌انداخت و خوردنش مثل خیانت به خود سابقش بود."),
                    StoryParagraph("He pushed the food away with his leg, and his sister, misunderstanding this gesture, thought he was rejecting her kindness, and she began to cry.", "او غذا را با پایش کنار زد و خواهرش که این حرکت را اشتباه فهمید، فکر کرد لطفش را رد می‌کند و شروع کرد به گریه کردن."),
                    StoryParagraph("Gregor wanted to comfort her, wanted to tell her that he was grateful, that he loved her, that she was the only one who still cared, but he could not, and the frustration was unbearable.", "گرگور می‌خواست دلداری‌اش دهد، می‌خواست به او بگوید سپاسگزار است، دوستش دارد، او تنها کسی است که هنوز اهمیت می‌دهد، اما نمی‌توانست و ناکامی تحمل‌ناپذیر بود."),
                    StoryParagraph("He retreated under the sofa and stayed there for hours, listening to his sister's sobs, feeling more alone than he had ever felt in his life.", "او زیر مبل عقب‌نشینی کرد و ساعت‌ها آنجا ماند و به هق‌هق‌های خواهرش گوش داد و تنهاتر از هر زمان دیگری در زندگی‌اش حس کرد."),
                    StoryParagraph("The gap between him and his family grew wider with every passing day, and the love that had once bound them together began to erode, replaced by disgust, fear, and resentment.", "فاصله میان او و خانواده‌اش با هر روزی که می‌گذشت پهن‌تر می‌شد و عشقی که زمانی آن‌ها را به هم بسته بود شروع به فرسایش کرد و جایگزینش انزجار، ترس و کینه شد."),
                    StoryParagraph("Gregor understood this, and he did not blame them, because he knew that he had become something that could not be loved, something that could only be tolerated.", "گرگور این را می‌فهمید و سرزنششان نمی‌کرد، چون می‌دانست به چیزی تبدیل شده که نمی‌توانست دوست داشته شود، چیزی که فقط می‌توانست تحمل شود."),
                    StoryParagraph("But understanding did not make the pain any less, and each night, as he lay in the darkness beneath the sofa, he wept, though no tears came from his insect eyes.", "اما فهمیدن درد را کمتر نمی‌کرد و هر شب، همان‌طور که در تاریکی زیر مبل دراز می‌کشید، گریه می‌کرد، هرچند اشکی از چشمان حشره‌ای‌اش نمی‌آمد."),
                    StoryParagraph("He wept for the life he had lost, for the family he could no longer help, for the man he had once been, and for the creature he had become.", "او برای زندگی‌ای که از دست داده بود گریه می‌کرد، برای خانواده‌ای که دیگر نمی‌توانست کمکشان کند، برای مردی که زمانی بوده و برای موجودی که شده بود."),
                    StoryParagraph("And he wept, most of all, for the simple, irreplaceable fact of being human, a fact that he had never appreciated until it was taken from him forever.", "و بیشتر از همه، برای واقعیت ساده و جبران‌ناپذیر انسان بودن گریه می‌کرد، واقعیتی که هرگز قدرش را ندانسته بود تا وقتی برای همیشه از او گرفته شد.")
                )
            ),
            StoryChapter(
                number = 3, title = "The Family's Decline", titlePersian = "افول خانواده",
                paragraphs = listOf(
                    StoryParagraph("Months passed, and the family's situation grew more desperate with each passing week.", "ماه‌ها گذشت و وضعیت خانواده با هر هفته‌ای که می‌گذشت ناامیدکننده‌تر شد."),
                    StoryParagraph("The savings were almost gone, the father's health was failing, the mother's asthma was getting worse, and the sister, who had once dreamed of studying music, now worked long hours in a shop for a meager wage.", "پس‌انداز تقریباً تمام شده بود، سلامت پدر رو به وخامت بود، آسم مادر بدتر می‌شد و خواهر که زمانی رؤیای تحصیل موسیقی را داشت، حالا ساعات طولانی در مغازه‌ای برای دستمزدی اندک کار می‌کرد."),
                    StoryParagraph("The lodgers had become the primary source of income, and the family had to be constantly careful not to offend them, because if they left, the family would be ruined.", "مستأجرها به منبع اصلی درآمد تبدیل شده بودند و خانواده باید مدام مراقب می‌بود که آن‌ها را نرنجاند، چون اگر می‌رفتند، خانواده نابود می‌شد."),
                    StoryParagraph("Gregor, listening to all this from his room, felt the weight of his uselessness pressing down upon him like a physical force.", "گرگور که همه این‌ها را از اتاقش می‌شنید، وزن بی‌فایده بودنش را مثل نیرویی جسمی روی خودش حس می‌کرد."),
                    StoryParagraph("He had once been the provider, the protector, the one who made everything possible, and now he was the reason for everything that was going wrong.", "او زمانی نان‌آور، محافظ، کسی که همه چیز را ممکن می‌کرد بود و حالا دلیل هر چیزی بود که اشتباه پیش می‌رفت."),
                    StoryParagraph("His sister, who had once been his closest ally, began to neglect him, bringing his food less frequently, cleaning his room less thoroughly, spending more and more time away from home.", "خواهرش که زمانی نزدیک‌ترین همپیمانش بود، شروع کرد به غفلت از او، غذایش را کمتر می‌آورد، اتاقش را کمتر تمیز می‌کرد و وقت بیشتری دور از خانه می‌گذراند."),
                    StoryParagraph("She had become a young woman, and she had begun to have her own life, her own friends, her own dreams, and Gregor, in his insect state, could not be part of any of it.", "او زن جوانی شده بود و شروع کرده بود زندگی خودش را داشته باشد، دوستان خودش، رؤیاهای خودش و گرگور در وضعیت حشره‌ای‌اش نمی‌توانست بخشی از هیچ‌کدام باشد."),
                    StoryParagraph("She still cared for him, in her own way, but the care had become a duty rather than a love, and Gregor could feel the difference.", "او هنوز به شیوه خودش اهمیت می‌داد، اما این اهمیت به وظیفه‌ای تبدیل شده بود نه عشقی و گرگور می‌توانست تفاوت را حس کند."),
                    StoryParagraph("His mother, who had briefly tried to visit him, had given up, because the sight of her transformed son was too much for her to bear.", "مادرش که لحظه‌ای تلاش کرده بود به دیدنش برود، دست کشیده بود، چون دیدن پسر دگردیسی‌یافته‌اش برایش بیش از حد تحمل‌پذیر بود."),
                    StoryParagraph("His father, who had never been close to him, now regarded him as a monster, a curse, a punishment from God for some unknown sin.", "پدرش که هرگز به او نزدیک نبود، حالا او را مثل هیولایی می‌دید، نفرینی، مجازاتی از خدا برای گناهی ناشناخته."),
                    StoryParagraph("One day, the father, in a fit of rage, began to throw apples at Gregor, and one of them struck him in the back and lodged there.", "یک روز، پدرش در حمله‌ای از خشم، شروع کرد به پرت کردن سیب به سمت گرگور و یکی از آن‌ها به پشتش خورد و آنجا فرو رفت."),
                    StoryParagraph("Gregor fled to his room, and the apple remained embedded in his flesh, causing him terrible pain and slowly poisoning him from within.", "گرگور به اتاقش فرار کرد و سیب در گوشتش فرو رفته باقی ماند و دردی هولناک ایجاد کرد و آهسته از درون مسمومش می‌کرد."),
                    StoryParagraph("No one tried to remove the apple, because no one wanted to touch him, and so it stayed there, a constant reminder of his father's hatred and his own helplessness.", "هیچ‌کس تلاش نکرد سیب را بردارد، چون هیچ‌کس نمی‌خواست لمسش کند و بنابراین آنجا ماند، یادآوری دائمی از نفرت پدرش و درماندگی خودش."),
                    StoryParagraph("The wound became infected, and Gregor's health, which had already been declining, began to fail rapidly.", "زخم عفونی شد و سلامت گرگور که از قبل رو به زوال بود، شروع کرد به سرعت تحلیل رفتن."),
                    StoryParagraph("He stopped eating almost completely, stopped moving except when absolutely necessary, and spent nearly all his time hidden beneath the sofa, waiting for something he could not name.", "او تقریباً به طور کامل از خوردن دست کشید، از حرکت کردن دست کشید جز وقتی مطلقاً لازم بود و تقریباً تمام وقتش را زیر مبل پنهان می‌گذراند، منتظر چیزی که نمی‌توانست نامش را ببرد."),
                    StoryParagraph("One day, the lodgers, who had noticed strange things about the house, gave notice that they were leaving.", "یک روز، مستأجرها که چیزهای عجیبی درباره خانه متوجه شده بودند، اعلام کردند می‌روند."),
                    StoryParagraph("The family, desperate to keep them, tried to please them, tried to make their stay more comfortable, but the lodgers had already decided.", "خانواده که ناامیدانه تلاش می‌کرد نگهشان دارد، سعی کرد راضیشان کند، سعی کرد اقامتشان را راحت‌تر کند، اما مستأجرها از قبل تصمیم گرفته بودند."),
                    StoryParagraph("And then, on the very evening they were supposed to leave, the sister, playing her violin to entertain them, drew Gregor out of his room.", "و بعد، در همان شبی که قرار بود بروند، خواهرش که برای سرگرم کردنشان ویولن می‌نواخت، گرگور را از اتاقش بیرون کشید."),
                    StoryParagraph("The lodgers, seeing the monstrous creature, were horrified, and they announced that they would leave immediately and would not pay for their stay.", "مستأجرها با دیدن موجود هیولایی وحشت کردند و اعلام کردند که فوراً می‌روند و برای اقامتشان پول نمی‌دهند."),
                    StoryParagraph("The father, enraged, attacked Gregor and drove him back into his room, and the sister, in tears, cried out that they must get rid of him.", "پدر خشمگین به گرگور حمله کرد و به اتاقش عقبش راند و خواهرش گریان فریاد کشید که باید از شرش خلاص شوند."),
                    StoryParagraph("'We must try to get rid of it,' she said. 'We have to try to take care of ourselves.'", "گفت: «باید تلاش کنیم از شرش خلاص شویم. باید تلاش کنیم از خودمان مراقبت کنیم.»"),
                    StoryParagraph("'It is not our brother anymore,' she said. 'It is a creature that must be destroyed.'", "گفت: «دیگر برادرمان نیست. موجودی است که باید نابود شود.»"),
                    StoryParagraph("Gregor, lying in his room, heard every word, and he knew, in that moment, that he had lost everything, that his family had abandoned him completely, that the love they had once felt for him was gone forever.", "گرگور که در اتاقش دراز کشیده بود، هر کلمه را شنید و در آن لحظه دانست که همه چیز را از دست داده، که خانواده‌اش کاملاً رهایش کرده‌اند، که عشقی که زمانی برایش حس می‌کردند برای همیشه رفته است."),
                    StoryParagraph("He did not blame them, because he understood, in a way that only the truly abandoned can understand, that they had no choice, that he had become a burden too heavy to bear.", "او سرزنششان نکرد، چون به شکلی که فقط رهاشدگان واقعی می‌فهمند می‌فهمید که آن‌ها انتخاب دیگری نداشتند، که او باری بیش از حد سنگین برای تحمل شده بود."),
                    StoryParagraph("He retreated under the sofa and lay there in the darkness, and he began to think about death, not with fear, but with a kind of quiet longing, a longing for peace, for release, for the end of suffering.", "او زیر مبل عقب‌نشینی کرد و در تاریکی دراز کشید و شروع کرد به فکر کردن درباره مرگ، نه با ترس، بلکه با نوعی اشتیاق آرام، اشتیاقی برای صلح، برای رهایی، برای پایان رنج."),
                    StoryParagraph("He thought about his family, about the sacrifices they had made for him, about the suffering he had caused, and he decided that the best thing he could do for them was to die.", "به خانواده‌اش فکر کرد، به فداکاری‌هایی که برایش کرده بودند، به رنجی که ایجاد کرده بود و تصمیم گرفت بهترین کاری که می‌تواند برایشان بکند این است که بمیرد."),
                    StoryParagraph("And so, one night, in the silence and darkness, Gregor Samsa made peace with his death, and he closed his eyes, and he waited for the end.", "و اینگونه، یک شب، در سکوت و تاریکی، گرگور سامسا با مرگش صلح کرد و چشمانش را بست و منتظر پایان ماند."),
                    StoryParagraph("The end came in the early morning, when his head sank to the floor of its own accord, and his last breath left him without any struggle, without any pain, without any fear.", "پایان در صبح زود آمد، وقتی سرش به‌خودی‌خود روی زمین فرود آمد و آخرین نفسش بدون هیچ تقلا، بدون هیچ درد، بدون هیچ ترسی ترکش کرد."),
                    StoryParagraph("Gregor Samsa, who had once been a human being, who had once loved and been loved, who had once been a son and a brother, died alone in a room that had become his prison.", "گرگور سامسا، که زمانی انسان بود، که زمانی عشق ورزیده بود و دوستش داشته بودند، که زمانی پسر و برادر بود، تنهای تنها در اتاقی که به زندانش تبدیل شده بود مرد."),
                    StoryParagraph("And no one, in all the world, wept for him, because no one, in all the world, remembered that he had ever truly lived.", "و هیچ‌کس، در تمام دنیا، برایش گریه نکرد، چون هیچ‌کس، در تمام دنیا، به یاد نداشت که او هرگز واقعاً زندگی کرده بود.")
                )
            ),
            StoryChapter(
                number = 4, title = "Gregor's Death", titlePersian = "مرگ گرگور",
                paragraphs = listOf(
                    StoryParagraph("The morning after Gregor's death, the cleaning lady, who came to the apartment early each day, noticed that something was different in the room where the creature lived.", "صبح بعد از مرگ گرگور، زن نظافتچی که هر روز زود به آپارتمان می‌آمد، متوجه شد چیزی در اتاقی که موجود در آن زندگی می‌کرد متفاوت است."),
                    StoryParagraph("She opened the door cautiously, as she always did, and she saw the shriveled, lifeless body lying on the floor, dry and flat and utterly motionless.", "او با احتیاط در را باز کرد، همان‌طور که همیشه می‌کرد و جسد خشکیده و بی‌جان را روی زمین دید که خشک و تخت و کاملاً بی‌حرکت بود."),
                    StoryParagraph("She poked it with her broom, and when it did not move, she knew that the creature was finally dead, and she let out a long, satisfied whistle.", "با جارویش آن را تکان داد و وقتی حرکت نکرد، دانست که موجود بالاخره مرده است و سوت طولانی و رضایت‌بخشی کشید."),
                    StoryParagraph("She went to the family, who were still asleep, and she told them, in a loud, cheerful voice, that the thing in the room had died during the night.", "او به سراغ خانواده رفت که هنوز خواب بودند و با صدای بلند و شادمانه به آن‌ها گفت که آن چیز در اتاق در طول شب مرده است."),
                    StoryParagraph("The father sat up in bed, crossed himself, and said, 'Thank God.'", "پدر در تخت نشست، صلیب کشید و گفت: «خدا را شکر.»"),
                    StoryParagraph("The mother, who had not slept well for months, looked at her husband with a mixture of relief and guilt, and she too whispered a prayer of thanks.", "مادر که ماه‌ها خوب نخوابیده بود، با آمیزه‌ای از آسودگی و گناه به شوهرش نگاه کرد و او هم دعای تشکری زمزمه کرد."),
                    StoryParagraph("The sister, who had been the last to abandon hope, did not say anything; she simply got out of bed, dressed herself, and went to look at the body of her brother.", "خواهر که آخرین کسی بود که امید را رها کرد، چیزی نگفت؛ فقط از تخت بیرون آمد، لباس پوشید و رفت جسد برادرش را ببیند."),
                    StoryParagraph("She stood in the doorway for a long moment, looking at the flat, dry shape on the floor, and she felt, at last, that she could feel something again.", "لحظه‌ای طولانی در چارچوب در ایستاد و به شکل تخت و خشک روی زمین نگاه کرد و در نهایت حس کرد می‌تواند دوباره چیزی حس کند."),
                    StoryParagraph("But what she felt was not grief, not exactly, and it was not love, not anymore, but a strange, hollow emptiness, as though something that had been pressing on her heart for months had finally been removed.", "اما چیزی که حس می‌کرد غم نبود، دقیقاً، و عشق نبود، دیگر نه، بلکه خالی‌بودنی عجیب و توخالی بود، گویی چیزی که ماه‌ها روی قلبش فشار می‌آورد بالاخره برداشته شده بود."),
                    StoryParagraph("She turned away and went to join her parents in the living room, and the three of them sat together for a long time without speaking, each lost in their own thoughts.", "رو برگرداند و به نشیمن رفت تا به والدینش بپیوندد و هر سه مدت طولانی بدون حرف زدن با هم نشستند، هر کدام غرق افکار خودش."),
                    StoryParagraph("'We should get rid of it,' the father said finally, breaking the silence. 'It has to be done.'", "پدر بالاخره سکوت را شکست و گفت: «باید از شرش خلاص شویم. باید انجام شود.»"),
                    StoryParagraph("The mother nodded, and the sister, after a moment's hesitation, nodded too, and no one objected, no one suggested a funeral, no one proposed a burial.", "مادر سر تکان داد و خواهر بعد از لحظه‌ای تردید، او هم سر تکان داد و هیچ‌کس مخالفت نکرد، هیچ‌کس پیشنهاد مراسم خاکسپاری نداد، هیچ‌کس پیشنهاد دفن نکرد."),
                    StoryParagraph("Gregor was a creature, not a person, and creatures were not buried; they were disposed of, like garbage, like something that had never really existed.", "گرگور موجودی بود، نه یک شخص و موجودات را دفن نمی‌کردند؛ آن‌ها را دور می‌انداختند، مثل آشغال، مثل چیزی که هرگز واقعاً وجود نداشته."),
                    StoryParagraph("The cleaning lady was given the task, and she dragged the body out of the apartment, and she threw it into the trash bin behind the building, and she did not look back.", "وظیفه به زن نظافتچی داده شد و او جسد را از آپارتمان بیرون کشید و در سطل زباله پشت ساختمان انداخت و به عقب نگاه نکرد."),
                    StoryParagraph("And so Gregor Samsa, who had once been a human being with a name and a soul and a heart, was reduced to garbage, discarded in the trash, forgotten forever.", "و اینگونه گرگور سامسا، که زمانی انسانی با نام و روح و قلب بود، به زباله تبدیل شد، در سطل آشغال دور انداخته شد، برای همیشه فراموش شد."),
                    StoryParagraph("The family, meanwhile, began to plan for their future, a future that no longer included their son and brother.", "خانواده در همین حال، شروع کرد به برنامه‌ریزی برای آینده‌شان، آینده‌ای که دیگر شامل پسر و برادرشان نمی‌شد."),
                    StoryParagraph("They decided to move to a smaller apartment, one that they could afford, one that did not contain the room where the creature had lived.", "تصمیم گرفتند به آپارتمانی کوچک‌تر نقل مکان کنند، آپارتمانی که بتوانند بپردازند، آپارتمانی که اتاقی که موجود در آن زندگی کرده بود را نداشته باشد."),
                    StoryParagraph("The father, who had recovered some of his old strength, found work as a bank messenger, and he wore his uniform proudly, as though he had finally become a useful member of society again.", "پدر که مقداری از قدرتش را بازیافته بود، به‌عنوان پیک بانکی کار پیدا کرد و یونیفرمش را با افتخار می‌پوشید، گویی بالاخره دوباره عضو مفید جامعه شده بود."),
                    StoryParagraph("The mother, whose asthma had improved, took in more sewing work, and she began to smile again, for the first time in months.", "مادر که آسمش بهتر شده بود، کار خیاطی بیشتری گرفت و برای اولین بار در ماه‌ها، دوباره شروع کرد به لبخند زدن."),
                    StoryParagraph("The sister, who had once dreamed of studying music, had given up that dream, but she had found a new one: she wanted to work, to earn money, to be independent, to build a life for herself.", "خواهر که زمانی رؤیای تحصیل موسیقی را داشت، آن رؤیا را رها کرده بود، اما رؤیای جدیدی یافته بود: می‌خواست کار کند، پول دربیاورد، مستقل باشد، زندگی‌ای برای خودش بسازد."),
                    StoryParagraph("One Sunday, the three of them decided to take a day off from work and to go for a walk in the countryside, away from the city, away from the memories.", "یک یکشنبه، هر سه تصمیم گرفتند از کار مرخصی بگیرند و برای قدم زدن به حومه شهر بروند، دور از شهر، دور از خاطرات."),
                    StoryParagraph("The weather was beautiful, the sun was warm, and the trees were in bloom, and as they walked together, they talked about their plans for the future.", "هوا زیبا بود، خورشید گرم بود و درختان شکوفا بودند و همان‌طور که با هم قدم می‌زدند، درباره نقشه‌هایشان برای آینده صحبت کردند."),
                    StoryParagraph("The parents looked at their daughter, who had grown into a strong, capable young woman, and they realized, with a mixture of pride and hope, that she was ready to be married.", "والدین به دخترشان نگاه کردند که به زن جوانی قوی و توانمند تبدیل شده بود و با آمیزه‌ای از غرور و امید دریافتند که آماده ازدواج است."),
                    StoryParagraph("And as the tram carried them back to the city, back to their new apartment, back to their new life, they felt, for the first time in a long time, that the future was bright, that there was hope again, that happiness was possible.", "و همان‌طور که تراموا آن‌ها را به شهر برگرداند، به آپارتمان جدیدشان، به زندگی جدیدشان، برای اولین بار در مدت طولانی حس کردند که آینده روشن است، دوباره امیدی هست، خوشبختی ممکن است."),
                    StoryParagraph("They did not speak of Gregor; they did not mention his name; they did not think, consciously at least, about the son and brother they had lost.", "آن‌ها از گرگور صحبت نکردند؛ نامش را نبردند؛ آگاهانه حداقل، به پسر و برادری که از دست داده بودند فکر نکردند."),
                    StoryParagraph("But somewhere, in the deepest part of their hearts, in the place where no words could reach, the memory of him remained, and it would remain forever, a silent ghost that haunted every moment of happiness.", "اما جایی، در عمیق‌ترین بخش قلبشان، در جایی که هیچ کلمه‌ای نمی‌تواند برسد، خاطره‌اش باقی ماند و برای همیشه باقی می‌ماند، شبحی خاموش که هر لحظه از خوشبختی را تسخیر می‌کرد."),
                    StoryParagraph("For Gregor Samsa had been a human being, had loved and been loved, had sacrificed for his family, had been the best of them in many ways.", "زیرا گرگور سامسا انسانی بوده بود، عشق ورزیده بود و دوستش داشته بودند، برای خانواده‌اش فداکاری کرده بود، از بسیاری جهات بهترینشان بوده بود."),
                    StoryParagraph("And yet, when he had needed them most, when he had been at his most vulnerable, they had abandoned him, not because they were evil, but because they were human, because they could not bear the weight of a suffering they could not understand.", "و با این حال، وقتی بیش از هر زمان به آن‌ها نیاز داشت، وقتی در آسیب‌پذیرترین حالتش بود، آن‌ها رهایش کردند، نه چون شرور بودند، بلکه چون انسان بودند، چون نمی‌توانستند وزن رنجی که نمی‌فهمیدند را تحمل کنند."),
                    StoryParagraph("This was Kafka's vision: that the modern world had made us incapable of love, incapable of compassion, incapable of seeing the humanity in those who are different from us.", "این رؤیای کافکا بود: که دنیای مدرن ما را ناتوان از عشق کرده، ناتوان از شفقت، ناتوان از دیدن انسانیت در کسانی که با ما متفاوتند."),
                    StoryParagraph("Gregor's transformation was not the tragedy; the tragedy was that, even before he became an insect, he had already been isolated, already been alienated, already been alone.", "دگردیسی گرگور تراژدی نبود؛ تراژدی این بود که حتی قبل از اینکه حشره شود، از قبل منزوی بود، از قبل بیگانه بود، از قبل تنها بود."),
                    StoryParagraph("His metamorphosis was merely the physical manifestation of a spiritual transformation that had been taking place in him for years, a slow turning away from humanity, a slow descent into the solitude of the exploited.", "دگردیسی‌اش صرفاً تجلی فیزیکی دگردیسی معنوی‌ای بود که سال‌ها در او رخ می‌داد، فاصله‌گیری آهسته از بشریت، نزولی آرام به تنهایی استثمارشدگان."),
                    StoryParagraph("And so his death was not really a death, but a continuation of a process that had begun long before, a process that the modern world, with its coldness and its cruelty and its endless demands, had made inevitable.", "و بنابراین مرگش واقعاً مرگ نبود، بلکه ادامه فرآیندی بود که خیلی قبل‌تر آغاز شده بود، فرآیندی که دنیای مدرن، با سردی و بی‌رحمی و خواسته‌های بی‌پایانش، اجتناب‌ناپذیر کرده بود."),
                    StoryParagraph("Gregor Samsa was the first, but he would not be the last, and as long as there are families who cannot bear the weight of their own children, as long as there are societies that discard those who are different, as long as there are hearts that cannot love the unlovable, his story will continue to be told.", "گرگور سامسا اولین بود، اما آخرین نمی‌بود و تا وقتی خانواده‌هایی هستند که نمی‌توانند وزن فرزندان خودشان را تحمل کنند، تا وقتی جوامعی هستند که متفاوت‌ها را دور می‌اندازند، تا وقتی قلب‌هایی هستند که نمی‌توانند نادوست‌داشتنی‌ها را دوست داشته باشند، داستانش گفته خواهد شد.")
                )
            ),
            StoryChapter(
                number = 5, title = "A New Beginning", titlePersian = "شروع جدید",
                paragraphs = listOf(
                    StoryParagraph("In the weeks that followed Gregor's death, the family's life began to change in ways both subtle and profound.", "در هفته‌های پس از مرگ گرگور، زندگی خانواده به روش‌هایی هم ظریف و هم عمیق شروع به تغییر کرد."),
                    StoryParagraph("They moved to a smaller apartment, in a different part of the city, where no one knew them and where no one would ask questions about the son who was no longer mentioned.", "آن‌ها به آپارتمانی کوچک‌تر در قسمت دیگری از شهر نقل مکان کردند، جایی که هیچ‌کس نمی‌شناختشان و هیچ‌کس درباره پسر که دیگر نامی از او برده نمی‌شد سؤال نمی‌پرسید."),
                    StoryParagraph("The new apartment was clean and bright, with windows that looked out onto a small garden, and the mother, who had not been able to sleep for months, found that she could finally rest.", "آپارتمان جدید تمیز و روشن بود، با پنجره‌هایی که به باغچه کوچکی نگاه می‌کردند و مادر که ماه‌ها نتوانسته بود بخوابد، دید که بالاخره می‌تواند استراحت کند."),
                    StoryParagraph("The father, who had aged a decade in a year, slowly regained his strength, and he began to take pride in his work as a bank messenger, in his uniform, in his new role as the head of the household.", "پدر که در یک سال یک دهه پیر شده بود، آهسته قدرتش را بازیافت و شروع کرد به افتخار کردن به کارش به‌عنوان پیک بانکی، به یونیفرمش، به نقش جدیدش به‌عنوان سرپرست خانه."),
                    StoryParagraph("The sister, who had been the most affected by the whole ordeal, changed the most.", "خواهر که بیشترین تأثیر را از تمام این ماجرا گرفته بود، بیشترین تغییر را کرد."),
                    StoryParagraph("She had been a girl when her brother transformed, a girl full of dreams and hopes and girlish fancies, and she had been forced, by the events that followed, to become a woman overnight.", "او وقتی برادرش دگردیس شد دختری بود، دختری پر از رؤیا و امید و خیالات دخترانه و مجبور شده بود، توسط اتفاقاتی که پس آمد، یک‌شبه زن شود."),
                    StoryParagraph("She had taken care of the creature that her brother had become, had watched him die, had helped dispose of his body, had pretended, for the sake of her parents, that nothing had happened.", "او از موجودی که برادرش شده بود مراقبت کرده بود، تماشا کرده بود که می‌میرد، کمک کرده بود جسدش را دور بیندازند، برای خاطر والدینش تظاهر کرده بود که هیچ اتفاقی نیفتاده است."),
                    StoryParagraph("And now, in the new apartment, she began to blossom, to grow, to become the person she had always wanted to be, the person her brother, perhaps, would have wanted her to be.", "و حالا، در آپارتمان جدید، شروع کرد به شکوفا شدن، به رشد کردن، به تبدیل شدن به شخصی که همیشه می‌خواست باشد، شخصی که برادرش، شاید، می‌خواست باشد."),
                    StoryParagraph("She had taken a job in a shop, and she had discovered that she was good at it, that she had a talent for business, that she could earn her own money and support herself.", "او شغلی در مغازه‌ای گرفته بود و کشف کرده بود که در آن خوب است، استعدادی برای تجارت دارد، می‌تواند پول خودش را دربیاورد و از خودش حمایت کند."),
                    StoryParagraph("She had made friends, real friends, not the shallow acquaintances of childhood, but friends who shared her interests, who understood her, who accepted her for who she was.", "او دوستانی پیدا کرده بود، دوستان واقعی، نه آشنایان سطحی کودکی، بلکه دوستانی که علایقش را شریک بودند، که درکش می‌کردند، که همان‌طور که بود می‌پذیرفتندش."),
                    StoryParagraph("And she had begun to think about love, about marriage, about a family of her own, not the broken family she had grown up in, but a family she would build, a family that would not fall apart.", "و شروع کرده بود به فکر کردن درباره عشق، درباره ازدواج، درباره خانواده‌ای از خودش، نه خانواده شکسته‌ای که در آن بزرگ شده بود، بلکه خانواده‌ای که خودش می‌ساخت، خانواده‌ای که از هم نمی‌پاشید."),
                    StoryParagraph("Her parents noticed the change, and they were proud of her, in a way that was complicated by the knowledge that their other child, the one who had made this new life possible, was dead.", "والدینش تغییر را متوجه شدند و به او افتخار کردند، به شکلی که با آگاهی به اینکه فرزند دیگرشان، همان که این زندگی جدید را ممکن کرده بود، مرده است پیچیده شده بود."),
                    StoryParagraph("They did not speak of Gregor, not because they had forgotten him, but because they could not bear to remember, because remembering meant facing the truth of what they had done.", "آن‌ها از گرگور صحبت نمی‌کردند، نه چون فراموشش کرده بودند، بلکه چون نمی‌توانستند تحمل کنند به یادش آورند، چون به یاد آوردن یعنی مواجه شدن با حقیقت کاری که کرده بودند."),
                    StoryParagraph("They had abandoned their son, their own flesh and blood, in his hour of greatest need, and this knowledge was too heavy to bear, so they buried it, like they had buried him, in the depths of their hearts.", "آن‌ها پسرشان، خون خودشان را، در ساعت بیشترین نیازش رها کرده بودند و این آگاهی برای تحمل بیش از حد سنگین بود، پس دفنش کردند، مثل خودش، در اعماق قلبشان."),
                    StoryParagraph("One evening, as the family sat together in their new living room, the father looked at his daughter and smiled.", "یک عصر، وقتی خانواده با هم در نشیمن جدیدشان نشسته بودند، پدر به دخترش نگاه کرد و لبخند زد."),
                    StoryParagraph("'You have become a beautiful young woman,' he said. 'Your mother and I are very proud of you.'", "گفت: «تو زن جوان زیبایی شده‌ای. من و مادرت خیلی به تو افتخار می‌کنیم.»"),
                    StoryParagraph("The mother nodded, and her eyes filled with tears, but they were tears of happiness, not sorrow, tears of hope, not regret.", "مادر سر تکان داد و چشمانش پر از اشک شد، اما اشک شادی بود، نه اندوه، اشک امید بود، نه پشیمانی."),
                    StoryParagraph("The sister smiled at her parents, and she felt, in that moment, that despite everything that had happened, despite the pain and the loss and the guilt, life was still worth living.", "خواهر به والدینش لبخند زد و در آن لحظه حس کرد که با وجود هر چیزی که اتفاق افتاده، با وجود درد و فقدان و گناه، زندگی هنوز ارزش زیستن را دارد."),
                    StoryParagraph("And so the story of Gregor Samsa ended, not with his death, which was only a moment, but with the continuation of life, which is eternal.", "و اینگونه داستان گرگور سامسا پایان یافت، نه با مرگش که فقط لحظه‌ای بود، بلکه با تداوم زندگی که ابدی است."),
                    StoryParagraph("His family had survived, had moved on, had found happiness again, and this, perhaps, was the most tragic thing of all: that life could continue without him, that the world could keep spinning, that the sun could keep shining, as though he had never existed.", "خانواده‌اش زنده مانده بودند، پیش رفته بودند، دوباره خوشبختی یافته بودند و این، شاید، تراژیک‌ترین چیز از همه بود: که زندگی می‌توانست بدون او ادامه یابد، که دنیا می‌توانست بچرخد، که خورشید می‌توانست بتابد، گویی هرگز وجود نداشته است."),
                    StoryParagraph("But this is the truth that Kafka wanted us to see: that we are all Gregor Samsa, that we are all, at some point, transformed into something that our families and our societies cannot accept.", "اما این حقیقتی است که کافکا می‌خواست ما ببینیم: که همه ما گرگور سامسا هستیم، که همه ما، در نقطه‌ای، به چیزی تبدیل می‌شویم که خانواده‌ها و جوامعمان نمی‌توانند بپذیرند."),
                    StoryParagraph("We are all, in our own ways, monsters that must be hidden, burdens that must be borne, creatures that must be tolerated until we can be discarded.", "همه ما، به شیوه‌های خودمان، هیولاهایی هستیم که باید پنهان شوند، بارهایی که باید حمل شوند، موجوداتی که باید تحمل شوند تا وقتی بتوان دور انداختیمان."),
                    StoryParagraph("And we are all, at the same time, the family that does the discarding, the society that does the rejecting, the heart that cannot love the unlovable.", "و در همان زمان، همه ما خانواده‌ای هستیم که دور می‌اندازد، جامعه‌ای که طرد می‌کند، قلبی که نمی‌تواند نادوست‌داشتنی‌ها را دوست داشته باشد."),
                    StoryParagraph("The story of Gregor Samsa is not just the story of a man who became an insect; it is the story of the human condition, of the impossibility of love in a world that has made love impossible.", "داستان گرگور سامسا فقط داستان مردی نیست که حشره شد؛ داستان وضعیت انسانی است، غیرممکن بودن عشق در دنیایی که عشق را غیرممکن کرده است."),
                    StoryParagraph("Kafka wrote this story over a hundred years ago, and yet it feels more relevant today than ever, in a world where millions of people feel just as isolated, just as alienated, just as unloved as Gregor Samsa felt.", "کافکا این داستان را بیش از صد سال پیش نوشت و با این حال، امروز بیشتر از هر زمان دیگری مرتبط حس می‌شود، در دنیایی که میلیون‌ها نفر همانقدر تنها، همانقدر بیگانه، همانقدر نادوست‌داشته حس می‌کنند که گرگور سامسا حس می‌کرد."),
                    StoryParagraph("And so his story continues, not just on the page, but in the lives of every person who has ever felt that they did not belong, who has ever been abandoned by those they loved, who has ever wondered what it means to be human.", "و اینگونه داستانش ادامه دارد، نه فقط روی صفحه، بلکه در زندگی هر شخصی که زمانی حس کرده به جایی تعلق ندارد، که زمانی توسط کسانی که دوستشان داشت رها شده، که زمانی پرسیده انسان بودن یعنی چه."),
                    StoryParagraph("Gregor Samsa lives on, in each of us, in every moment of loneliness, in every act of abandonment, in every failure of love.", "گرگور سامسا زنده می‌ماند، در هر یک از ما، در هر لحظه از تنهایی، در هر عمل رها کردن، در هر شکست عشق."),
                    StoryParagraph("And his death, his final, quiet, unnoticed death, is a reminder of what happens when we forget that we are all human, when we forget that we all need love, when we forget that we all deserve to be seen.", "و مرگش، مرگ نهایی، آرام، نادیده‌اش، یادآوری‌ای است از آنچه اتفاق می‌افتد وقتی فراموش می‌کنیم که همه ما انسانیم، وقتی فراموش می‌کنیم که همه ما به عشق نیاز داریم، وقتی فراموش می‌کنیم که همه ما سزاوار دیده شدنیم."),
                    StoryParagraph("This is the final lesson of Gregor Samsa's life and death: that in every monster, there is a human being, and that in every human being, there is the potential to become a monster, and that the only way to save us all is to learn to see, and to love, and to accept, no matter how difficult that may be.", "این درس نهایی زندگی و مرگ گرگور سامسا است: که در هر هیولایی، انسانی هست و در هر انسانی، پتانسیل تبدیل شدن به هیولا هست و تنها راه نجات همه ما یادگیری دیدن، عشق ورزیدن و پذیرفتن است، هر چقدر هم دشوار باشد."),
                    StoryParagraph("The end.", "پایان.")
                )
            )
        )
    )
}